function renderCommunityCategories() {
  const board = $("#community-category-grid");
  if (!board) return;
  const topicItems = publicCatalog?.taxonomy?.topics?.length
    ? publicCatalog.taxonomy.topics
    : [...new Set(posts.map((post) => post.topic))].map((topic) => {
      const sample = posts.find((post) => post.topic === topic);
      return { id: topic, name: lang === "zh" ? sample.zhTopic : topic };
    });
  board.innerHTML = `
    <p>${t("allTopics")}</p>
    <div class="gallery-category-row">
      <button class="${activeCommunityCategory === "all" ? "active" : ""}" data-community-category="all">${t("allTopics")}</button>
      ${topicItems.map((item) => `
        <button class="${activeCommunityCategory === categoryValue(item) ? "active" : ""}" data-community-category="${categoryValue(item)}">${item.name || item.id}</button>
      `).join("")}
    </div>
  `;
}

function renderPosts() {
  renderCommunityCategories();
  let visible = communityItems().filter((post) => activeCommunityCategory === "all" || itemMatchesCategory(post, activeCommunityCategory) || post.topic === activeCommunityCategory);
  visible = visible.sort((a, b) => postSort === "hot" ? b.hot - a.hot : new Date(b.date) - new Date(a.date));
  $("#post-list").innerHTML = visible.map((post) => `
    <article class="post-card">
      <div>
        <span class="tag">${lang === "zh" ? post.zhTopic : post.topic}</span>
        <h4>${local(post, "title", "zhTitle")}</h4>
        <p class="meta">${post.user} · ${post.date}</p>
      </div>
      <div class="meta">${post.hot} ${t("like")} · ${t("comment")}</div>
    </article>
  `).join("") || `<p class="muted">${lang === "zh" ? "没有找到匹配帖子。" : "No matching posts."}</p>`;
}

