function loadAiPreviewImage(src) {
  return new Promise((resolve, reject) => {
    if (!src) {
      reject(new Error("Missing image source."));
      return;
    }
    const image = new Image();
    if (/^https?:\/\//i.test(src)) image.crossOrigin = "anonymous";
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Image failed to load."));
    image.src = src;
  });
}

async function composeAiHandPreview(nailImages) {
  const images = nailImages.filter(Boolean).slice(0, 5);
  if (!images.length) return "";
  try {
    const [hand, ...nails] = await Promise.all([
      loadAiPreviewImage("assets/hand-preview-base.jpg"),
      ...images.map((src) => loadAiPreviewImage(src)),
    ]);
    const canvas = document.createElement("canvas");
    canvas.width = hand.naturalWidth || hand.width;
    canvas.height = hand.naturalHeight || hand.height;
    const context = canvas.getContext("2d");
    context.drawImage(hand, 0, 0, canvas.width, canvas.height);
    const placements = [
      {
        label: "leftmost",
        width: 58,
        height: 146,
        quad: [{ x: 957, y: 430 }, { x: 1007, y: 420 }, { x: 1028, y: 543 }, { x: 976, y: 557 }],
      },
      {
        label: "second",
        width: 66,
        height: 162,
        quad: [{ x: 1307, y: 257 }, { x: 1368, y: 247 }, { x: 1387, y: 389 }, { x: 1320, y: 406 }],
      },
      {
        label: "middle",
        width: 68,
        height: 185,
        quad: [{ x: 1488, y: 122 }, { x: 1546, y: 122 }, { x: 1559, y: 306 }, { x: 1502, y: 315 }],
      },
      {
        label: "fourth",
        width: 66,
        height: 175,
        quad: [{ x: 1684, y: 176 }, { x: 1740, y: 177 }, { x: 1755, y: 350 }, { x: 1698, y: 363 }],
      },
      {
        label: "rightmost-thumb",
        width: 92,
        height: 202,
        quad: [{ x: 1920, y: 850 }, { x: 2095, y: 760 }, { x: 2140, y: 835 }, { x: 1975, y: 940 }],
      },
    ];
    nails.forEach((nail, index) => {
      drawAiNailOnHand(context, nail, placements[index]);
    });
    return canvas.toDataURL("image/jpeg", 0.92);
  } catch (error) {
    console.warn("AI hand preview compose failed", error);
    return "";
  }
}

function drawAiNailOnHand(context, image, placement) {
  if (!placement) return;
  const patch = document.createElement("canvas");
  patch.width = Math.max(1, Math.round(placement.width * 4));
  patch.height = Math.max(1, Math.round(placement.height * 4));
  const patchContext = patch.getContext("2d");
  patchContext.save();
  applyAiNailPreviewClip(patchContext, patch.width, patch.height);
  const source = aiImageContentBounds(image);
  const scale = Math.max(patch.width / source.width, patch.height / source.height);
  const drawWidth = source.width * scale;
  const drawHeight = source.height * scale;
  patchContext.drawImage(
    image,
    source.x,
    source.y,
    source.width,
    source.height,
    (patch.width - drawWidth) / 2,
    (patch.height - drawHeight) / 2,
    drawWidth,
    drawHeight,
  );
  const shine = patchContext.createLinearGradient(0, 0, patch.width, patch.height);
  shine.addColorStop(0, "rgba(255,255,255,0.42)");
  shine.addColorStop(0.42, "rgba(255,255,255,0.06)");
  shine.addColorStop(1, "rgba(60,35,45,0.16)");
  patchContext.fillStyle = shine;
  patchContext.fillRect(0, 0, patch.width, patch.height);
  patchContext.restore();

  context.save();
  context.globalAlpha = 0.9;
  drawImageOnQuad(context, patch, placement.quad);
  context.restore();
}

function aiImageContentBounds(image) {
  const canvas = document.createElement("canvas");
  canvas.width = image.naturalWidth || image.width;
  canvas.height = image.naturalHeight || image.height;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(image, 0, 0, canvas.width, canvas.height);
  let pixels;
  try {
    pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
  } catch (_) {
    return { x: 0, y: 0, width: canvas.width, height: canvas.height };
  }
  let minX = canvas.width;
  let minY = canvas.height;
  let maxX = 0;
  let maxY = 0;
  for (let y = 0; y < canvas.height; y += 1) {
    for (let x = 0; x < canvas.width; x += 1) {
      const index = (y * canvas.width + x) * 4;
      const r = pixels[index];
      const g = pixels[index + 1];
      const b = pixels[index + 2];
      const alpha = pixels[index + 3];
      const notWhite = !(r > 242 && g > 242 && b > 242);
      if (alpha > 18 && notWhite) {
        minX = Math.min(minX, x);
        minY = Math.min(minY, y);
        maxX = Math.max(maxX, x);
        maxY = Math.max(maxY, y);
      }
    }
  }
  if (minX > maxX || minY > maxY) return { x: 0, y: 0, width: canvas.width, height: canvas.height };
  const padding = Math.round(Math.max(canvas.width, canvas.height) * 0.04);
  return {
    x: Math.max(0, minX - padding),
    y: Math.max(0, minY - padding),
    width: Math.min(canvas.width, maxX + padding) - Math.max(0, minX - padding),
    height: Math.min(canvas.height, maxY + padding) - Math.max(0, minY - padding),
  };
}

function isPersonalDraft(design) {
  return design?.source === "personal" && (design.mode === "drafts" || design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID);
}

function transparentizeAiDesignImage(src) {
  return new Promise((resolve) => {
    if (!src) {
      resolve(src);
      return;
    }
    const image = new Image();
    if (/^https?:\/\//i.test(src)) image.crossOrigin = "anonymous";
    image.onerror = () => resolve(src);
    image.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = image.naturalWidth || image.width;
      canvas.height = image.naturalHeight || image.height;
      const context = canvas.getContext("2d", { willReadFrequently: true });
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      let imageData;
      try {
        imageData = context.getImageData(0, 0, canvas.width, canvas.height);
      } catch (_) {
        resolve(src);
        return;
      }
      const data = imageData.data;
      let removed = 0;
      for (let index = 0; index < data.length; index += 4) {
        const r = data[index];
        const g = data[index + 1];
        const b = data[index + 2];
        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const nearWhite = r > 236 && g > 236 && b > 236;
        const palePaper = max > 245 && max - min < 18;
        if (nearWhite || palePaper) {
          data[index + 3] = 0;
          removed += 1;
        }
      }
      if (!removed) {
        resolve(src);
        return;
      }
      context.putImageData(imageData, 0, 0);
      resolve(canvas.toDataURL("image/png"));
    };
    image.src = src;
  });
}

function drawImageOnQuad(context, image, quad) {
  if (!quad?.length || quad.length !== 4) return;
  const columns = 8;
  const rows = 16;
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const u0 = column / columns;
      const u1 = (column + 1) / columns;
      const v0 = row / rows;
      const v1 = (row + 1) / rows;
      const p00 = bilinearPoint(quad, u0, v0);
      const p10 = bilinearPoint(quad, u1, v0);
      const p01 = bilinearPoint(quad, u0, v1);
      const p11 = bilinearPoint(quad, u1, v1);
      const sx0 = u0 * image.width;
      const sx1 = u1 * image.width;
      const sy0 = v0 * image.height;
      const sy1 = v1 * image.height;
      drawTexturedTriangle(context, image, sx0, sy0, sx1, sy0, sx1, sy1, p00.x, p00.y, p10.x, p10.y, p11.x, p11.y);
      drawTexturedTriangle(context, image, sx0, sy0, sx1, sy1, sx0, sy1, p00.x, p00.y, p11.x, p11.y, p01.x, p01.y);
    }
  }
}

function bilinearPoint(quad, u, v) {
  const top = {
    x: quad[0].x + (quad[1].x - quad[0].x) * u,
    y: quad[0].y + (quad[1].y - quad[0].y) * u,
  };
  const bottom = {
    x: quad[3].x + (quad[2].x - quad[3].x) * u,
    y: quad[3].y + (quad[2].y - quad[3].y) * u,
  };
  return {
    x: top.x + (bottom.x - top.x) * v,
    y: top.y + (bottom.y - top.y) * v,
  };
}

function drawTexturedTriangle(context, image, sx0, sy0, sx1, sy1, sx2, sy2, dx0, dy0, dx1, dy1, dx2, dy2) {
  const denominator = sx0 * (sy1 - sy2) + sx1 * (sy2 - sy0) + sx2 * (sy0 - sy1);
  if (!denominator) return;
  const a = (dx0 * (sy1 - sy2) + dx1 * (sy2 - sy0) + dx2 * (sy0 - sy1)) / denominator;
  const b = (dy0 * (sy1 - sy2) + dy1 * (sy2 - sy0) + dy2 * (sy0 - sy1)) / denominator;
  const c = (dx0 * (sx2 - sx1) + dx1 * (sx0 - sx2) + dx2 * (sx1 - sx0)) / denominator;
  const d = (dy0 * (sx2 - sx1) + dy1 * (sx0 - sx2) + dy2 * (sx1 - sx0)) / denominator;
  const e = (dx0 * (sx1 * sy2 - sx2 * sy1) + dx1 * (sx2 * sy0 - sx0 * sy2) + dx2 * (sx0 * sy1 - sx1 * sy0)) / denominator;
  const f = (dy0 * (sx1 * sy2 - sx2 * sy1) + dy1 * (sx2 * sy0 - sx0 * sy2) + dy2 * (sx0 * sy1 - sx1 * sy0)) / denominator;

  context.save();
  context.beginPath();
  context.moveTo(dx0, dy0);
  context.lineTo(dx1, dy1);
  context.lineTo(dx2, dy2);
  context.closePath();
  context.clip();
  context.setTransform(a, b, c, d, e, f);
  context.drawImage(image, 0, 0);
  context.restore();
}

function applyAiNailPreviewClip(context, width, height) {
  context.beginPath();
  context.moveTo(width * 0.5, height * 0.02);
  context.bezierCurveTo(width * 0.86, height * 0.04, width * 0.95, height * 0.28, width * 0.9, height * 0.62);
  context.bezierCurveTo(width * 0.84, height * 0.86, width * 0.68, height * 0.98, width * 0.5, height * 0.99);
  context.bezierCurveTo(width * 0.32, height * 0.98, width * 0.16, height * 0.86, width * 0.1, height * 0.62);
  context.bezierCurveTo(width * 0.05, height * 0.28, width * 0.14, height * 0.04, width * 0.5, height * 0.02);
  context.closePath();
  context.clip();
}

function renderAiReferences() {
  const grid = $("#ai-reference-grid");
  if (!grid) return;
  const items = aiReferenceImages.slice(0, 3).map((image, index) => `
    <button type="button" class="ai-reference-thumb" data-ai-remove-ref="${index}" style="--ref-image:url('${image}')"></button>
  `).join("");
  const add = aiReferenceImages.length < 3 ? `<label class="ai-reference-add" for="ai-reference-input">+</label>` : "";
  grid.innerHTML = items + add;
}

function compressAiReferenceFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Unable to read reference image."));
    reader.onload = () => {
      const original = String(reader.result || "");
      const image = new Image();
      image.onerror = () => resolve(original);
      image.onload = () => {
        const maxSide = 900;
        const scale = Math.min(1, maxSide / Math.max(image.naturalWidth || image.width, image.naturalHeight || image.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round((image.naturalWidth || image.width) * scale));
        canvas.height = Math.max(1, Math.round((image.naturalHeight || image.height) * scale));
        const context = canvas.getContext("2d");
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", 0.76));
      };
      image.src = original;
    };
    reader.readAsDataURL(file);
  });
}

function toggleAiStyle(button) {
  const style = button.dataset.aiStyle;
  if (!style) return;
  button.classList.toggle("active");
  selectedAiStyles = $$("#ai-style-tags [data-ai-style].active").map((item) => item.dataset.aiStyle);
}

function currentNailReferenceImage() {
  return makeTemplateDataUrl({
    name: "Current nail base",
    thumb: `linear-gradient(135deg, rgba(255,255,255,0), rgba(255,228,239,.88), rgba(133,230,213,.72))`,
  }, currentFinger().shape);
}

function buildAiPrompt(extra = "") {
  const promptInput = $("#ai-prompt-input");
  const base = promptInput?.value.trim() || "";
  const styles = selectedAiStyles.length ? ` Styles: ${selectedAiStyles.join(", ")}.` : "";
  const shape = ` Nail shape family: ${currentFinger().shape}.`;
  const instruction = " Use this request as the visual theme for the generated nail designs.";
  const extraText = extra?.trim() ? ` Extra revision request: ${extra.trim()}.` : "";
  return `${base}.${styles}${shape}${instruction}${extraText}`.replace(/\s+/g, " ").trim();
}

async function generateAiImage(extra = "", isRegenerate = false) {
  const promptInput = $("#ai-prompt-input");
  if (!promptInput?.value.trim()) {
    setAiStatus(lang === "zh" ? "请先填写需求讲述。" : "Please describe the request first.", true);
    promptInput?.focus();
    return;
  }
  const prompt = buildAiPrompt(extra);
  const flow = $("#ai-workflow-modal")?.dataset.flow || "image";
  const model = $("#ai-model-select")?.value || "";
  const button = isRegenerate ? $("#ai-regenerate-submit") : $("#ai-generate-submit");
  const regenerateHint = $("#ai-regenerate-hint");
  if (button) button.disabled = true;
  if (isRegenerate && regenerateHint) regenerateHint.classList.remove("hidden");
  setAiStatus(t("aiGenerating"));
  try {
    const references = [currentNailReferenceImage(), ...aiReferenceImages];
    let payload = {
      prompt,
      flow,
      model,
      styles: selectedAiStyles,
      references,
      count: 5,
      preview: false,
    };
    while (JSON.stringify(payload).length > 7_500_000 && payload.references.length > 1) {
      payload.references.pop();
    }
    const response = await fetch("/api/ai-generate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "AI generation failed.");
    const outputs = Array.isArray(data.outputs) ? data.outputs : [];
    const step2Outputs = outputs
      .filter((item) => /^step2-\d+$/.test(String(item?.step || "")))
      .sort((a, b) => Number(a.order || String(a.step).split("-")[1]) - Number(b.order || String(b.step).split("-")[1]));
    const step3Output = outputs.find((item) => item?.step === "step3");
    const rawGeneratedImages = step2Outputs.length
      ? step2Outputs.map((item) => item.image).filter(Boolean)
      : Array.isArray(data.images) ? data.images.filter(Boolean) : [];
    aiGeneratedImages = await Promise.all(rawGeneratedImages.map((image) => transparentizeAiDesignImage(image)));
    selectedAiImage = aiGeneratedImages[0] || "";
    const localDraftPreview = await composeAiHandPreview(aiGeneratedImages);
    const previewCompose = await requestAiPreviewCompose(prompt, aiGeneratedImages, localDraftPreview);
    const localPreview = previewCompose.image ? "" : localDraftPreview;
    aiPreviewImage = previewCompose.image || localPreview || step3Output?.image || data.previewImage || "";
    renderAiResults();
    selectAiImage(selectedAiImage);
    const seedEditUnavailable = /SeedEdit/i.test(previewCompose.message || "");
    const providerLabel = previewCompose.provider && previewCompose.provider !== "local"
      ? `Step3 provider: ${previewCompose.provider}.`
      : localPreview && seedEditUnavailable
        ? "Step3 provider: local canvas fallback after SeedEdit skipped/failed."
        : localPreview ? "Step3 provider: local canvas fallback." : "";
    const previewMessage = previewCompose.message || (localPreview ? "Used local canvas fallback." : "");
    setAiStatus([t("aiGenerated"), data.message, providerLabel, previewMessage].filter(Boolean).join(" "));
    setAiWorkflowStep(2);
  } catch (error) {
    console.error(error);
    aiGeneratedImages = [];
    selectedAiImage = "";
    aiPreviewImage = "";
    renderAiResults();
    setAiStatus(t("aiGenerateFailed"), true);
  } finally {
    if (button) button.disabled = false;
    if (regenerateHint) regenerateHint.classList.add("hidden");
  }
}

async function requestAiPreviewCompose(prompt, nailImages, sourceImage = "") {
  if (!nailImages?.length) return { image: "", provider: "", message: "" };
  try {
    const compactNails = await Promise.all(nailImages.map((image) => compactAiPreviewInputImage(image)));
    const response = await fetch("/api/ai-preview-compose", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ prompt, nailImages: compactNails, sourceImage }),
    });
    const data = await response.json();
    if (data.message) console.info(data.message);
    if (!response.ok) throw new Error(data.error || "AI preview compose failed.");
    return {
      image: data.image || "",
      provider: data.provider || "",
      message: data.message || "",
    };
  } catch (error) {
    console.warn("AI preview compose fallback", error);
    return {
      image: "",
      provider: "",
      message: `AI preview compose request failed: ${error.message || error}.`,
    };
  }
}

function compactAiPreviewInputImage(src) {
  return new Promise((resolve) => {
    if (!src) {
      resolve(src);
      return;
    }
    const image = new Image();
    if (/^https?:\/\//i.test(src)) image.crossOrigin = "anonymous";
    image.onerror = () => resolve(src);
    image.onload = () => {
      const width = image.naturalWidth || image.width;
      const height = image.naturalHeight || image.height;
      const maxSide = 900;
      const scale = Math.min(1, maxSide / Math.max(width, height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(width * scale));
      canvas.height = Math.max(1, Math.round(height * scale));
      const context = canvas.getContext("2d");
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL("image/png"));
    };
    image.src = src;
  });
}

