function renderGallerySourceTabs() {
  const source = $("#gallery-source");
  if (!source) return;
  const data = publicCatalog?.taxonomy || galleryTaxonomy || fallbackGalleryTaxonomy;
  const officialName = data.official_galleries?.[0]?.name || t("officialGallery");
  const communityName = data.community_galleries?.[0]?.name || t("communityGallery");
  source.innerHTML = `
    <button class="${activeSource === "all" ? "active" : ""}" data-source="all">${t("allTopics")}</button>
    <button class="${activeSource === "official" ? "active" : ""}" data-source="official">${officialName}</button>
    <button class="${activeSource === "community" ? "active" : ""}" data-source="community">${communityName}</button>
  `;
}

function renderGalleryCategories() {
  const board = $("#gallery-category-grid");
  if (!board) return;
  board.innerHTML = taxonomyRows().map((row) => `
    <label class="gallery-filter-line ${row.className || ""}">
      <span>${row.label}</span>
      <select data-gallery-filter="${row.key}">
        <option value="all">${t("allTopics")}</option>
        ${(row.items || []).map((item) => {
          const value = categoryValue(item);
          return `<option value="${value}" ${(activeGalleryFilters[row.key] || "all") === value ? "selected" : ""}>${item.name || item.id}</option>`;
        }).join("")}
      </select>
    </label>
  `).join("");
}

async function loadGalleryTaxonomy() {
  renderGallerySourceTabs();
  renderGalleryCategories();
  try {
    const response = await fetch("/api/gallery-taxonomy", { cache: "no-store" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload = await response.json();
    if (payload?.data) {
      galleryTaxonomy = payload.data;
      renderGallerySourceTabs();
      renderGalleryCategories();
    }
  } catch (error) {
    console.warn("Gallery taxonomy fallback in use", error);
  }
}

async function loadPublicCatalog() {
  try {
    const response = await fetch("/api/public-catalog", { cache: "no-store" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload = await response.json();
    if (payload?.data) {
      publicCatalog = payload.data;
      publicCatalogLoaded = true;
      galleryTaxonomy = payload.data.taxonomy || galleryTaxonomy;
      updateMaterialTileImages();
      renderAll();
      renderDesigner();
    }
  } catch (error) {
    publicCatalogLoaded = true;
    updateMaterialTileImages();
    renderAll();
    console.warn("Public catalog fallback in use", error);
  }
}

function taxonomySelectItems(key) {
  const data = publicCatalog?.taxonomy || galleryTaxonomy || fallbackGalleryTaxonomy;
  if (key === "shape") return data.shapes || [];
  if (key === "style") return data.styles || [];
  if (key === "material") return data.materials || [];
  return [];
}

function fillCommunityUploadSelect(selector, key) {
  const select = $(selector);
  if (!select) return;
  const items = taxonomySelectItems(key);
  select.innerHTML = `<option value="">${t("allTopics")}</option>` + items.map((item) => {
    const value = item.id || item.name || "";
    const label = item.name || item.label || item.id || "";
    return `<option value="${escapeAttribute(value)}">${label}</option>`;
  }).join("");
}

function resetCommunityTemplateUpload() {
  communityTemplateUploadImage = null;
  $("#community-template-form")?.reset();
  const preview = $("#community-template-preview");
  if (preview) {
    preview.hidden = true;
    preview.removeAttribute("src");
  }
  $("#community-template-empty")?.removeAttribute("hidden");
  const status = $("#community-template-upload-status");
  if (status) status.textContent = t("templateUploadReady");
}

function openCommunityTemplateModal() {
  fillCommunityUploadSelect("#community-template-shape", "shape");
  fillCommunityUploadSelect("#community-template-style", "style");
  fillCommunityUploadSelect("#community-template-material", "material");
  resetCommunityTemplateUpload();
  $("#community-template-modal")?.classList.remove("hidden");
}

function closeCommunityTemplateModal() {
  $("#community-template-modal")?.classList.add("hidden");
}

function readImageFile(file) {
  return new Promise((resolve, reject) => {
    if (!file) {
      reject(new Error("No file selected"));
      return;
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Image read failed"));
    reader.onload = () => {
      const image = new Image();
      image.onload = () => resolve({ data: reader.result, width: image.naturalWidth, height: image.naturalHeight });
      image.onerror = () => resolve({ data: reader.result, width: 0, height: 0 });
      image.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

async function submitCommunityTemplateUpload(event) {
  event.preventDefault();
  const status = $("#community-template-upload-status");
  const setStatus = (message) => { if (status) status.textContent = message; };
  const name = $("#community-template-name")?.value.trim() || "";
  if (!communityTemplateUploadImage?.data) {
    setStatus(t("templateUploadImageRequired"));
    return;
  }
  if (!name) {
    setStatus(t("templateUploadNameRequired"));
    return;
  }
  setStatus(t("templateUploadSaving"));
  const user = await (currentAuthUser?.userId ? activeActionUser() : ensurePersistentUser({ createGuest: true }));
  const payload = {
    userId: user?.userId || "",
    recoveryCode: user?.recoveryCode || "",
    templateName: name,
    templateTitle: name,
    description: $("#community-template-description")?.value.trim() || "",
    image: communityTemplateUploadImage.data,
    width: communityTemplateUploadImage.width,
    height: communityTemplateUploadImage.height,
    nailShape: $("#community-template-shape")?.value || "",
    styleCategories: $("#community-template-style")?.value || "",
    materialType: $("#community-template-material")?.value || "",
    materialCategories: $("#community-template-material")?.value || "",
    designType: $("#community-template-design-type")?.value || "nail",
    tags: $("#community-template-tags")?.value.trim() || "",
  };
  try {
    const response = await fetch("/api/community-template", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const result = await response.json();
    if (!response.ok || !result.ok) throw new Error(result.error || "Upload failed");
    closeCommunityTemplateModal();
    activeSource = "community";
    activeGalleryFilters = {};
    activeGalleryCategory = "all";
    gallerySearch = "";
    if ($("#gallery-search")) $("#gallery-search").value = "";
    await loadPublicCatalog();
    resetTemplateRenderLimit();
    renderGallerySourceTabs();
    renderGalleryCategories();
    renderDesigns();
    showToast(t("templateUploadSaved"));
  } catch (error) {
    console.warn("[community-template-upload]", error);
    setStatus(error.message || "Upload failed");
  }
}

async function handleCommunityTemplateImageChange(event) {
  const file = event.target.files?.[0];
  if (!file) return;
  try {
    communityTemplateUploadImage = await readImageFile(file);
    const preview = $("#community-template-preview");
    if (preview) {
      preview.src = communityTemplateUploadImage.data;
      preview.hidden = false;
    }
    $("#community-template-empty")?.setAttribute("hidden", "hidden");
  } catch (error) {
    console.warn("[community-template-upload] image read failed", error);
    const status = $("#community-template-upload-status");
    if (status) status.textContent = error.message || "Image read failed";
  }
}

function renderTemplateCard(design, index, scope = "public") {
  const meta = templateMeta(design, index);
  const isDraftCard = (scope === "personal" || scope === "drafts") && isPersonalDraft(design);
  const showDelete = design.source === "personal" && (
    (scope === "drafts" && (isDraftCard || canvasDraftDeleteMode))
    || (scope === "personal" && personalDeleteMode)
  );
  return `
    <article class="design-card template-card ${isDraftCard ? "template-draft-card" : ""}" data-template-index="${index}" data-template-scope="${scope}">
      ${showDelete ? `<button class="template-delete-button" data-delete-template="${index}" data-template-scope="${scope}" aria-label="${t("deletePersonalTemplates")}">×</button>` : ""}
      <button class="template-cover-button" data-template-open="${index}" data-template-scope="${scope}" aria-label="${local(design, "name", "zhName")}">
        <span class="template-cover template-shape shape-${meta.shapeKey}" style="--thumb: ${designImageStyle(design)}"><em>${formatHeat(meta.views)}</em></span>
      </button>
      <button class="template-name" data-template-open="${index}" data-template-scope="${scope}">${local(design, "name", "zhName")}</button>
      <p class="template-id">${meta.id}</p>
      <p class="template-sub">${meta.author}</p>
      <p class="template-sub">${meta.date}</p>
      ${isDraftCard ? `
        <div class="template-draft-actions">
          <button data-template-open="${index}" data-template-scope="${scope}">${lang === "zh" ? "查看" : "Open"}</button>
          <button data-template-use-canvas="${index}" data-template-scope="${scope}">${t("useInCanvas")}</button>
        </div>
      ` : `
        <div class="template-icon-actions">
          <button data-template-like="${index}" data-template-scope="${scope}" title="${t("like")}">${t("like")} <span>${design.likes || 0}</span></button>
          <button data-save-gallery="${index}" data-template-scope="${scope}" title="${t("save")}">${t("save")}</button>
          <button data-template-open="${index}" data-template-scope="${scope}" title="${t("comment")}">${t("comment")} <span>${design.comments || 0}</span></button>
        </div>
      `}
    </article>
  `;
}

function visibleDesignsForSource(source, mode = personalMode) {
  const pool = source === "personal" ? designs : catalogTemplates();
  let visible = source === "all"
    ? pool.filter((design) => design.source === "official" || design.source === "community")
    : pool.filter((design) => design.source === source);
  if (source === "personal") {
    if (mode === "drafts") {
      visible = visible.filter((design) => isPersonalDraft(design));
      visible = visible.slice().sort((a, b) => Number(Boolean(b.isAutoDraft || b.templateId === AUTO_DRAFT_TEMPLATE_ID)) - Number(Boolean(a.isAutoDraft || a.templateId === AUTO_DRAFT_TEMPLATE_ID)));
    } else if (mode === "templates") {
      visible = visible.filter((design) => (design.mode || "templates") === "templates" && !isPersonalDraft(design));
    } else {
      visible = visible.filter((design) => (design.mode || "templates") === mode);
    }
  }
  const query = gallerySearch.trim().toLowerCase();
  if (query) {
    visible = visible.filter((design) => `${design.name || ""} ${design.zhName || ""}`.toLowerCase().includes(query));
  }
  if (source !== "personal") {
    const selectedFilters = Object.values(activeGalleryFilters).filter((value) => value && value !== "all");
    if (selectedFilters.length) {
      visible = visible.filter((design) => selectedFilters.every((filter) => itemMatchesCategory(design, filter)));
    }
  }
  return visible;
}

function resetTemplateRenderLimit() {
  templateRenderLimit = TEMPLATE_RENDER_BATCH;
}

function resetProductRenderLimit() {
  productRenderLimit = PRODUCT_RENDER_BATCH;
}

function observeListSentinel(observerRef, sentinelId, onReach) {
  const sentinel = document.getElementById(sentinelId);
  if (typeof observerRef.current === "function") observerRef.current();
  else if (observerRef.current) observerRef.current.disconnect();
  if (!sentinel) {
    observerRef.current = null;
    return;
  }
  const reach = () => {
    if (typeof observerRef.current === "function") observerRef.current();
    else if (observerRef.current) observerRef.current.disconnect();
    observerRef.current = null;
    onReach();
  };
  const onScroll = () => {
    if (!document.body.contains(sentinel)) {
      if (typeof observerRef.current === "function") observerRef.current();
      observerRef.current = null;
      return;
    }
    if (sentinel.getBoundingClientRect().top < window.innerHeight + 360) reach();
  };
  const onClick = () => reach();
  sentinel.addEventListener("click", onClick, { once: true });
  window.addEventListener("scroll", onScroll, { passive: true });
  observerRef.current = () => {
    window.removeEventListener("scroll", onScroll);
    sentinel.removeEventListener("click", onClick);
  };
}

function observeProductLoadMore() {
  observeListSentinel({ get current() { return productLoadObserver; }, set current(value) { productLoadObserver = value; } }, "product-load-sentinel", () => {
    productRenderLimit += PRODUCT_RENDER_BATCH;
    renderProducts();
  });
}

function observeTemplateLoadMore() {
  observeListSentinel({ get current() { return templateLoadObserver; }, set current(value) { templateLoadObserver = value; } }, "template-load-sentinel", () => {
    templateRenderLimit += TEMPLATE_RENDER_BATCH;
    renderDesigns();
  });
}

function hydrateProductImages() {
  const images = $$("#product-grid img[data-src]");
  if (productImageObserver) productImageObserver.disconnect();
  if (!images.length) {
    productImageObserver = null;
    return;
  }
  const loadImage = (image) => {
    const source = image.dataset.src;
    if (!source) return;
    image.addEventListener("load", () => {
      image.closest(".product-cover")?.classList.add("image-loaded");
    }, { once: true });
    image.src = source;
    image.removeAttribute("data-src");
  };
  if (!("IntersectionObserver" in window)) {
    images.slice(0, PRODUCT_RENDER_BATCH).forEach(loadImage);
    return;
  }
  productImageObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      productImageObserver.unobserve(entry.target);
      loadImage(entry.target);
    });
  }, { rootMargin: "280px 0px" });
  images.forEach((image) => productImageObserver.observe(image));
}

function renderDesigns() {
  if (!publicCatalogLoaded) {
    $("#design-grid").innerHTML = `<article class="design-card template-card"><p class="muted">${lang === "zh" ? "正在加载模板..." : "Loading templates..."}</p></article>`;
    renderPersonalDesigns();
    renderCanvasDrafts();
    return;
  }
  const visible = visibleDesignsForSource(activeSource);
  renderedPublicTemplateItems = visible;
  if (!visible.length) {
    $("#design-grid").innerHTML = `<article class="design-card template-card"><p class="muted">${t("backendTemplatesEmpty")}</p></article>`;
    observeTemplateLoadMore();
  } else {
    const shown = visible.slice(0, templateRenderLimit);
    const loadMore = visible.length > shown.length
      ? `<div id="template-load-sentinel" class="list-load-sentinel">${lang === "zh" ? `继续加载 ${visible.length - shown.length} 个模板...` : `Loading ${visible.length - shown.length} more templates...`}</div>`
      : "";
    $("#design-grid").innerHTML = shown.map((design, index) => renderTemplateCard(design, index, "public")).join("") + loadMore;
    observeTemplateLoadMore();
  }
  renderPersonalDesigns();
  renderCanvasDrafts();
}

function renderPersonalDesigns() {
  const grid = $("#personal-design-grid");
  if (!grid) return;
  const visible = visibleDesignsForSource("personal", personalMode);
  renderedPersonalTemplateItems = visible;
  if (!visible.length) {
    if (personalMode === "favorites") {
      grid.innerHTML = `
        <article class="personal-empty-state">
          <p>${t("emptyFavoritesPrompt")}<button type="button" data-open-template-library>${t("emptyFavoritesAction")}</button></p>
        </article>
      `;
      return;
    }
    const emptyKey = personalMode === "drafts" ? "draftsEmpty" : "templatesEmpty";
    grid.innerHTML = `<article class="design-card template-card"><p class="muted">${t(emptyKey)}</p></article>`;
    return;
  }
  grid.innerHTML = visible.map((design, index) => renderTemplateCard(design, index, "personal")).join("");
}

function renderCanvasDrafts() {
  const grid = $("#canvas-draft-grid");
  if (!grid) return;
  const visible = visibleDesignsForSource("personal", "drafts");
  renderedCanvasDraftItems = visible;
  if (!visible.length) {
    grid.innerHTML = `<article class="design-card template-card"><p class="muted">${t("draftsEmpty")}</p></article>`;
    return;
  }
  grid.innerHTML = visible.map((design, index) => renderTemplateCard(design, index, "drafts")).join("");
}

function loadCanvasFromData(canvas, dataUrl, opacity = 1) {
  const context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  if (!dataUrl) return;
  const image = new Image();
  image.onload = () => {
    context.save();
    context.globalAlpha = opacity;
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    context.restore();
  };
  image.src = dataUrl;
}

function currentFinger() {
  return fingerDesigns[designerState.finger];
}

function fixedShapeForFinger(finger) {
  return fingerBaseShapes[finger] || "long-oval";
}

function normalizeFingerBaseStates(material = null) {
  const appliedMaterial = material || fingerDesigns.thumb?.material || "m123";
  fingers.forEach((finger) => {
    if (!fingerDesigns[finger]) fingerDesigns[finger] = createFingerState();
    fingerDesigns[finger].shape = fixedShapeForFinger(finger);
    fingerDesigns[finger].material = appliedMaterial;
  });
}

function materialCategoryMatch(template, materialId) {
  if (!template || !materialId) return false;
  const materialKey = String(materialId).toLowerCase();
  const materialNumber = materialKey.replace(/^m/, "");
  const materialName = materialLabelMap[materialId] || materialId;
  const values = [
    template.id,
    template.template_id,
    template.name,
    template.zhName,
    template.template_name,
    template.template_title,
    template.material_type,
    template.material_categories,
    template.image_url,
    ...(Array.isArray(template.image_list) ? template.image_list : []),
    ...(Array.isArray(template.category_ids) ? template.category_ids : []),
  ].filter(Boolean).join("|").toLowerCase();
  return values.includes(materialKey) || values.includes(materialNumber) || values.includes(materialName.toLowerCase());
}

function materialNumberForId(materialId) {
  return String(materialId || "").toLowerCase().match(/(?:m)?(12[3-9]|130)/)?.[1] || "";
}

function materialBaseLookupText(template) {
  const imageRefs = templateImageList(template)
    .filter((src) => src && !String(src).startsWith("data:"))
    .map((src) => String(src).slice(-220));
  return [
    template?.id,
    template?.template_id,
    template?.name,
    template?.zhName,
    template?.template_name,
    template?.template_title,
    template?.material_type,
    template?.material_categories,
    template?.image_url,
    ...(Array.isArray(template?.category_ids) ? template.category_ids : []),
    ...imageRefs,
  ].filter(Boolean).join("|").toLowerCase();
}

function materialImageSourceIsUsable(source) {
  const text = String(source || "").trim();
  return Boolean(text) && !/\/api\/admin\/product-image/i.test(text);
}

function materialFingerOrderNumber(template, materialId = "") {
  const values = materialBaseLookupText(template);
  const materialNumber = materialNumberForId(materialId) || values.match(/(?:^|[^0-9])(12[3-9]|130)(?:[^0-9]|$)/)?.[1] || "";
  const escaped = materialNumber.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const numbered = escaped
    ? values.match(new RegExp(`${escaped}\\s*(?:--|-|_|\\s)+\\s*(10|[1-9])(?:[^0-9]|$)`))
    : null;
  const generic = numbered || values.match(/(?:finger|nail|指|甲)\s*(10|[1-9])(?:[^0-9]|$)/);
  return generic ? Number(generic[1]) : 0;
}

function materialFingerFromTemplate(template, materialId = "") {
  const values = materialBaseLookupText(template);
  const named = [
    ["thumb", ["thumb", "大拇指", "拇指"]],
    ["index", ["index", "食指"]],
    ["middle", ["middle", "中指"]],
    ["ring", ["ring", "无名指"]],
    ["pinky", ["pinky", "little", "小指"]],
  ].find(([, aliases]) => aliases.some((alias) => values.includes(alias)));
  if (named) return named[0];
  const order = materialFingerOrderNumber(template, materialId);
  if (order) return fingers[(order - 1) % fingers.length] || "";
  return "";
}

function materialBaseCandidateRank(template, materialId) {
  const images = templateImageList(template).filter(materialImageSourceIsUsable);
  if (!images.length) return 999;
  const values = materialBaseLookupText(template);
  const order = materialFingerOrderNumber(template, materialId);
  if (order) return order > fingers.length ? order + 20 : order;
  if (images.length >= fingers.length && /^material_/i.test(String(template?.template_id || template?.id || ""))) return 40;
  if (images.length >= fingers.length && /(cutout|single|单甲|抠图|底图|nail-base|material-base)/i.test(values)) return 45;
  return 999;
}

function officialMaterialTemplateSet(materialId) {
  const templates = ((publicCatalog?.material_bases?.length ? publicCatalog.material_bases : publicCatalog?.templates) || [])
    .filter((item) => item.source_type === "official" && materialCategoryMatch(item, materialId) && templateImageList(item).length)
    .map((item, index) => ({ item, index, rank: materialBaseCandidateRank(item, materialId) }))
    .filter((entry) => entry.rank < 999)
    .sort((a, b) => a.rank - b.rank || a.index - b.index)
    .map((entry) => entry.item);
  const multiImageTemplate = templates.find((item) => templateImageList(item).length >= fingers.length);
  if (multiImageTemplate) {
    return Object.fromEntries(fingers.map((finger) => [finger, multiImageTemplate]));
  }
  const byFinger = new Map();
  templates.forEach((item) => {
    const finger = materialFingerFromTemplate(item, materialId);
    if (finger && !byFinger.has(finger)) byFinger.set(finger, item);
  });
  return Object.fromEntries(fingers.map((finger) => {
    const match = byFinger.get(finger);
    return [finger, match || null];
  }));
}

function templateFingerImageSource(template, finger) {
  const images = templateImageList(template).filter(materialImageSourceIsUsable);
  if (!images.length) return "";
  const fingerIndex = Math.max(0, fingers.indexOf(finger));
  return images[fingerIndex] || images[0] || "";
}

function materialBaseImageForFinger(materialId, finger) {
  const template = officialMaterialTemplateSet(materialId)[finger];
  const templateImage = templateFingerImageSource(template, finger);
  if (templateImage) return cssImage(templateImage);
  const cachedImages = officialMaterialBaseMap[materialId];
  if (Array.isArray(cachedImages) && cachedImages.length) {
    const fingerIndex = Math.max(0, fingers.indexOf(finger));
    return cssImage(cachedImages[fingerIndex] || cachedImages[0]);
  }
  return fittedMaterialUrl(materialId, fixedShapeForFinger(finger));
}

function materialPreviewImage(materialId) {
  const templateSet = officialMaterialTemplateSet(materialId);
  const firstTemplate = fingers.map((finger) => templateSet[finger]).find(Boolean);
  const templateImage = templateFingerImageSource(firstTemplate, "thumb");
  if (templateImage) return templateImage;
  const cachedImages = officialMaterialBaseMap[materialId];
  if (Array.isArray(cachedImages) && cachedImages[0]) return cachedImages[0];
  return transparentPixel;
}

function updateMaterialTileImages() {
  $$(".material-tile").forEach((tile) => {
    const materialId = tile.dataset.material;
    const img = tile.querySelector("img");
    if (!img || !materialId) return;
    img.src = materialPreviewImage(materialId);
  });
}

function applyMaterialToAllFingers(materialId) {
  if (!materialId) return;
  saveCurrentCanvas();
  pushHistory();
  normalizeFingerBaseStates(materialId);
  renderDesigner();
  autoSave();
}

function activeLayer() {
  const current = currentFinger();
  if (!designerState.activeLayerId || !current.layers.some((layer) => layer.id === designerState.activeLayerId)) {
    const fallback = current.layers.find((layer) => layer.type === "paint") || current.layers[0];
    designerState.activeLayerId = fallback?.id || null;
  }
  return current.layers.find((layer) => layer.id === designerState.activeLayerId);
}

function ensurePaintLayer() {
  let layer = activeLayer();
  if (!layer || layer.type !== "paint") {
    layer = currentFinger().layers.find((item) => item.type === "paint");
    if (!layer) {
      layer = { id: uid("paint"), type: "paint", name: `Paint ${currentFinger().layers.length + 1}`, visible: true, opacity: 1, data: null, hasContent: false };
      currentFinger().layers.unshift(layer);
    }
    designerState.activeLayerId = layer.id;
  }
  designerState.paintLayerId = layer.id;
  return layer;
}

function activePaintLayerForTool() {
  const currentLayerForFill = activeLayer();
  return currentLayerForFill?.type === "paint" && currentLayerForFill.visible ? currentLayerForFill : null;
}

function addPaintLayer() {
  saveCurrentCanvas();
  pushHistory();
  const count = currentFinger().layers.filter((layer) => layer.type === "paint").length + 1;
  const layer = { id: uid("paint"), type: "paint", name: `Paint ${count}`, visible: true, opacity: 1, data: null, hasContent: false };
  currentFinger().layers.unshift(layer);
  designerState.activeLayerId = layer.id;
  designerState.paintLayerId = layer.id;
  designerState.selectedObjectId = null;
  renderDesigner();
  autoSave();
}

function drawImageToCanvas(canvas, source, draw) {
  return new Promise((resolve) => {
    const context = canvas.getContext("2d");
    const image = new Image();
    image.onload = () => {
      draw(context, image);
      resolve();
    };
    image.src = source;
  });
}

function cachedLayerImage(source) {
  if (!source) return null;
  let image = layerImageCache.get(source);
  if (image) return image;
  image = new Image();
  image.onload = () => compositeCanvases();
  image.src = source;
  layerImageCache.set(source, image);
  return image;
}

function compositeCanvases() {
  const current = currentFinger();
  const paintContext = paintCanvas().getContext("2d");
  const assetContext = assetCanvas().getContext("2d");
  if (!editingPaintLayerId) {
    paintContext.clearRect(0, 0, paintCanvas().width, paintCanvas().height);
  }
  assetContext.clearRect(0, 0, assetCanvas().width, assetCanvas().height);

  current.layers.slice().reverse().forEach((layer) => {
    if (!layer.visible) return;
    const isEditingPaintLayer = layer.type === "paint" && layer.id === editingPaintLayerId;
    if (isEditingPaintLayer) return;
    const canvas = assetCanvas();
    const context = canvas.getContext("2d");
    if (layer.type === "asset" && layer.src) {
      const image = cachedLayerImage(layer.src);
      if (!image?.complete) return;
      context.save();
      context.globalAlpha = layer.filtersBaked ? 1 : layer.opacity;
      context.filter = layer.filtersBaked ? "none" : `hue-rotate(${layer.hue || 0}deg) saturate(${layer.saturation || 1}) brightness(${layer.brightness || 1})`;
      if (layer.rotation) {
        context.translate(layer.x + layer.w / 2, layer.y + layer.h / 2);
        context.rotate((layer.rotation * Math.PI) / 180);
        context.drawImage(image, -layer.w / 2, -layer.h / 2, layer.w, layer.h);
      } else {
        context.drawImage(image, layer.x, layer.y, layer.w, layer.h);
      }
      context.restore();
    } else if (layer.data) {
      const image = cachedLayerImage(layer.data);
      if (!image?.complete) return;
      context.save();
      context.globalAlpha = layer.opacity;
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      context.restore();
    }
  });
}

function layerThumb(layer) {
  if (layer.type === "asset" && layer.src) return `<img class="layer-thumb" src="${layer.src}" alt="" />`;
  if (layer.data) return `<img class="layer-thumb" src="${layer.data}" alt="" />`;
  return `<span class="layer-thumb"></span>`;
}

function layerActionText(key) {
  const labels = {
    hide: lang === "zh" ? "隐藏图层" : "Hide layer",
    show: lang === "zh" ? "显示图层" : "Show layer",
    opacity: lang === "zh" ? "透明度" : "Opacity",
    duplicate: lang === "zh" ? "复制图层" : "Duplicate layer",
    mergeDown: lang === "zh" ? "向下合并一层" : "Merge down one layer",
    mergeAll: lang === "zh" ? "向下合并所有图层" : "Merge all below",
    delete: lang === "zh" ? "删除图层" : "Delete layer",
  };
  return labels[key] || key;
}

function renderLayerList() {
  const list = $("#layer-list");
  if (!list) return;
  list.innerHTML = currentFinger().layers.map((layer) => `
    <div class="layer-row ${layer.id === designerState.activeLayerId ? "active" : ""} ${openLayerMenuFor === layer.id ? "layer-menu-open" : ""} ${layer.visible ? "" : "layer-hidden"} ${openLayerOpacityFor === layer.id ? "has-opacity-popover" : ""}" data-layer-id="${layer.id}">
      ${layerThumb(layer)}
      <strong>${layer.name}</strong>
      <span class="layer-menu-caret" data-layer-menu="${layer.id}" aria-hidden="true">▾</span>
      <div class="layer-action-menu">
        <button data-layer-toggle="${layer.id}" title="${layer.visible ? t("hideLayer") : t("showLayer")}">${layerActionText(layer.visible ? "hide" : "show")}</button>
        <button data-layer-opacity="${layer.id}" title="${t("adjustOpacity")}">${layerActionText("opacity")}</button>
        ${openLayerOpacityFor === layer.id ? `
          <label class="layer-opacity-popover">
            <span>${Math.round((layer.opacity ?? 1) * 100)}%</span>
            <input type="range" min="0" max="100" value="${Math.round((layer.opacity ?? 1) * 100)}" data-layer-opacity-slider="${layer.id}" aria-label="${t("adjustOpacity")}" />
          </label>
        ` : ""}
        <button data-layer-duplicate="${layer.id}" title="Duplicate layer">${layerActionText("duplicate")}</button>
        <button data-layer-merge-down="${layer.id}" title="Merge down">${layerActionText("mergeDown")}</button>
        <button data-layer-merge-all="${layer.id}" title="Merge all below">${layerActionText("mergeAll")}</button>
        <button data-layer-delete="${layer.id}" title="Delete">${layerActionText("delete")}</button>
      </div>
    </div>
  `).join("");
}

function decorateLayerDragHandles() {
  $$("#layer-list .layer-row").forEach((row) => {
    if (row.querySelector("[data-layer-drag]")) return;
    const button = document.createElement("button");
    button.className = "layer-drag-handle";
    button.dataset.layerDrag = row.dataset.layerId;
    button.draggable = true;
    button.title = "Drag to reorder";
    button.setAttribute("aria-label", "Drag layer");
    button.textContent = "::";
    row.appendChild(button);
  });
}

function reorderLayer(dragId, targetId) {
  if (!dragId || !targetId || dragId === targetId) return;
  saveCurrentCanvas();
  const layers = currentFinger().layers;
  const from = layers.findIndex((layer) => layer.id === dragId);
  const to = layers.findIndex((layer) => layer.id === targetId);
  if (from === -1 || to === -1) return;
  pushHistory();
  const [moved] = layers.splice(from, 1);
  layers.splice(to, 0, moved);
  designerState.activeLayerId = moved.id;
  designerState.selectedObjectId = moved.type === "asset" ? moved.id : null;
  renderDesigner();
  autoSave();
}

function cloneLayerForDuplicate(layer) {
  const clone = JSON.parse(JSON.stringify(layer));
  clone.id = uid(layer.type || "layer");
  clone.name = `${layer.name || "Layer"} Copy`;
  return clone;
}

function duplicateLayer(layerId) {
  saveCurrentCanvas();
  const current = currentFinger();
  const index = current.layers.findIndex((item) => item.id === layerId);
  if (index === -1) return;
  pushHistory();
  const clone = cloneLayerForDuplicate(current.layers[index]);
  current.layers.splice(index, 0, clone);
  designerState.activeLayerId = clone.id;
  designerState.selectedObjectId = clone.type === "asset" ? clone.id : null;
  renderDesigner();
  autoSave();
}

function loadLayerImage(source) {
  return new Promise((resolve) => {
    if (!source) {
      resolve(null);
      return;
    }
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => resolve(null);
    image.src = source;
  });
}

async function rasterizeLayerGroup(layers) {
  const canvas = document.createElement("canvas");
  canvas.width = 420;
  canvas.height = 760;
  const context = canvas.getContext("2d");
  for (const layer of layers.slice().reverse()) {
    if (!layer.visible) continue;
    const source = layer.type === "asset" ? layer.src : layer.data;
    const image = await loadLayerImage(source);
    if (!image) continue;
    context.save();
    context.globalAlpha = layer.type === "asset" && layer.filtersBaked ? 1 : (layer.opacity ?? 1);
    if (layer.type === "asset") {
      context.filter = layer.filtersBaked ? "none" : `hue-rotate(${layer.hue || 0}deg) saturate(${layer.saturation || 1}) brightness(${layer.brightness || 1})`;
      const x = layer.x || 0;
      const y = layer.y || 0;
      const w = layer.w || 420;
      const h = layer.h || 760;
      if (layer.rotation) {
        context.translate(x + w / 2, y + h / 2);
        context.rotate((layer.rotation * Math.PI) / 180);
        context.drawImage(image, -w / 2, -h / 2, w, h);
      } else {
        context.drawImage(image, x, y, w, h);
      }
    } else {
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
    }
    context.restore();
  }
  return canvas.toDataURL("image/png");
}

async function mergeLayerDown(layerId, mergeAll = false) {
  saveCurrentCanvas();
  const current = currentFinger();
  const index = current.layers.findIndex((item) => item.id === layerId);
  if (index === -1 || index >= current.layers.length - 1) return;
  pushHistory();
  const group = mergeAll ? current.layers.slice(index) : current.layers.slice(index, index + 2);
  const data = await rasterizeLayerGroup(group);
  const merged = {
    id: uid("merged"),
    type: "paint",
    name: mergeAll ? "Merged Layers" : "Merged Layer",
    visible: true,
    opacity: 1,
    data,
    hasContent: true,
  };
  const deleteCount = mergeAll ? current.layers.length - index : 2;
  current.layers.splice(index, deleteCount, merged);
  designerState.activeLayerId = merged.id;
  designerState.selectedObjectId = null;
  renderDesigner();
  autoSave();
}

function cloneDesignState(state) {
  return JSON.parse(JSON.stringify(state));
}

function openApplyTargetModal() {
  saveCurrentCanvas();
  $("#apply-target-modal")?.classList.remove("hidden");
}

function closeApplyTargetModal() {
  $("#apply-target-modal")?.classList.add("hidden");
}

function applyCurrentDesignToFinger(targetFinger) {
  if (!fingers.includes(targetFinger)) return;
  saveCurrentCanvas();
  if (targetFinger === designerState.finger) {
    closeApplyTargetModal();
    showToast(lang === "zh" ? "已保留在当前甲片。" : "Kept on current nail.");
    return;
  }
  pushHistory();
  fingerDesigns[targetFinger] = cloneDesignState(currentFinger());
  closeApplyTargetModal();
  renderDesigner();
  autoSave();
  showToast(lang === "zh" ? "已应用到目标甲片。" : "Applied to target nail.");
}

function openSaveChoiceModal() {
  const modal = $("#save-choice-modal");
  if (!modal) {
    saveDesignDraft();
    return;
  }
  modal.classList.remove("hidden");
}

function closeSaveChoiceModal() {
  $("#save-choice-modal")?.classList.add("hidden");
}

function openExitChoiceModal() {
  $("#exit-choice-modal")?.classList.remove("hidden");
}

function closeExitChoiceModal() {
  $("#exit-choice-modal")?.classList.add("hidden");
}

function activateDesignTab(tabName) {
  const designView = $("#design-view");
  if (!designView) return;
  designView.querySelectorAll(".tab").forEach((button) => {
    button.classList.toggle("active", button.dataset.tab === tabName);
  });
  designView.querySelectorAll(".tab-panel").forEach((panel) => {
    panel.classList.toggle("active", panel.id === `${tabName}-panel`);
  });
  if (tabName === "canvas") {
    activeD3View = "canvas";
    setCanvasSubpage(activeCanvasSubpage || "canvas");
    renderDesigner();
  }
  if (tabName === "personal") {
    activeD3View = "personal";
    renderPersonalDesigns();
  }
  if (tabName === "gallery") {
    activeSource = "community";
    activeGalleryCategory = "all";
    activeGalleryFilters = {};
    resetTemplateRenderLimit();
    renderGallerySourceTabs();
    renderGalleryCategories();
    renderDesigns();
  }
}

function setCanvasSubpage(subpage = "canvas") {
  activeCanvasSubpage = subpage === "drafts" ? "drafts" : "canvas";
  $$("#canvas-sub-switch button").forEach((button) => {
    button.classList.toggle("active", button.dataset.canvasSubpage === activeCanvasSubpage);
  });
  $("#canvas-work-panel")?.classList.toggle("active", activeCanvasSubpage === "canvas");
  $("#canvas-drafts-panel")?.classList.toggle("active", activeCanvasSubpage === "drafts");
  if (activeCanvasSubpage === "drafts") renderCanvasDrafts();
}

function activateD3Subpage(viewName) {
  const target = viewName === "canvas" ? "canvas" : "personal";
  activeD3View = target;
  activateDesignTab(target === "canvas" ? "canvas" : "personal");
}

function switchToPersonalTemplateGallery(mode = "favorites") {
  if (mode === "drafts") {
    activeD3View = "canvas";
    activateDesignTab("canvas");
    setCanvasSubpage("drafts");
    renderCanvasDrafts();
    return;
  }
  activeD3View = "personal";
  personalMode = "favorites";
  $$("#personal-switch button").forEach((button) => button.classList.toggle("active", button.dataset.personal === personalMode));
  activateDesignTab("personal");
  renderPersonalDesigns();
}

function switchToPublicTemplateGallery({ communityFirst = false } = {}) {
  activateDesignTab("gallery");
  activeSource = communityFirst ? "community" : "all";
  renderGallerySourceTabs();
  renderGalleryCategories();
  renderDesigns();
  if (communityFirst) {
    $("#gallery-panel")?.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function openDeleteTemplateModal(index, scope = "personal") {
  const design = renderedTemplateByScope(scope, index);
  if (!design || design.source !== "personal") return;
  pendingDeleteTemplateIndex = designs.indexOf(design);
  $("#delete-template-modal")?.classList.remove("hidden");
}

function closeDeleteTemplateModal() {
  pendingDeleteTemplateIndex = null;
  $("#delete-template-modal")?.classList.add("hidden");
}

function confirmDeleteTemplate() {
  if (pendingDeleteTemplateIndex === null) return;
  const design = designs[pendingDeleteTemplateIndex];
  if (design?.source === "personal") {
    designs.splice(pendingDeleteTemplateIndex, 1);
    persistPersonalDesigns();
    renderDesigns();
  }
  closeDeleteTemplateModal();
}

function exitCanvas({ saveDraft = false } = {}) {
  if (saveDraft) saveManualPersonalDraft({ render: false });
  closeExitChoiceModal();
  switchToPersonalTemplateGallery("drafts");
}

function saveDesignDraft() {
  if (!saveManualPersonalDraft()) return;
  closeSaveChoiceModal();
  switchToPersonalTemplateGallery("drafts");
}

function autoSave() {
  saveCurrentCanvas();
  localStorage.setItem("nailStudioFingerDesigns", JSON.stringify(fingerDesigns));
  persistPersonalDesigns();
}

function saveCurrentCanvas() {
  const layer = currentFinger().layers.find((item) => item.id === editingPaintLayerId && item.type === "paint");
  if (layer && paintCanvas()) {
    layer.data = paintCanvas().toDataURL();
    layer.hasContent = true;
    if (isDrawing) return;
    editingPaintLayerId = null;
    compositeCanvases();
  }
}

function loadPaintLayerForEditing(layer) {
  if (!layer || layer.type !== "paint" || !paintCanvas()) return Promise.resolve();
  if (editingPaintLayerId === layer.id) return Promise.resolve();
  if (editingPaintLayerId && editingPaintLayerId !== layer.id) saveCurrentCanvas();
  const loadToken = ++paintLayerLoadToken;
  editingPaintLayerId = layer.id;
  designerState.paintLayerId = layer.id;
  const context = paintCanvas().getContext("2d");
  context.clearRect(0, 0, paintCanvas().width, paintCanvas().height);
  if (!layer.data) return Promise.resolve();
  const image = new Image();
  return new Promise((resolve) => {
    image.onload = () => {
      if (loadToken !== paintLayerLoadToken || editingPaintLayerId !== layer.id) {
        resolve();
        return;
      }
      context.drawImage(image, 0, 0, paintCanvas().width, paintCanvas().height);
      resolve();
    };
    image.onerror = () => resolve();
    image.src = layer.data;
  });
}

function renderDesigner() {
  const nail = $("#active-canvas-nail");
  if (!nail || !paintCanvas() || !assetCanvas()) return;

  normalizeFingerBaseStates(currentFinger().material);
  const current = currentFinger();
  activeLayer();
  $("#designer-board")?.classList.toggle("draw-mode", designerState.mode === "draw");
  nail.className = `canvas-nail material-base material-${current.material}`;
  nail.style.setProperty("--fitted-nail", materialBaseImageForFinger(current.material, designerState.finger));

  compositeCanvases();
  nail.classList.add("hide-guide");
  renderLayerList();
  decorateLayerDragHandles();
  renderObjectBox();

  $$(".finger-option").forEach((button) => {
    const selected = button.dataset.finger === designerState.finger;
    const finger = fingerDesigns[button.dataset.finger];
    button.classList.toggle("active", selected);
    const mini = button.querySelector(".mini-nail");
    mini.className = `mini-nail material-base material-${finger.material}`;
    mini.style.setProperty("--fitted-nail", materialBaseImageForFinger(finger.material, button.dataset.finger));
  });
  $$(".designer-mode").forEach((button) => button.classList.toggle("active", button.dataset.designerMode === designerState.mode));
  $$(".dynamic-panel").forEach((panel) => panel.classList.toggle("active", panel.id === `${designerState.mode}-panel`));
  $$(".swatch, .material-tile").forEach((button) => button.classList.toggle("active", button.dataset.material === current.material || button.dataset.color === designerState.color));
  $$(".brush-option").forEach((button) => button.classList.toggle("active", button.dataset.brush === designerState.brush));
  $("#brush-size").value = designerState.brushSize;
  $("#brush-opacity").value = designerState.brushOpacity;
}

function renderCampaignCarousels() {
  const campaign = activityCampaigns[campaignSlideIndex % activityCampaigns.length];
  $$(".campaign-carousel").forEach((node) => {
    node.style.setProperty("--campaign-bg", campaign.image);
    node.dataset.campaignUrl = campaign.url;
    node.innerHTML = `
      <span>${lang === "zh" ? "活动宣传" : "Campaign"}</span>
      <strong>${local(campaign, "title", "zhTitle")}</strong>
      <em>${local(campaign, "text", "zhText")}</em>
    `;
  });
}

function startCampaignCarousel() {
  window.clearInterval(campaignSlideTimer);
  renderCampaignCarousels();
  campaignSlideTimer = window.setInterval(() => {
    campaignSlideIndex = (campaignSlideIndex + 1) % activityCampaigns.length;
    renderCampaignCarousels();
  }, 5000);
}

function renderAll() {
  renderCampaignCarousels();
  renderHomeProducts();
  renderPosts();
  renderPromos();
  renderRewards();
  renderGallerySourceTabs();
  renderGalleryCategories();
  if ($("#design-view")?.classList.contains("active")) {
    renderDesigns();
  }
  if ($("#products-view")?.classList.contains("active")) {
    renderProductFilters();
    renderProductPromoRail();
    renderProducts();
  }
  renderCart();
  updateMemberStickyLabel();
}

function productLabel(item) {
  return lang === "zh" && item.zh ? item.zh : (item.label || item.name || item.id);
}

function productName(item) {
  return lang === "zh" && item.zhName ? item.zhName : item.name;
}

function productImageSource(item) {
  const direct = item.image || item.image_url || "";
  if (direct) return direct;
  const base64 = item.image_base64 || "";
  if (!base64) return "";
  if (/^data:image\//i.test(base64)) return base64;
  return `data:image/png;base64,${base64}`;
}

function productDeliveryLabel(product) {
  const raw = String(product.pickupMethod || product.deliveryMode || product.delivery_mode || product.fulfillment || product.pickupMode || "").toLowerCase();
  const pickupOnly = raw.includes("pickup_only") || raw === "pickup" || raw === "self_pickup" || (product.supportsPickup === true && product.supportsShipping === false);
  const shippingOnly = raw.includes("shipping_only") || raw === "shipping" || raw === "delivery" || (product.supportsShipping === true && product.supportsPickup === false);
  if (pickupOnly) return lang === "zh" ? "自提" : "Pickup";
  if (shippingOnly) return lang === "zh" ? "送货" : "Delivery";
  return lang === "zh" ? "送货/自提" : "Delivery/Pickup";
}

function truthyFlag(value) {
  if (value === true || value === 1) return true;
  return ["1", "true", "yes", "y"].includes(String(value || "").trim().toLowerCase());
}

function isPrintingProduct(product) {
  const text = [
    product.id,
    product.name,
    product.zhName,
    product.productType,
    product.style,
    product.desc,
    ...(product.tags || []),
  ].join(" ").toLowerCase();
  return text.includes("printing") || /\bprint\b/.test(text);
}

function homeFeaturedProducts() {
  const featured = productItems().filter((product) => truthyFlag(product.isFeatured));
  const source = featured.length ? featured : productItems();
  return source
    .map((product, index) => ({ product, index }))
    .sort((a, b) => {
      const printDelta = Number(isPrintingProduct(b.product)) - Number(isPrintingProduct(a.product));
      return printDelta || a.index - b.index;
    })
    .slice(0, 16)
    .map(({ product }) => product);
}

function renderHomeProducts() {
  const grid = $("#home-product-grid");
  if (!grid) return;
  if (!publicCatalogLoaded) {
    grid.innerHTML = `<p class="muted">${lang === "zh" ? "正在加载商品..." : "Loading products..."}</p>`;
    return;
  }
  const items = homeFeaturedProducts();
  if (!items.length) {
    grid.innerHTML = `<p class="muted">${lang === "zh" ? "暂无商品。" : "No products yet."}</p>`;
    return;
  }
  grid.innerHTML = items.map((product) => `
    <button class="home-product-item" type="button" data-product-open="${product.id}">
      <span class="home-product-image">
        ${product.image ? `<img data-home-src="${product.image}" alt="${productName(product)}" loading="lazy" decoding="async">` : `<span class="home-product-fallback" style="${productCoverStyle(product)}"></span>`}
      </span>
      <span class="home-product-info">
        <strong>${money(product.price)}</strong>
        <span>${Math.max(0, Number(product.stock || 0))}</span>
        <em>${productDeliveryLabel(product)}</em>
      </span>
    </button>
  `).join("");
  hydrateHomeProductImages();
}

function hydrateHomeProductImages() {
  $$("#home-product-grid img[data-home-src]").forEach((image) => {
    image.src = image.dataset.homeSrc;
    image.removeAttribute("data-home-src");
  });
}

function productPromoEvents() {
  const acceptedTypes = new Set([
    "product_campaign",
    "product_purchase_campaign",
    "product_purchase_activity",
    "promotion",
    "promotion_campaign",
    "promo",
    "promo_campaign",
    "discount_campaign",
    "sale_campaign",
    "shopping_campaign",
    "shopping_activity",
    "press_on_product_campaign",
  ]);
  return Array.isArray(publicCatalog?.events)
    ? publicCatalog.events.filter((event) => {
      const type = String(event.event_type || "").trim().toLowerCase();
      const text = [
        type,
        event.event_title,
        event.event_name,
        event.event_content,
      ].join(" ").toLowerCase();
      return acceptedTypes.has(type) || text.includes("promo") || text.includes("promotion") || text.includes("促销") || text.includes("折扣");
    })
    : [];
}

function promoCardTone(index) {
  return ["", "mint", "violet", "pearl"][index % 4];
}

function renderProductPromoRail() {
  const rail = $(".product-promo-rail");
  const track = $("#product-promo-track");
  if (!rail || !track) return;
  const events = productPromoEvents();
  if (!events.length) {
    rail.classList.remove("hidden");
    track.innerHTML = `
      <article class="product-promo-card empty">
        <span>${lang === "zh" ? "促销活动" : "Promotion"}</span>
        <strong>${lang === "zh" ? "无活动" : "No activity"}</strong>
        <p>${lang === "zh" ? "暂无可展示的促销类活动。" : "No promotional campaign is available yet."}</p>
      </article>
    `;
    return;
  }
  rail.classList.remove("hidden");
  activeProductPromoIndex = Math.max(0, Math.min(activeProductPromoIndex, events.length - 1));
  const event = events[activeProductPromoIndex];
  const tone = promoCardTone(activeProductPromoIndex);
  const image = productImageSource(event);
  const title = local(event, "event_title", "event_title") || local(event, "event_name", "event_name") || `Event ${activeProductPromoIndex + 1}`;
  const copy = local(event, "event_content", "event_content") || t("productNoCampaign");
  const typeLabel = String(event.event_type || "product campaign").replace(/_/g, " ");
  const href = String(event.html_url || "").trim() || `activity.html?id=${event.event_id}`;
  track.innerHTML = `
    <article class="product-promo-card ${tone}" data-campaign-target="event-${event.event_id}" data-campaign-url="${href}" style="${image ? `background-image: linear-gradient(rgba(45,35,48,.18), rgba(45,35,48,.48)), ${cssImage(image)}; background-size: cover; background-position: center;` : ""}">
      <span>${typeLabel}</span>
      <strong>${title}</strong>
      <p>${copy}</p>
    </article>
    <div class="product-promo-dots" aria-label="Product campaign pages">
      ${events.map((item, index) => `<button class="${index === activeProductPromoIndex ? "active" : ""}" data-product-promo-page="${index}" type="button" aria-label="Campaign ${index + 1}"></button>`).join("")}
    </div>
  `;
}

function stopProductPromoAutoplay() {
  window.clearInterval(productPromoTimer);
  productPromoTimer = null;
}

function startProductPromoAutoplay() {
  stopProductPromoAutoplay();
  if (!$("#products-view")?.classList.contains("active")) return;
  const events = productPromoEvents();
  if (events.length <= 1) return;
  productPromoTimer = window.setInterval(() => {
    const currentEvents = productPromoEvents();
    if (!$("#products-view")?.classList.contains("active") || currentEvents.length <= 1) {
      stopProductPromoAutoplay();
      return;
    }
    activeProductPromoIndex = (activeProductPromoIndex + 1) % currentEvents.length;
    renderProductPromoRail();
  }, 5000);
}

function money(value) {
  return `$${value.toFixed(2)}`;
}

function escapeAttribute(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function persistProductCart() {
  try {
    localStorage.setItem(PRODUCT_CART_KEY, JSON.stringify(productCart));
  } catch (error) {
    console.warn("[cart] Failed to persist cart", error);
  }
}

function restoreProductCart() {
  try {
    const raw = localStorage.getItem(PRODUCT_CART_KEY);
    if (!raw) return;
    const saved = JSON.parse(raw);
    if (!Array.isArray(saved)) return;
    productCart.splice(0, productCart.length, ...saved
      .filter((line) => line && line.id && Number(line.qty) > 0)
      .map((line) => ({
        id: String(line.id),
        qty: Math.max(1, Math.min(99, Number(line.qty) || 1)),
        size: productSizeOrder.includes(String(line.size || "").toUpperCase()) ? String(line.size).toUpperCase() : "M",
        fulfillmentMode: ["pickup", "shipping"].includes(String(line.fulfillmentMode || "")) ? String(line.fulfillmentMode) : "",
        pickupDeviceId: String(line.pickupDeviceId || ""),
        pickupLabel: String(line.pickupLabel || ""),
        shippingAddress: String(line.shippingAddress || ""),
        remark: String(line.remark || ""),
      })));
  } catch (error) {
    console.warn("[cart] Failed to restore cart", error);
  }
}

function currentCheckoutItems(mode = "cart") {
  if (mode === "buy-now") {
    const product = findProductById(activeProductIndex);
    if (!product) return [];
    return [{
      id: product.id,
      qty: Math.max(1, Number(activeProductQty || 1)),
      size: activeProductSize,
      fulfillmentMode: activeProductFulfillmentMode,
      pickupDeviceId: activeProductPickupDevice?.id || "",
      pickupLabel: activeProductPickupDevice ? pickupDeviceLabel(activeProductPickupDevice) : "",
      shippingAddress: activeProductShippingAddress,
      remark: activeProductRemark,
    }];
  }
  return productCart.map((line) => ({
    id: line.id,
    qty: line.qty,
    size: line.size || "M",
    fulfillmentMode: line.fulfillmentMode || "",
    pickupDeviceId: line.pickupDeviceId || "",
    pickupLabel: line.pickupLabel || "",
    shippingAddress: line.shippingAddress || "",
    remark: line.remark || "",
  }));
}

function checkoutSnapshot(mode = "cart") {
  const items = currentCheckoutItems(mode).map((line) => {
    const product = findProductById(line.id);
    if (!product) return null;
    return {
      id: product.id,
      qty: line.qty,
      size: line.size || "M",
      name: product.name,
      zhName: product.zhName || "",
      price: Number(product.price || 0),
      image: product.image || "",
      tags: Array.isArray(product.tags) ? product.tags.slice(0, 6) : [],
      shape: product.shape || "",
      style: product.style || "",
      productType: product.productType || "",
      boundDeviceId: product.boundDeviceId || "",
      fulfillmentMode: line.fulfillmentMode || "",
      pickupDeviceId: line.pickupDeviceId || "",
      pickupLabel: line.pickupLabel || "",
      shippingAddress: line.shippingAddress || "",
      remark: line.remark || "",
    };
  }).filter(Boolean);
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const discount = subtotal >= 120 ? subtotal * 0.12 : subtotal >= 80 ? 8 : 0;
  return {
    mode,
    createdAt: new Date().toISOString(),
    currency: "AUD",
    items,
    subtotal,
    discount,
    total: Math.max(0, subtotal - discount),
  };
}

function prepareCheckoutDraft(mode = "cart") {
  const draft = checkoutSnapshot(mode);
  try {
    localStorage.setItem(CHECKOUT_DRAFT_KEY, JSON.stringify(draft));
  } catch (error) {
    console.warn("[checkout] Failed to store checkout draft", error);
  }
  return draft;
}

function productCoverStyle(product) {
  if (product.image) return `background-image: ${cssImage(product.image)}; background-size: cover; background-position: center; background-color: #fff;`;
  const [a, b] = product.color;
  return `background: radial-gradient(circle at 42% 22%, rgba(255,255,255,.95) 0 7px, transparent 8px), linear-gradient(150deg, ${a}, ${b});`;
}

function findProductById(productId) {
  return productItems().find((product) => String(product.id) === String(productId));
}

function renderProductFilters() {
  const board = $("#product-category-grid");
  const taxonomy = publicCatalog?.taxonomy || fallbackGalleryTaxonomy;
  const styleItems = taxonomy.styles?.length ? taxonomy.styles : productStyleFilters;
  const shapeItems = taxonomy.shapes?.length ? taxonomy.shapes : productShapeFilters;
  if (!board) return;
  const optionHtml = (items, value, compoundValue = true) => `
    <option value="all">${t("allProducts")}</option>
    ${(items || []).filter((item) => item.id !== "all").map((item) => {
      const itemValue = compoundValue ? categoryValue(item) : (item.id || item.value || "");
      return `<option value="${itemValue}" ${value === itemValue ? "selected" : ""}>${productLabel(item)}</option>`;
    }).join("")}
  `;
  board.innerHTML = `
    <div class="product-filter-line product-filter-line-select">
      <label for="product-filter-style">${t("productStyleCategory")}</label>
      <select id="product-filter-style" data-product-filter="style">
        ${optionHtml(styleItems, activeProductStyle)}
      </select>
    </div>
    <div class="product-filter-line product-filter-line-select">
      <label for="product-filter-shape">${t("productShapeCategory")}</label>
      <select id="product-filter-shape" data-product-filter="shape">
        ${optionHtml(shapeItems, activeProductShape)}
      </select>
    </div>
  `;
}

function filteredProducts() {
  const query = productSearch.trim().toLowerCase();
  return productItems().filter((product) => {
    const matchesStyle = activeProductStyle === "all" || itemMatchesCategory(product, activeProductStyle) || categoryTokens(activeProductStyle).map(normalizeCategoryId).includes(normalizeCategoryId(product.style));
    const matchesShape = activeProductShape === "all" || itemMatchesCategory(product, activeProductShape) || categoryTokens(activeProductShape).map(normalizeCategoryId).includes(normalizeCategoryId(product.shape));
    const haystack = [product.id, product.name, product.zhName, product.productType, product.style, product.shape, ...product.tags].join(" ").toLowerCase();
    return matchesStyle && matchesShape && (!query || haystack.includes(query));
  });
}

function renderProducts() {
  const grid = $("#product-grid");
  if (!grid) return;
  if (!publicCatalogLoaded) {
    grid.innerHTML = `<p class="muted">${lang === "zh" ? "正在加载商品..." : "Loading products..."}</p>`;
    return;
  }
  const items = filteredProducts();
  const shown = items.slice(0, productRenderLimit);
  const productCards = shown.map((product) => {
    return `
      <button class="product-card" type="button" data-product-open="${product.id}">
        <span class="product-card-heading">
          <strong>${productName(product)}</strong>
          <small>${product.shape || product.productType || ""}</small>
        </span>
        ${product.image ? `
          <span class="product-cover has-product-image">
            <img data-src="${product.image}" alt="" loading="lazy" decoding="async">
          </span>
        ` : `
          <span class="product-cover" style="${productCoverStyle(product)}">
            <span class="press-nail-shape press-shape-${product.shape}"></span>
          </span>
        `}
        <span class="product-meta">
          <b>${money(product.price)}</b>
          <span>${Math.max(0, Number(product.stock || 0))}</span>
          <em>${productDeliveryLabel(product)}</em>
        </span>
      </button>
    `;
  }).join("");
  const loadMore = items.length > shown.length
    ? `<div id="product-load-sentinel" class="list-load-sentinel">${lang === "zh" ? `继续加载 ${items.length - shown.length} 个商品...` : `Loading ${items.length - shown.length} more products...`}</div>`
    : "";
  grid.innerHTML = productCards + loadMore || `<p class="muted">${lang === "zh" ? "没有找到匹配商品。" : "No matching products."}</p>`;
  hydrateProductImages();
  observeProductLoadMore();
}

function productSizeStock(product, size = activeProductSize) {
  if (!product) return 0;
  if (product.sizeStocks && size in product.sizeStocks) return Number(product.sizeStocks[size] || 0);
  return Number(product.stock || 0);
}

function preferredProductSize(product) {
  const available = productSizeOrder.find((size) => productSizeStock(product, size) > 0);
  return available || productSizeOrder.find((size) => size in (product.sizeStocks || {})) || "M";
}

function syncProductDetailSummary() {
  const product = findProductById(activeProductIndex);
  if (!product) return;
  const stock = productSizeStock(product, activeProductSize);
  const qtyInput = $("#product-detail-qty");
  activeProductQty = stock > 0
    ? Math.max(1, Math.min(stock, Number(qtyInput?.value || activeProductQty || 1)))
    : 1;
  if (qtyInput) {
    qtyInput.max = String(Math.max(1, stock || 1));
    qtyInput.value = String(activeProductQty);
  }
  const stockNode = $("#product-detail-stock");
  if (stockNode) {
    stockNode.textContent = stock > 0
      ? String(stock)
      : t("outOfStock");
  }
  $("#product-detail-total").textContent = money(stock > 0 ? Number(product.price || 0) * activeProductQty : 0);
  const buyButton = $("#buy-product-now");
  const cartButton = $("#add-product-cart");
  const fulfillmentReady = isActiveProductFulfillmentReady(product);
  [buyButton, cartButton].forEach((button) => {
    if (!button) return;
    button.toggleAttribute("disabled", stock <= 0 || !fulfillmentReady);
    if ("href" in button && (stock <= 0 || !fulfillmentReady)) button.removeAttribute("href");
    else if (button === buyButton) button.setAttribute("href", "checkout.html");
  });
  $$("#product-size-grid button").forEach((button) => {
    button.classList.toggle("active", button.dataset.productSize === activeProductSize);
  });
}

function isActiveProductFulfillmentReady(product) {
  if (!product) return false;
  const available = productFulfillmentAvailability(product);
  if (activeProductFulfillmentMode === "pickup") return available.pickup && Boolean(activeProductPickupDevice);
  if (activeProductFulfillmentMode === "shipping") return available.shipping && Boolean(activeProductShippingAddress);
  return false;
}

function promptMissingFulfillment(product) {
  const available = productFulfillmentAvailability(product);
  if (available.pickup && !available.shipping) openProductPickupModal();
  else if (available.shipping && !available.pickup) openProductShippingModal();
  else showToast(lang === "zh" ? "请先选择取货方式。" : "Please choose a fulfillment method first.");
}

function fulfillmentMode(product) {
  const raw = String(product?.pickupMethod || product?.deliveryMode || "").toLowerCase();
  if (raw.includes("pickup") && !raw.includes("shipping") && raw !== "both") return "pickup";
  if ((raw.includes("shipping") || raw.includes("delivery") || raw.includes("mail")) && raw !== "both") return "shipping";
  if (product?.supportsPickup === true && product?.supportsShipping === false) return "pickup";
  if (product?.supportsShipping === true && product?.supportsPickup === false) return "shipping";
  return "both";
}

function productFulfillmentAvailability(product) {
  const mode = fulfillmentMode(product);
  const hasPickupDevice = !productBoundDeviceIds(product).length || pickupDevices(product).length > 0;
  return {
    pickup: (mode === "pickup" || mode === "both") && hasPickupDevice,
    shipping: mode === "shipping" || mode === "both",
  };
}

function productBoundDeviceIds(product) {
  const raw = product?.boundDeviceId || product?.bound_device_id || product?.deviceId || product?.device_id || "";
  return String(raw)
    .split(/[,/|;，、]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function deviceMatchesBoundId(device, boundId) {
  const normalized = String(boundId || "").trim().toLowerCase();
  if (!normalized) return false;
  return [
    device?.equip_id,
    device?.id,
    device?.device_id,
    device?.deviceId,
  ].some((value) => String(value || "").trim().toLowerCase() === normalized);
}

function pickupDevices(product = findProductById(activeProductIndex)) {
  const rows = Array.isArray(publicCatalog?.device_info) ? publicCatalog.device_info : [];
  const hostRows = rows.filter((item) => {
    const type = String(item.type || "").toLowerCase();
    return type.includes("host") || type.includes("主机") || type.includes("main");
  });
  const source = hostRows.length ? hostRows : rows;
  const boundIds = productBoundDeviceIds(product);
  if (boundIds.length) return source.filter((device) => boundIds.some((id) => deviceMatchesBoundId(device, id)));
  if (source.length) return source;
  return [
    { id: "boxhill-1", equip_id: "Boxhill1", address: "Boxhill pickup kiosk" },
    { id: "boxhill-2", equip_id: "Boxhill2", address: "Boxhill pickup kiosk" },
    { id: "chadstone-maita", equip_id: "Chadstone Maita", address: "Chadstone Maita pickup kiosk" },
    { id: "dfo-south-wharf", equip_id: "DFO South Wharf", address: "DFO South Wharf pickup kiosk" },
  ];
}

function pickupDeviceLabel(device) {
  if (!device) return "";
  return [device.equip_id || device.id, device.address].filter(Boolean).join(" · ");
}

function temporaryShippingAddress() {
  try {
    return localStorage.getItem(PRODUCT_TEMP_ADDRESS_KEY) || "";
  } catch {
    return "";
  }
}

function setTemporaryShippingAddress(address) {
  try {
    localStorage.setItem(PRODUCT_TEMP_ADDRESS_KEY, String(address || "").trim());
  } catch (error) {
    console.warn("[cart] Failed to store temporary shipping address", error);
  }
}

async function loadUserShippingAddress() {
  const sessionId = storedAuthSessionId();
  if (!sessionId) return { ok: false, address: "" };
  try {
    const response = await fetch("/api/user/shipping-address", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sessionId }),
    });
    return await response.json();
  } catch (error) {
    return { ok: false, error: error.message };
  }
}

async function renderProductFulfillment(product) {
  const box = $("#product-fulfillment-options");
  if (!box || !product) return;
  const available = productFulfillmentAvailability(product);
  const selectedPickup = activeProductFulfillmentMode === "pickup" && activeProductPickupDevice;
  const selectedShipping = activeProductFulfillmentMode === "shipping" && activeProductShippingAddress;
  const selectedFulfillmentText = selectedPickup
    ? pickupDeviceLabel(activeProductPickupDevice)
    : selectedShipping
      ? activeProductShippingAddress
      : (lang === "zh" ? "请选择自取或配送。" : "Choose pickup or delivery.");
  box.innerHTML = `
    <div class="product-fulfillment-choice-row">
      <button type="button" data-product-fulfillment="pickup" class="${selectedPickup ? "active" : ""}" ${available.pickup ? "" : "disabled"}>
        <strong>${t("pickupMethod")}</strong>
        <small>${available.pickup ? t("selectPickupLocation") : t("unavailableOption")}</small>
      </button>
      <button type="button" data-product-fulfillment="shipping" class="${selectedShipping ? "active" : ""}" ${available.shipping ? "" : "disabled"}>
        <strong>${t("shippingMethod")}</strong>
        <small>${available.shipping ? t("enterShippingAddress") : t("unavailableOption")}</small>
      </button>
    </div>
    <section class="product-fulfillment-option">
      <strong>${activeProductFulfillmentMode === "pickup" ? t("selectedPickup") : activeProductFulfillmentMode === "shipping" ? t("selectedShipping") : t("pickupOption")}</strong>
      <p>${escapeAttribute(selectedFulfillmentText)}</p>
    </section>
  `;
}

async function openProductShippingModal() {
  const input = $("#product-shipping-modal-address");
  if (!input) return;
  const remembered = temporaryShippingAddress();
  let address = remembered || activeProductShippingAddress;
  if (!address) {
    const result = await loadUserShippingAddress();
    address = String(result.address || "").trim();
  }
  input.value = address;
  $("#product-shipping-modal")?.classList.remove("hidden");
}

function closeProductShippingModal() {
  $("#product-shipping-modal")?.classList.add("hidden");
}

function confirmProductShippingAddress() {
  const address = String($("#product-shipping-modal-address")?.value || "").trim();
  if (!address) {
    showToast(t("noShippingAddress"));
    return;
  }
  activeProductFulfillmentMode = "shipping";
  activeProductShippingAddress = address;
  activeProductPickupDevice = null;
  setTemporaryShippingAddress(address);
  closeProductShippingModal();
  renderProductFulfillment(findProductById(activeProductIndex));
  syncProductDetailSummary();
}

function openProductPickupModal() {
  const list = $("#pickup-device-list");
  if (!list) return;
  const product = findProductById(activeProductIndex);
  const devices = pickupDevices(product);
  list.innerHTML = devices.length ? devices.map((device, index) => `
    <button type="button" data-pickup-device-index="${index}">
      <strong>${escapeAttribute(device.equip_id || device.id || `Device ${index + 1}`)}</strong>
      <small>${escapeAttribute(device.address || "")}</small>
    </button>
  `).join("") : `<p class="muted">${lang === "zh" ? "该商品暂未绑定可自取设备。" : "No pickup device is bound to this product."}</p>`;
  $("#product-pickup-modal")?.classList.remove("hidden");
}

function closeProductPickupModal() {
  $("#product-pickup-modal")?.classList.add("hidden");
}

function selectPickupDevice(index) {
  const device = pickupDevices(findProductById(activeProductIndex))[Number(index)];
  if (!device) return;
  activeProductFulfillmentMode = "pickup";
  activeProductPickupDevice = device;
  activeProductShippingAddress = "";
  closeProductPickupModal();
  renderProductFulfillment(findProductById(activeProductIndex));
  syncProductDetailSummary();
}

function renderProductSizeOptions(product) {
  const grid = $("#product-size-grid");
  if (!grid || !product) return;
  grid.innerHTML = productSizeOrder.map((size) => {
    const stock = productSizeStock(product, size);
    return `
      <button type="button" data-product-size="${size}" ${stock <= 0 ? "disabled" : ""}>
        ${size} (${stock})
      </button>
    `;
  }).join("");
}

function openProductDetail(productId) {
  const product = findProductById(productId);
  if (!product) return;
  activeProductIndex = product.id;
  activeProductSize = preferredProductSize(product);
  activeProductQty = 1;
  activeProductFulfillmentMode = "";
  activeProductPickupDevice = null;
  activeProductShippingAddress = temporaryShippingAddress();
  activeProductRemark = "";
  $("#product-detail-id").textContent = product.id;
  $("#product-detail-name").textContent = productName(product);
  $("#product-detail-description").textContent = product.desc;
  $("#product-detail-price").textContent = money(product.price);
  $("#product-detail-image").setAttribute("style", product.image ? "" : productCoverStyle(product));
  $("#product-detail-image").classList.toggle("has-product-image", Boolean(product.image));
  $("#product-detail-image").innerHTML = product.image
    ? `<img src="${product.image}" alt="${escapeAttribute(productName(product))}" loading="lazy" decoding="async">`
    : `<span class="press-nail-shape press-shape-${product.shape}"></span>`;
  $("#product-detail-tags").innerHTML = [product.style, product.shape, ...product.tags].map((tag) => `<span>${tag}</span>`).join("");
  const remarkInput = $("#product-detail-remark");
  if (remarkInput) remarkInput.value = "";
  renderProductSizeOptions(product);
  syncProductDetailSummary();
  renderProductFulfillment(product);
  $("#product-detail-modal").classList.remove("hidden");
}

function closeProductDetail() {
  $("#product-detail-modal")?.classList.add("hidden");
}

function addProductToCart(index = activeProductIndex) {
  const product = findProductById(index);
  if (!product) return;
  const stock = productSizeStock(product, activeProductSize);
  if (stock <= 0) return;
  activeProductRemark = String($("#product-detail-remark")?.value || "").trim();
  if (!isActiveProductFulfillmentReady(product)) {
    promptMissingFulfillment(product);
    return;
  }
  const qty = Math.max(1, Math.min(stock, Number(activeProductQty || 1)));
  const pickupDeviceId = activeProductPickupDevice?.id || activeProductPickupDevice?.equip_id || "";
  const pickupLabel = activeProductPickupDevice ? pickupDeviceLabel(activeProductPickupDevice) : "";
  const line = productCart.find((item) => (
    item.id === product.id
    && item.size === activeProductSize
    && item.fulfillmentMode === activeProductFulfillmentMode
    && String(item.pickupDeviceId || "") === String(pickupDeviceId || "")
    && String(item.shippingAddress || "") === String(activeProductShippingAddress || "")
    && String(item.remark || "") === String(activeProductRemark || "")
  ));
  if (line) {
    line.qty = Math.min(stock, line.qty + qty);
  } else {
    productCart.push({
      id: product.id,
      qty,
      size: activeProductSize,
      fulfillmentMode: activeProductFulfillmentMode,
      pickupDeviceId,
      pickupLabel,
      shippingAddress: activeProductShippingAddress,
      remark: activeProductRemark,
    });
  }
  persistProductCart();
  renderCart();
  closeProductDetail();
  showToast(t("productAdded"));
}

function renderCart() {
  const list = $("#cart-list");
  const count = $("#cart-count");
  if (!list || !count) return;
  const totalQty = productCart.reduce((sum, item) => sum + item.qty, 0);
  count.textContent = totalQty;
  if (!productCart.length) {
    list.innerHTML = `<p class="muted">${t("cartEmpty")}</p>`;
  } else {
    list.innerHTML = productCart.map((line, index) => {
      const product = productItems().find((item) => item.id === line.id);
      if (!product) return "";
      const fulfillment = line.fulfillmentMode === "pickup"
        ? `${t("pickupMethod")} · ${line.pickupLabel || line.pickupDeviceId || ""}`
        : line.fulfillmentMode === "shipping"
          ? `${t("shippingMethod")} · ${line.shippingAddress || ""}`
          : "";
      return `
        <div class="cart-line" data-cart-index="${index}">
          <span class="cart-thumb" style="${productCoverStyle(product)}"></span>
          <div>
            <strong>${productName(product)}</strong>
            <small>${product.id} · ${t("size")} ${line.size || "M"} x ${line.qty}</small>
            ${fulfillment ? `<small>${escapeAttribute(fulfillment)}</small>` : ""}
            ${line.remark ? `<small>${t("productRemark")}: ${escapeAttribute(line.remark)}</small>` : ""}
          </div>
          <div class="cart-line-side">
            <b>${money(product.price * line.qty)}</b>
            <div class="cart-line-actions">
              <button type="button" data-cart-edit="${index}">${t("cartEdit")}</button>
              <button type="button" data-cart-delete="${index}">${t("cartDelete")}</button>
            </div>
          </div>
        </div>
      `;
    }).join("");
  }
  const subtotal = productCart.reduce((sum, line) => {
    const product = productItems().find((item) => item.id === line.id);
    if (!product) return sum;
    return sum + product.price * line.qty;
  }, 0);
  const discount = subtotal >= 120 ? subtotal * 0.12 : subtotal >= 80 ? 8 : 0;
  $("#cart-subtotal").textContent = money(subtotal);
  $("#cart-discount").textContent = `-${money(discount)}`;
  $("#cart-total").textContent = money(Math.max(0, subtotal - discount));
  persistProductCart();
}

function openCart() {
  renderCart();
  $("#cart-modal")?.classList.remove("hidden");
}

function closeCart() {
  $("#cart-modal")?.classList.add("hidden");
}

function removeCartLine(index) {
  const idx = Number(index);
  if (!Number.isInteger(idx) || idx < 0 || idx >= productCart.length) return;
  productCart.splice(idx, 1);
  persistProductCart();
  renderCart();
}

function openCartEdit(index) {
  const idx = Number(index);
  const line = productCart[idx];
  const product = line ? findProductById(line.id) : null;
  if (!line || !product) return;
  activeCartEditIndex = idx;
  const sizeSelect = $("#cart-edit-size");
  const qtyInput = $("#cart-edit-qty");
  const remarkInput = $("#cart-edit-remark");
  if (sizeSelect) {
    sizeSelect.innerHTML = productSizeOrder.map((size) => {
      const stock = productSizeStock(product, size);
      return `<option value="${size}" ${line.size === size ? "selected" : ""} ${stock <= 0 ? "disabled" : ""}>${size} (${stock})</option>`;
    }).join("");
  }
  if (qtyInput) {
    const stock = productSizeStock(product, line.size || "M");
    qtyInput.max = String(Math.max(1, stock || 1));
    qtyInput.value = String(Math.max(1, Math.min(stock || 1, Number(line.qty || 1))));
  }
  if (remarkInput) remarkInput.value = line.remark || "";
  $("#cart-edit-modal")?.classList.remove("hidden");
}

function closeCartEdit() {
  activeCartEditIndex = -1;
  $("#cart-edit-modal")?.classList.add("hidden");
}

function saveCartEdit() {
  const line = productCart[activeCartEditIndex];
  const product = line ? findProductById(line.id) : null;
  if (!line || !product) return;
  const size = String($("#cart-edit-size")?.value || line.size || "M").toUpperCase();
  const stock = productSizeStock(product, size);
  line.size = size;
  line.qty = Math.max(1, Math.min(stock || 1, Number($("#cart-edit-qty")?.value || line.qty || 1)));
  line.remark = String($("#cart-edit-remark")?.value || "").trim();
  persistProductCart();
  renderCart();
  closeCartEdit();
}

function activateView(viewName) {
  $$(".nav-item").forEach((button) => button.classList.toggle("active", button.dataset.view === viewName));
  $$(".view").forEach((view) => view.classList.toggle("active", view.id === `${viewName}-view`));
  document.body.dataset.activeView = viewName;
  $("#page-title").textContent = t($(".view.active").dataset.titleKey);
  if (viewName !== "products") stopProductPromoAutoplay();
  if (viewName === "products") {
    renderProductFilters();
    renderProductPromoRail();
    startProductPromoAutoplay();
    renderProducts();
  }
  if (viewName === "design") {
    renderGallerySourceTabs();
    renderGalleryCategories();
    renderDesigns();
  }
  updateMemberStickyLabel();
}

function installDebugBridge() {
  window.nailStudioDebug = {
    getCatalogSummary() {
      return {
        templates: Array.isArray(publicCatalog?.templates) ? publicCatalog.templates.length : 0,
        materialBases: Array.isArray(publicCatalog?.material_bases) ? publicCatalog.material_bases.length : 0,
        materialBaseIds: Array.isArray(publicCatalog?.material_bases)
          ? publicCatalog.material_bases.map((item) => ({
              templateId: item.template_id,
              material: item.material_type,
              count: templateImageList(item).length,
              firstImageType: templateImageSource(item).startsWith("data:") ? "base64" : (templateImageSource(item) ? "url" : "empty"),
            }))
          : [],
      };
    },
    getCanvasDebug() {
      const nail = $("#active-canvas-nail");
      return {
        activeView: document.querySelector("[data-view].active")?.getAttribute("data-view") || null,
        activeTab: document.querySelector("#design-view .tab.active")?.getAttribute("data-tab") || null,
        currentFinger: designerState.finger,
        currentMaterial: currentFinger()?.material || null,
        fitted: nail ? getComputedStyle(nail).getPropertyValue("--fitted-nail").trim() : "",
        classes: nail?.className || "",
      };
    },
    getMaterialImage(materialId, finger = designerState.finger) {
      return materialBaseImageForFinger(materialId, finger);
    },
    forceRender() {
      renderDesigner();
      return this.getCanvasDebug();
    },
  };
}

function applyInitialRoute() {
  const params = new URLSearchParams(window.location.search);
  const view = params.get("view");
  if (!view || !$(`#${view}-view`)) return;
  activateView(view);
  if (view !== "member") return;
  const memberTarget = params.get("member");
  window.requestAnimationFrame(() => {
    const target = memberTarget === "store"
      ? $("#member-store")
      : memberTarget === "task-list"
        ? $(".member-hub-panel")
        : $("#member-stats-board");
    target?.scrollIntoView({ behavior: "auto", block: "start" });
    updateMemberStickyLabel();
  });
}

function updateMemberStickyLabel() {
  $$(".member-sticky-label").forEach((label) => label.classList.remove("is-floating"));
  const floatLabel = $("#member-floating-label");
  const memberView = $("#member-view");
  if (!floatLabel || !memberView || !memberView.classList.contains("active")) {
    floatLabel?.classList.add("hidden");
    return;
  }

  const topOffset = window.innerWidth <= 680 ? 116 : window.innerWidth <= 980 ? 124 : 90;
  const sections = [
    { target: "stats", section: $("#member-stats-board"), label: $('#member-stats-board .member-sticky-label') },
    { target: "store", section: $("#member-store"), label: $('#member-store .member-sticky-label') },
    { target: "task-list", section: $(".member-hub-panel"), label: $('.member-hub-panel .member-sticky-label') },
  ].filter((item) => item.section && item.label);

  const probeY = topOffset + 8;
  let active = sections.find((item) => {
    const rect = item.section.getBoundingClientRect();
    return rect.top <= probeY && rect.bottom >= probeY;
  });
  if (!active) {
    active = sections
      .map((item) => ({ ...item, rect: item.section.getBoundingClientRect() }))
      .filter((item) => item.rect.top < probeY && item.rect.bottom > 0)
      .sort((a, b) => b.rect.top - a.rect.top)[0];
  }

  if (!active) {
    floatLabel.classList.add("hidden");
    return;
  }

  const labelRect = active.label.getBoundingClientRect();
  const shouldFloat = labelRect.top < topOffset || labelRect.bottom < topOffset;
  if (!shouldFloat) {
    floatLabel.classList.add("hidden");
    return;
  }

  const sectionRect = active.section.getBoundingClientRect();
  const left = Math.max(16, sectionRect.left);
  const width = Math.min(sectionRect.width, window.innerWidth - left - 16);
  floatLabel.innerHTML = active.label.innerHTML;
  floatLabel.dataset.memberJump = active.target;
  floatLabel.style.setProperty("--member-float-left", `${left}px`);
  floatLabel.style.setProperty("--member-float-top", `${topOffset}px`);
  floatLabel.style.setProperty("--member-float-width", `${width}px`);
  floatLabel.classList.remove("hidden");
}

function activateMemberPanel(panelName, targetId = null) {
  const panel = panelName === "rewards" ? "rewards" : "tasks";
  $$("#member-subnav [data-member-panel]").forEach((button) => {
    button.classList.toggle("active", button.dataset.memberPanel === panel);
  });
  $$("#member-view .member-panel").forEach((node) => {
    node.classList.toggle("active", node.id === `member-${panel}-panel`);
  });
  if (!targetId) return;
  window.requestAnimationFrame(() => {
    const card = $(`#member-view [data-member-card="${targetId}"]`) || (panel === "rewards" ? $("#member-store") : $("#member-stats-board"));
    if (!card) return;
    card.scrollIntoView({ behavior: "smooth", block: "center" });
    card.classList.add("notice-highlight");
    window.setTimeout(() => card.classList.remove("notice-highlight"), 1800);
  });
}

function canvasPoint(event) {
  const rect = paintCanvas().getBoundingClientRect();
  return {
    x: ((event.clientX - rect.left) / rect.width) * paintCanvas().width,
    y: ((event.clientY - rect.top) / rect.height) * paintCanvas().height,
    cssX: event.clientX - rect.left,
    cssY: event.clientY - rect.top,
  };
}

function applyCanvasView() {
  const nail = $("#active-canvas-nail");
  if (!nail) return;
  nail.style.setProperty("--canvas-zoom", canvasView.scale.toFixed(3));
  nail.style.setProperty("--canvas-pan-x", `${Math.round(canvasView.x)}px`);
  nail.style.setProperty("--canvas-pan-y", `${Math.round(canvasView.y)}px`);
}

function distanceBetweenPointers() {
  const points = [...canvasView.pointers.values()];
  if (points.length < 2) return 0;
  return Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
}

function centerBetweenPointers() {
  const points = [...canvasView.pointers.values()];
  return {
    x: (points[0].x + points[1].x) / 2,
    y: (points[0].y + points[1].y) / 2,
  };
}

function beginCanvasPinch() {
  canvasView.pinching = true;
  canvasView.startDistance = Math.max(1, distanceBetweenPointers());
  canvasView.startCenter = centerBetweenPointers();
  canvasView.startScale = canvasView.scale;
  canvasView.startX = canvasView.x;
  canvasView.startY = canvasView.y;
  isDrawing = false;
  lastPoint = null;
}

function updateCanvasPinch() {
  if (!canvasView.pinching || canvasView.pointers.size < 2) return;
  const distance = distanceBetweenPointers();
  const center = centerBetweenPointers();
  canvasView.scale = Math.max(1, Math.min(3, canvasView.startScale * (distance / canvasView.startDistance)));
  canvasView.x = canvasView.startX + center.x - canvasView.startCenter.x;
  canvasView.y = canvasView.startY + center.y - canvasView.startCenter.y;
  applyCanvasView();
}

function layerRotationRadians(layer) {
  return ((layer?.rotation || 0) * Math.PI) / 180;
}

function layerLocalPoint(point, layer) {
  const cx = layer.x + layer.w / 2;
  const cy = layer.y + layer.h / 2;
  const radians = -layerRotationRadians(layer);
  const dx = point.x - cx;
  const dy = point.y - cy;
  return {
    x: dx * Math.cos(radians) - dy * Math.sin(radians) + layer.w / 2,
    y: dx * Math.sin(radians) + dy * Math.cos(radians) + layer.h / 2,
  };
}

function layerPointFromLocal(local, layer) {
  const radians = layerRotationRadians(layer);
  const dx = local.x - layer.w / 2;
  const dy = local.y - layer.h / 2;
  return {
    x: layer.x + layer.w / 2 + dx * Math.cos(radians) - dy * Math.sin(radians),
    y: layer.y + layer.h / 2 + dx * Math.sin(radians) + dy * Math.cos(radians),
  };
}

function layerCanvasPoints(layer) {
  return [
    layerPointFromLocal({ x: 0, y: 0 }, layer),
    layerPointFromLocal({ x: layer.w, y: 0 }, layer),
    layerPointFromLocal({ x: layer.w, y: layer.h }, layer),
    layerPointFromLocal({ x: 0, y: layer.h }, layer),
  ];
}

function pointInLayerBox(point, layer, padding = 0) {
  if (!layer) return false;
  const local = layerLocalPoint(point, layer);
  return local.x >= -padding && local.x <= layer.w + padding && local.y >= -padding && local.y <= layer.h + padding;
}

function assetLayerAt(point) {
  return currentFinger().layers.find((layer) => layer.type === "asset" && layer.visible && pointInLayerBox(point, layer));
}

function objectCornerAt(point, layer) {
  if (!layer) return null;
  const threshold = 26;
  const corners = [
    ["nw", { x: 0, y: 0 }],
    ["ne", { x: layer.w, y: 0 }],
    ["sw", { x: 0, y: layer.h }],
    ["se", { x: layer.w, y: layer.h }],
  ];
  const hit = corners.find(([, local]) => {
    const corner = layerPointFromLocal(local, layer);
    return Math.hypot(point.x - corner.x, point.y - corner.y) <= threshold;
  });
  return hit?.[0] || null;
}

function cursorForObjectPoint(point) {
  const selected = currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset" && item.visible);
  const layer = selected && pointInLayerBox(point, selected, 26)
    ? selected
    : assetLayerAt(point);
  const corner = objectCornerAt(point, layer);
  if (corner === "nw" || corner === "se") return "nwse-resize";
  if (corner === "ne" || corner === "sw") return "nesw-resize";
  if (layer && pointInLayerBox(point, layer)) return "move";
  return "";
}

function updateCanvasCursor(event) {
  if (isDrawing || objectAction || selectionAction || eyedropperActive) return;
  const canvas = paintCanvas();
  if (!canvas) return;
  const point = canvasPoint(event);
  const selectedAsset = currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset" && item.visible);
  const canEditObject = Boolean(selectedAsset) || designerState.brush === "select" || designerState.mode === "import";
  const cursor = designerState.brush === "bucket" && !selectedAsset ? "crosshair" : canEditObject ? cursorForObjectPoint(point) : "";
  canvas.style.cursor = cursor || "";
}

function resizeLayerFromCorner(layer, original, handle, dx, dy) {
  const minSize = 24;
  let left = original.x;
  let top = original.y;
  let right = original.x + original.w;
  let bottom = original.y + original.h;
  if (handle.includes("w")) left = Math.max(0, Math.min(right - minSize, original.x + dx));
  if (handle.includes("e")) right = Math.min(420, Math.max(left + minSize, original.x + original.w + dx));
  if (handle.includes("n")) top = Math.max(0, Math.min(bottom - minSize, original.y + dy));
  if (handle.includes("s")) bottom = Math.min(760, Math.max(top + minSize, original.y + original.h + dy));
  layer.x = left;
  layer.y = top;
  layer.w = right - left;
  layer.h = bottom - top;
}

function resizeRotatedLayerFromPointer(layer, original, handle, point) {
  const minSize = 24;
  const opposite = {
    nw: { x: original.w, y: original.h },
    ne: { x: 0, y: original.h },
    sw: { x: original.w, y: 0 },
    se: { x: 0, y: 0 },
  }[handle] || { x: 0, y: 0 };
  const moving = layerLocalPoint(point, original);
  if (handle.includes("w")) moving.x = Math.min(opposite.x - minSize, moving.x);
  if (handle.includes("e")) moving.x = Math.max(opposite.x + minSize, moving.x);
  if (handle.includes("n")) moving.y = Math.min(opposite.y - minSize, moving.y);
  if (handle.includes("s")) moving.y = Math.max(opposite.y + minSize, moving.y);
  const left = Math.min(opposite.x, moving.x);
  const top = Math.min(opposite.y, moving.y);
  const right = Math.max(opposite.x, moving.x);
  const bottom = Math.max(opposite.y, moving.y);
  const nextW = Math.max(minSize, right - left);
  const nextH = Math.max(minSize, bottom - top);
  const localCenter = {
    x: left + nextW / 2,
    y: top + nextH / 2,
  };
  const worldCenter = layerPointFromLocal(localCenter, original);
  layer.w = nextW;
  layer.h = nextH;
  layer.x = worldCenter.x - nextW / 2;
  layer.y = worldCenter.y - nextH / 2;
  layer.rotation = original.rotation || 0;
}

function layerCenterInClient(layer) {
  const nail = $("#active-canvas-nail")?.getBoundingClientRect();
  if (!nail || !layer) return { x: 0, y: 0 };
  return {
    x: nail.left + ((layer.x + layer.w / 2) / 420) * nail.width,
    y: nail.top + ((layer.y + layer.h / 2) / 760) * nail.height,
  };
}

function pointerAngleAroundLayer(event, layer) {
  const center = layerCenterInClient(layer);
  return (Math.atan2(event.clientY - center.y, event.clientX - center.x) * 180) / Math.PI;
}

function beginObjectRotate(event) {
  const layer = currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset");
  if (!layer) return false;
  event.preventDefault();
  event.stopPropagation();
  pushHistory();
  objectRotateAction = {
    layer,
    startAngle: pointerAngleAroundLayer(event, layer),
    originalRotation: layer.rotation || 0,
  };
  event.currentTarget?.setPointerCapture?.(event.pointerId);
  return true;
}

function updateObjectRotate(event) {
  if (!objectRotateAction) return;
  const { layer, startAngle, originalRotation } = objectRotateAction;
  layer.rotation = originalRotation + pointerAngleAroundLayer(event, layer) - startAngle;
  compositeCanvases();
  renderObjectBox();
}

async function trimAssetTransparentEdges(layer) {
  if (!layer?.src) return;
  const image = await loadLayerImage(layer.src);
  if (!image) return;
  const sourceW = image.naturalWidth || image.width;
  const sourceH = image.naturalHeight || image.height;
  if (!sourceW || !sourceH) return;
  const canvas = document.createElement("canvas");
  canvas.width = sourceW;
  canvas.height = sourceH;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(image, 0, 0, sourceW, sourceH);
  const bounds = alphaBounds(canvas);
  if (!bounds) return;
  const margin = Math.max(sourceW, sourceH) * 0.015;
  if (
    bounds.x <= margin &&
    bounds.y <= margin &&
    bounds.x + bounds.w >= sourceW - margin &&
    bounds.y + bounds.h >= sourceH - margin
  ) {
    return;
  }
  const cropped = cropCanvasToBounds(canvas, bounds);
  const localX = (bounds.x / sourceW) * layer.w;
  const localY = (bounds.y / sourceH) * layer.h;
  const nextW = Math.max(8, (bounds.w / sourceW) * layer.w);
  const nextH = Math.max(8, (bounds.h / sourceH) * layer.h);
  const worldCenter = layerPointFromLocal({ x: localX + nextW / 2, y: localY + nextH / 2 }, layer);
  layer.x = worldCenter.x - nextW / 2;
  layer.y = worldCenter.y - nextH / 2;
  layer.w = nextW;
  layer.h = nextH;
  layer.src = cropped.toDataURL("image/png");
  layer.originalSrc = layer.src;
}

function endObjectRotate(event) {
  if (!objectRotateAction) return;
  const layer = objectRotateAction.layer;
  objectRotateAction = null;
  event?.currentTarget?.releasePointerCapture?.(event.pointerId);
  trimAssetTransparentEdges(layer).finally(() => {
    renderDesigner();
    autoSave();
  });
}

function beginObjectEdit(event) {
  const point = canvasPoint(event);
  const selectedLayer = designerState.selectedObjectId
    ? currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset")
    : null;
  const layer = selectedLayer && pointInLayerBox(point, selectedLayer, 26)
    ? selectedLayer
    : assetLayerAt(point);
  if (!layer || !pointInLayerBox(point, layer, 26)) {
    const currentSelected = currentFinger().layers.find((item) => item.id === designerState.selectedObjectId);
    if (currentSelected?.temporaryPaintSelection) commitTemporaryPaintSelection(currentSelected);
    return false;
  }
  designerState.activeLayerId = layer.id;
  designerState.selectedObjectId = layer.id;
  const corner = objectCornerAt(point, layer);
  objectAction = {
    mode: corner ? "resize" : "move",
    handle: corner,
    start: point,
    layer,
    original: { x: layer.x, y: layer.y, w: layer.w, h: layer.h, rotation: layer.rotation || 0 },
  };
  renderDesigner();
  return true;
}

function clampAssetCoordinate(value, size, canvasSize) {
  const visibleMargin = 32;
  const min = Math.min(visibleMargin - size, canvasSize - visibleMargin);
  const max = Math.max(visibleMargin - size, canvasSize - visibleMargin);
  return Math.max(min, Math.min(max, value));
}

function releasePaintPointer(event) {
  if (event?.pointerId === undefined || !paintCanvas()) return;
  try {
    paintCanvas().releasePointerCapture(event.pointerId);
  } catch {
    // The browser may already have released capture after a cancelled pointer.
  }
}

function updateObjectEdit(event) {
  if (!objectAction) return;
  const point = canvasPoint(event);
  const dx = point.x - objectAction.start.x;
  const dy = point.y - objectAction.start.y;
  const layer = objectAction.layer;
  if (objectAction.mode === "move") {
    layer.x = clampAssetCoordinate(objectAction.original.x + dx, layer.w, 420);
    layer.y = clampAssetCoordinate(objectAction.original.y + dy, layer.h, 760);
  } else {
    resizeRotatedLayerFromPointer(layer, objectAction.original, objectAction.handle || "se", point);
  }
  compositeCanvases();
  renderObjectBox();
}

function endObjectEdit() {
  if (!objectAction) return;
  const layer = objectAction.layer;
  objectAction = null;
  if (layer?.temporaryPaintSelection) {
    commitTemporaryPaintSelection(layer);
    return;
  }
  renderDesigner();
  autoSave();
}

async function commitTemporaryPaintSelection(selectionLayer) {
  const current = currentFinger();
  const target = current.layers.find((item) => item.id === selectionLayer.sourcePaintLayerId && item.type === "paint")
    || current.layers.find((item) => item.type === "paint");
  if (!target || !paintCanvas()) return;
  await loadPaintLayerForEditing(target);
  await drawImageToCanvas(paintCanvas(), selectionLayer.src, (ctx, image) => {
    ctx.drawImage(image, selectionLayer.x, selectionLayer.y, selectionLayer.w, selectionLayer.h);
  });
  target.data = paintCanvas().toDataURL();
  target.hasContent = true;
  current.layers = current.layers.filter((item) => item.id !== selectionLayer.id);
  designerState.activeLayerId = target.id;
  designerState.selectedObjectId = null;
  editingPaintLayerId = null;
  renderDesigner();
  autoSave();
}

function beginSelection(event) {
  const point = canvasPoint(event);
  selectionAction = { start: point, end: point };
  renderSelectionBox();
}

function updateSelection(event) {
  if (!selectionAction) return;
  selectionAction.end = canvasPoint(event);
  renderSelectionBox();
}

function renderSelectionBox() {
  const box = $("#selection-box");
  if (!box || !selectionAction) return;
  const nail = $("#active-canvas-nail").getBoundingClientRect();
  const x1 = Math.min(selectionAction.start.x, selectionAction.end.x);
  const y1 = Math.min(selectionAction.start.y, selectionAction.end.y);
  const x2 = Math.max(selectionAction.start.x, selectionAction.end.x);
  const y2 = Math.max(selectionAction.start.y, selectionAction.end.y);
  box.classList.add("active");
  box.style.left = `${(x1 / 420) * nail.width}px`;
  box.style.top = `${(y1 / 760) * nail.height}px`;
  box.style.width = `${((x2 - x1) / 420) * nail.width}px`;
  box.style.height = `${((y2 - y1) / 760) * nail.height}px`;
}

function paintLayerForSelection() {
  const active = activeLayer();
  if (active?.type === "paint" && active.visible) return active;
  return currentFinger().layers.find((layer) => layer.type === "paint" && layer.visible && (layer.data || layer.hasContent))
    || currentFinger().layers.find((layer) => layer.type === "paint" && layer.visible)
    || null;
}

async function endSelection() {
  if (!selectionAction) return;
  const x1 = Math.min(selectionAction.start.x, selectionAction.end.x);
  const y1 = Math.min(selectionAction.start.y, selectionAction.end.y);
  const x2 = Math.max(selectionAction.start.x, selectionAction.end.x);
  const y2 = Math.max(selectionAction.start.y, selectionAction.end.y);
  const selected = currentFinger().layers.find((layer) => layer.type === "asset" && layer.x >= x1 && layer.y >= y1 && layer.x + layer.w <= x2 && layer.y + layer.h <= y2);
  if (selected) {
    designerState.activeLayerId = selected.id;
    designerState.selectedObjectId = selected.id;
  } else if (x2 - x1 > 8 && y2 - y1 > 8) {
    const paintLayer = paintLayerForSelection();
    if (!paintLayer || !paintCanvas()) {
      $("#selection-box")?.classList.remove("active");
      selectionAction = null;
      renderDesigner();
      return;
    }
    await loadPaintLayerForEditing(paintLayer);
    const crop = document.createElement("canvas");
    crop.width = Math.max(1, Math.round(x2 - x1));
    crop.height = Math.max(1, Math.round(y2 - y1));
    const cropCtx = crop.getContext("2d");
    cropCtx.drawImage(paintCanvas(), x1, y1, x2 - x1, y2 - y1, 0, 0, crop.width, crop.height);
    const data = cropCtx.getImageData(0, 0, crop.width, crop.height).data;
    let hasPixels = false;
    for (let i = 3; i < data.length; i += 4) {
      if (data[i] > 0) {
        hasPixels = true;
        break;
      }
    }
    if (hasPixels) {
      pushHistory();
      const layer = {
        id: uid("asset"),
        type: "asset",
        name: "Selected Paint",
        visible: true,
        opacity: 1,
        hue: 0,
        saturation: 1,
        brightness: 1,
        src: crop.toDataURL(),
        x: x1,
        y: y1,
        w: x2 - x1,
        h: y2 - y1,
        temporaryPaintSelection: true,
        sourcePaintLayerId: paintLayer?.id || null,
      };
      currentFinger().layers.unshift(layer);
      designerState.activeLayerId = layer.id;
      designerState.selectedObjectId = layer.id;
      const ctx = paintCanvas().getContext("2d");
      ctx.save();
      ctx.globalCompositeOperation = "destination-out";
      ctx.clearRect(x1, y1, x2 - x1, y2 - y1);
      ctx.restore();
      paintLayer.data = paintCanvas().toDataURL();
      paintLayer.hasContent = true;
    }
  }
  $("#selection-box")?.classList.remove("active");
  selectionAction = null;
  renderDesigner();
  autoSave();
}

function deleteLayer(layerId) {
  pushHistory();
  const current = currentFinger();
  const layer = current.layers.find((item) => item.id === layerId);
  if (!layer) return;
  if (layer.type === "paint" && current.layers.filter((item) => item.type === "paint").length === 1 && current.layers.length === 1) {
    layer.data = null;
    layer.hasContent = false;
  } else {
    current.layers = current.layers.filter((item) => item.id !== layerId);
  }
  designerState.activeLayerId = current.layers[0]?.id || null;
  designerState.selectedObjectId = null;
  renderDesigner();
  autoSave();
}

function drawStroke(from, to) {
  const layer = ensurePaintLayer();
  if (!layer.visible) return;
  designerState.paintLayerId = layer.id;
  const context = paintCanvas().getContext("2d");
  context.save();
  if (designerState.brush === "eraser") {
    context.globalCompositeOperation = "destination-out";
  }
  context.globalAlpha = designerState.brush === "watercolor" ? designerState.brushOpacity * 0.35 : designerState.brushOpacity;
  context.strokeStyle = designerState.color;
  context.fillStyle = designerState.color;
  context.lineWidth = designerState.brush === "ballpoint" ? Math.max(1, designerState.brushSize * 0.35) : designerState.brushSize;
  context.lineCap = "round";
  context.lineJoin = "round";
  if (designerState.brush === "eraser") {
    context.beginPath();
    context.moveTo(from.x, from.y);
    context.lineTo(to.x, to.y);
    context.stroke();
  } else if (designerState.brush === "pixel") {
    const size = Math.max(4, designerState.brushSize);
    context.fillRect(Math.round(to.x / size) * size, Math.round(to.y / size) * size, size, size);
  } else if (designerState.brush === "watercolor") {
    for (let i = 0; i < 4; i += 1) {
      context.beginPath();
      context.arc(to.x + (Math.random() - 0.5) * designerState.brushSize, to.y + (Math.random() - 0.5) * designerState.brushSize, designerState.brushSize * (0.7 + Math.random() * 0.7), 0, Math.PI * 2);
      context.fill();
    }
  } else if (designerState.brush === "crayon") {
    for (let i = 0; i < 3; i += 1) {
      context.beginPath();
      context.moveTo(from.x + (Math.random() - 0.5) * 5, from.y + (Math.random() - 0.5) * 5);
      context.lineTo(to.x + (Math.random() - 0.5) * 5, to.y + (Math.random() - 0.5) * 5);
      context.stroke();
    }
  } else {
    context.beginPath();
    context.moveTo(from.x, from.y);
    context.lineTo(to.x, to.y);
    context.stroke();
  }
  context.restore();
  layer.data = paintCanvas().toDataURL();
  layer.hasContent = true;
}

function hexToRgba(hex, alpha = 1) {
  const value = hex.replace("#", "");
  const full = value.length === 3 ? value.split("").map((char) => char + char).join("") : value.padEnd(6, "0");
  return [
    parseInt(full.slice(0, 2), 16),
    parseInt(full.slice(2, 4), 16),
    parseInt(full.slice(4, 6), 16),
    Math.round(alpha * 255),
  ];
}

function colorDistance(data, index, target) {
  return Math.abs(data[index] - target[0]) + Math.abs(data[index + 1] - target[1]) + Math.abs(data[index + 2] - target[2]) + Math.abs(data[index + 3] - target[3]);
}

function imageDataHasVisiblePixels(data, alphaThreshold = 6) {
  for (let i = 3; i < data.length; i += 4) {
    if (data[i] > alphaThreshold) return true;
  }
  return false;
}

function floodFillAt(point) {
  const fillLayer = activePaintLayerForTool();
  if (!fillLayer || !fillLayer.visible || !paintCanvas()) return;
  loadPaintLayerForEditing(fillLayer).then(() => {
    const canvas = paintCanvas();
    const context = canvas.getContext("2d", { willReadFrequently: true });
    const x = Math.max(0, Math.min(canvas.width - 1, Math.round(point.x)));
    const y = Math.max(0, Math.min(canvas.height - 1, Math.round(point.y)));
    const image = context.getImageData(0, 0, canvas.width, canvas.height);
    const data = image.data;
    const startIndex = (y * canvas.width + x) * 4;
    const target = [data[startIndex], data[startIndex + 1], data[startIndex + 2], data[startIndex + 3]];
    const fill = hexToRgba(designerState.color, designerState.brushOpacity);
    if (colorDistance(data, startIndex, fill) < 8) return;
    pushHistory();
    const tolerance = target[3] < 16 ? 0 : 46;
    const alphaBarrier = 6;
    const visited = new Uint8Array(canvas.width * canvas.height);
    const stack = [[x, y]];
    while (stack.length) {
      const [cx, cy] = stack.pop();
      if (cx < 0 || cx >= canvas.width || cy < 0 || cy >= canvas.height) continue;
      const pixel = cy * canvas.width + cx;
      if (visited[pixel]) continue;
      const idx = pixel * 4;
      if (target[3] < 16) {
        if (data[idx + 3] > alphaBarrier) continue;
      } else if (colorDistance(data, idx, target) > tolerance) {
        continue;
      }
      visited[pixel] = 1;
      data[idx] = fill[0];
      data[idx + 1] = fill[1];
      data[idx + 2] = fill[2];
      data[idx + 3] = fill[3];
      stack.push([cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]);
    }
    context.putImageData(image, 0, 0);
    fillLayer.data = canvas.toDataURL();
    fillLayer.hasContent = true;
    editingPaintLayerId = null;
    renderDesigner();
    autoSave();
  });
  return;
  let layer = activePaintLayerForTool();
  if (!layer || !layer.visible || !paintCanvas()) return;
  loadPaintLayerForEditing(layer).then(async () => {
    const canvas = paintCanvas();
    const context = canvas.getContext("2d", { willReadFrequently: true });
    let image = context.getImageData(0, 0, canvas.width, canvas.height);
    if (!imageDataHasVisiblePixels(image.data)) {
      layer.hasContent = false;
      const candidates = currentFinger().layers.filter((item) => item.type === "paint" && item.visible && item.id !== layer.id);
      let foundReplacement = false;
      for (const candidate of candidates) {
        await loadPaintLayerForEditing(candidate);
        image = context.getImageData(0, 0, canvas.width, canvas.height);
        if (imageDataHasVisiblePixels(image.data)) {
          layer = candidate;
          layer.hasContent = true;
          designerState.paintLayerId = layer.id;
          designerState.activeLayerId = layer.id;
          foundReplacement = true;
          break;
        }
      }
      if (!foundReplacement) {
        await loadPaintLayerForEditing(layer);
        image = context.getImageData(0, 0, canvas.width, canvas.height);
      }
      if (!foundReplacement && !imageDataHasVisiblePixels(image.data)) {
        saveCurrentCanvas();
        renderLayerList();
        showToast(lang === "zh" ? "当前没有可填色的手绘线条。" : "No painted line layer to fill.");
        return;
      }
    }
    const x = Math.max(0, Math.min(canvas.width - 1, Math.round(point.x)));
    const y = Math.max(0, Math.min(canvas.height - 1, Math.round(point.y)));
    const data = image.data;
    const startIndex = (y * canvas.width + x) * 4;
    const target = [data[startIndex], data[startIndex + 1], data[startIndex + 2], data[startIndex + 3]];
    const fill = hexToRgba(designerState.color, designerState.brushOpacity);
    if (colorDistance(data, startIndex, fill) < 8) {
      saveCurrentCanvas();
      return;
    }
    pushHistory();
    const tolerance = target[3] < 16 ? 0 : 46;
    const alphaBarrier = 6;
    const visited = new Uint8Array(canvas.width * canvas.height);
    const stack = [[x, y]];
    let filled = 0;
    while (stack.length) {
      const [cx, cy] = stack.pop();
      if (cx < 0 || cx >= canvas.width || cy < 0 || cy >= canvas.height) continue;
      const pixel = cy * canvas.width + cx;
      if (visited[pixel]) continue;
      const idx = pixel * 4;
      if (target[3] < 16) {
        if (data[idx + 3] > alphaBarrier) continue;
      } else if (colorDistance(data, idx, target) > tolerance) {
        continue;
      }
      visited[pixel] = 1;
      data[idx] = fill[0];
      data[idx + 1] = fill[1];
      data[idx + 2] = fill[2];
      data[idx + 3] = fill[3];
      filled += 1;
      stack.push([cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]);
    }
    if (!filled) {
      saveCurrentCanvas();
      showToast(lang === "zh" ? "没有可填充的封闭区域。" : "No closed fill area found.");
      return;
    }
    context.putImageData(image, 0, 0);
    layer.hasContent = true;
    saveCurrentCanvas();
    renderDesigner();
    autoSave();
  });
}

function moveBrushCursor(event) {
  const rect = $("#canvas-stage").getBoundingClientRect();
  const cursor = $(".brush-cursor");
  if (designerState.brush === "select") {
    cursor.classList.remove("active");
    cursor.classList.remove("bucket");
    return;
  }
  cursor.classList.add("active");
  cursor.classList.toggle("bucket", designerState.brush === "bucket");
  cursor.style.setProperty("--brush-x", `${event.clientX - rect.left}px`);
  cursor.style.setProperty("--brush-y", `${event.clientY - rect.top}px`);
  cursor.style.setProperty("--brush-size", designerState.brush === "bucket" ? "30px" : `${designerState.brushSize}px`);
}

function makeLibraryAsset(kind) {
  const canvas = document.createElement("canvas");
  canvas.width = 420;
  canvas.height = 760;
  const context = canvas.getContext("2d");
  context.save();
  context.globalAlpha = 0.9;
  context.strokeStyle = designerState.color;
  context.fillStyle = designerState.color;
  context.lineWidth = 12;
  context.lineCap = "round";
    if (kind === "star") {
      for (const [x, y, r] of [[150, 220, 18], [260, 330, 12], [205, 470, 22]]) {
        context.beginPath();
        context.arc(x, y, r, 0, Math.PI * 2);
        context.fill();
      }
    } else if (kind === "ribbon") {
      context.beginPath();
      context.moveTo(70, 440);
      context.bezierCurveTo(160, 250, 260, 570, 350, 340);
      context.stroke();
    } else {
      for (const [x, y, rot] of [[170, 320, -0.6], [240, 320, 0.6], [205, 250, 0], [205, 390, 1.55]]) {
        context.save();
        context.translate(x, y);
        context.rotate(rot);
        context.beginPath();
        context.ellipse(0, 0, 42, 92, 0, 0, Math.PI * 2);
        context.stroke();
        context.restore();
      }
    }
  context.restore();
  return canvas.toDataURL();
}

function importAssetToCanvas(kind, imageSource) {
  pushHistory();
  const src = imageSource || makeLibraryAsset(kind);
  const layer = {
    id: uid("asset"),
    type: "asset",
    name: kind === "local" ? "Local Image" : `${kind} asset`,
    visible: true,
    opacity: 1,
    hue: 0,
    saturation: 1,
    brightness: 1,
    src,
    originalSrc: src,
    x: 88,
    y: 180,
    w: 244,
    h: 244,
  };
  currentFinger().layers.unshift(layer);
  designerState.activeLayerId = layer.id;
  designerState.selectedObjectId = layer.id;
  renderDesigner();
  autoSave();
  showToast(t("sampleImported"));
}

function selectedAssetLayer() {
  if (editorSession?.draft) return editorSession.draft;
  return currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset");
}

function assetEditSnapshot(layer = selectedAssetLayer()) {
  if (!layer) return null;
  return {
    src: layer.src,
    originalSrc: layer.originalSrc,
    x: layer.x,
    y: layer.y,
    w: layer.w,
    h: layer.h,
    opacity: layer.opacity,
    hue: layer.hue,
    saturation: layer.saturation,
    brightness: layer.brightness,
    rotation: layer.rotation || 0,
    filtersBaked: layer.filtersBaked,
  };
}

function restoreAssetEditSnapshot(snapshot, layer = selectedAssetLayer()) {
  if (!layer || !snapshot) return;
  Object.assign(layer, snapshot);
  $("#editor-preview-image").src = layer.src;
  $("#asset-hue").value = layer.hue || 0;
  $("#asset-saturation").value = layer.saturation || 1;
  $("#asset-opacity").value = layer.opacity ?? 1;
  $("#asset-brightness").value = layer.brightness || 1;
  updateEditorPreviewStyle(layer);
  if (!editorSession) {
    renderDesigner();
    autoSave();
  }
}

function pushEditorHistory() {
  const snapshot = assetEditSnapshot();
  if (!snapshot) return;
  editorUndoStack.push(snapshot);
  if (editorUndoStack.length > 50) editorUndoStack.shift();
  editorRedoStack.length = 0;
}

function undoEditorAction() {
  if (!editorUndoStack.length) return;
  const current = assetEditSnapshot();
  if (current) editorRedoStack.push(current);
  restoreAssetEditSnapshot(editorUndoStack.pop());
}

function redoEditorAction() {
  if (!editorRedoStack.length) return;
  const current = assetEditSnapshot();
  if (current) editorUndoStack.push(current);
  restoreAssetEditSnapshot(editorRedoStack.pop());
}

function openAssetEditor() {
  const sourceLayer = currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset");
  if (!sourceLayer) return;
  if (!sourceLayer.originalSrc) sourceLayer.originalSrc = sourceLayer.src;
  editorSession = {
    layerId: sourceLayer.id,
    original: { ...sourceLayer },
    draft: { ...sourceLayer },
  };
  editorUndoStack.length = 0;
  editorRedoStack.length = 0;
  const layer = editorSession.draft;
  $("#asset-editor").classList.remove("hidden");
  $("#editor-preview-image").src = layer.src;
  $("#asset-hue").value = layer.hue || 0;
  $("#asset-saturation").value = layer.saturation || 1;
  $("#asset-opacity").value = layer.opacity ?? 1;
  $("#asset-brightness").value = layer.brightness || 1;
  updateEditorPreviewStyle(layer);
  updateEditorModeUi();
  if (editorMode !== "select" && editorMode !== "free") {
    editorSelectionAction = null;
    editorFreePath = [];
    clearEditorSelection();
  }
}

function closeAssetEditor() {
  $("#asset-editor").classList.add("hidden");
  editorSession = null;
  editorMode = null;
  editorSelectionAction = null;
  editorFreePath = [];
  editorDragging = false;
  editorSelectionMoveAction = null;
  clearEditorSelection();
  $("#editor-transform-grid")?.classList.add("hidden");
  updateEditorModeUi();
}

function applyAssetEditor() {
  if (!editorSession?.draft) return;
  const target = currentFinger().layers.find((item) => item.id === editorSession.layerId);
  if (!target) return;
  pushHistory();
  Object.assign(target, editorSession.draft);
  editorSession = null;
  $("#asset-editor").classList.add("hidden");
  editorMode = null;
  editorSelectionAction = null;
  editorFreePath = [];
  editorDragging = false;
  editorSelectionMoveAction = null;
  clearEditorSelection();
  $("#editor-transform-grid")?.classList.add("hidden");
  updateEditorModeUi();
  renderDesigner();
  autoSave();
}

function clearEditorSelection() {
  const box = $("#editor-selection");
  if (!box) return;
  box.classList.remove("active", "free");
  box.style.left = "";
  box.style.top = "";
  box.style.width = "";
  box.style.height = "";
  box.style.clipPath = "";
}

function setEditorMode(mode) {
  editorMode = mode;
  editorDragging = false;
  editorSelectionMoveAction = null;
  editorTransformAction = null;
  if (mode === "select" || mode === "free") {
    editorSelectionAction = null;
    editorFreePath = [];
    clearEditorSelection();
  }
  renderEditorTransformGrid();
  updateEditorModeUi();
}

function updateEditorModeUi() {
  const preview = $("#editor-preview");
  if (preview) {
    preview.classList.toggle("mode-select", editorMode === "select");
    preview.classList.toggle("mode-free", editorMode === "free");
    preview.classList.toggle("mode-transform", editorMode === "transform");
  }
  $("#asset-rect-select")?.classList.toggle("active", editorMode === "select");
  $("#asset-free-select")?.classList.toggle("active", editorMode === "free");
  $("#asset-transform")?.classList.toggle("active", editorMode === "transform");
}

function updateEditorPreviewStyle(layer = selectedAssetLayer()) {
  if (!layer) return;
  const preview = $("#editor-preview");
  preview.style.setProperty("--asset-hue", `${layer.hue || 0}deg`);
  preview.style.setProperty("--asset-saturation", layer.saturation || 1);
  preview.style.setProperty("--asset-opacity", layer.opacity ?? 1);
  preview.style.setProperty("--asset-brightness", layer.brightness || 1);
}

function resetEditorPreviewFilter() {
  const preview = $("#editor-preview");
  if (!preview) return;
  preview.style.setProperty("--asset-hue", "0deg");
  preview.style.setProperty("--asset-saturation", 1);
  preview.style.setProperty("--asset-opacity", 1);
  preview.style.setProperty("--asset-brightness", 1);
}

function updateSelectedAssetFilter() {
  const layer = selectedAssetLayer();
  if (!layer) return;
  if (!filterUpdateTimer) pushEditorHistory();
  layer.hue = Number($("#asset-hue").value);
  layer.saturation = Number($("#asset-saturation").value);
  layer.opacity = Number($("#asset-opacity").value);
  layer.brightness = Number($("#asset-brightness").value);
  updateEditorPreviewStyle(layer);
  window.clearTimeout(filterUpdateTimer);
  filterUpdateTimer = window.setTimeout(() => bakeSelectedAssetFilters(layer), 60);
}

function bakeSelectedAssetFilters(layer = selectedAssetLayer()) {
  if (!layer) return;
  const source = layer.originalSrc || layer.src;
  const image = new Image();
  image.onload = () => {
    const canvas = document.createElement("canvas");
    canvas.width = 420;
    canvas.height = 760;
    const ctx = canvas.getContext("2d");
    ctx.filter = `hue-rotate(${layer.hue || 0}deg) saturate(${layer.saturation || 1}) brightness(${layer.brightness || 1})`;
    ctx.globalAlpha = layer.opacity ?? 1;
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
    layer.src = canvas.toDataURL();
    layer.filtersBaked = true;
    $("#editor-preview-image").src = layer.src;
    resetEditorPreviewFilter();
    filterUpdateTimer = null;
    if (!editorSession) {
      renderDesigner();
      autoSave();
    }
  };
  image.src = source;
}

function editorOperationBounds() {
  const preview = $("#editor-preview");
  if (!preview) return { x: 0, y: 0, w: 420, h: 760, scaleX: 1, scaleY: 1 };
  const rect = preview.getBoundingClientRect();
  if (!editorSelectionAction) return { x: 0, y: 0, w: 420, h: 760, cssX: 0, cssY: 0, cssW: rect.width, cssH: rect.height, scaleX: 420 / rect.width, scaleY: 760 / rect.height };
  const points = editorSelectionAction.mode === "free" && editorFreePath.length ? editorFreePath : [editorSelectionAction.start, editorSelectionAction.end];
  const x1Css = Math.max(0, Math.min(...points.map((point) => point.x)));
  const y1Css = Math.max(0, Math.min(...points.map((point) => point.y)));
  const x2Css = Math.min(rect.width, Math.max(...points.map((point) => point.x)));
  const y2Css = Math.min(rect.height, Math.max(...points.map((point) => point.y)));
  return {
    x: x1Css / rect.width * 420,
    y: y1Css / rect.height * 760,
    w: Math.max(1, (x2Css - x1Css) / rect.width * 420),
    h: Math.max(1, (y2Css - y1Css) / rect.height * 760),
    cssX: x1Css,
    cssY: y1Css,
    cssW: Math.max(1, x2Css - x1Css),
    cssH: Math.max(1, y2Css - y1Css),
    scaleX: 420 / rect.width,
    scaleY: 760 / rect.height,
  };
}

function editorSelectionBoundsCss() {
  const preview = $("#editor-preview");
  if (!preview || !editorSelectionAction) return null;
  const rect = preview.getBoundingClientRect();
  const points = editorSelectionAction.mode === "free" && editorFreePath.length ? editorFreePath : [editorSelectionAction.start, editorSelectionAction.end];
  const x1 = Math.max(0, Math.min(...points.map((point) => point.x)));
  const y1 = Math.max(0, Math.min(...points.map((point) => point.y)));
  const x2 = Math.min(rect.width, Math.max(...points.map((point) => point.x)));
  const y2 = Math.min(rect.height, Math.max(...points.map((point) => point.y)));
  if (x2 - x1 < 2 || y2 - y1 < 2) return null;
  return { x: x1, y: y1, w: x2 - x1, h: y2 - y1, rect };
}

function pointInsideEditorSelection(point) {
  const bounds = editorSelectionBoundsCss();
  if (!bounds) return false;
  if (point.x < bounds.x || point.x > bounds.x + bounds.w || point.y < bounds.y || point.y > bounds.y + bounds.h) return false;
  if (editorSelectionAction?.mode !== "free" || editorFreePath.length < 3) return true;
  let inside = false;
  for (let i = 0, j = editorFreePath.length - 1; i < editorFreePath.length; j = i, i += 1) {
    const a = editorFreePath[i];
    const b = editorFreePath[j];
    const intersects = ((a.y > point.y) !== (b.y > point.y)) && point.x < ((b.x - a.x) * (point.y - a.y)) / ((b.y - a.y) || 0.0001) + a.x;
    if (intersects) inside = !inside;
  }
  return inside;
}

function clampEditorSelectionDelta(dx, dy, originalPath, originalStart, originalEnd) {
  const preview = $("#editor-preview");
  if (!preview) return { dx, dy };
  const rect = preview.getBoundingClientRect();
  const points = originalPath?.length ? originalPath : [originalStart, originalEnd];
  const minX = Math.min(...points.map((point) => point.x));
  const maxX = Math.max(...points.map((point) => point.x));
  const minY = Math.min(...points.map((point) => point.y));
  const maxY = Math.max(...points.map((point) => point.y));
  return {
    dx: Math.max(-minX, Math.min(rect.width - maxX, dx)),
    dy: Math.max(-minY, Math.min(rect.height - maxY, dy)),
  };
}

function moveEditorSelection(dx, dy) {
  if (!editorSelectionMoveAction || !editorSelectionAction) return;
  const clamped = clampEditorSelectionDelta(
    dx,
    dy,
    editorSelectionMoveAction.originalPath,
    editorSelectionMoveAction.originalStart,
    editorSelectionMoveAction.originalEnd,
  );
  editorSelectionAction.start = {
    ...editorSelectionMoveAction.originalStart,
    x: editorSelectionMoveAction.originalStart.x + clamped.dx,
    y: editorSelectionMoveAction.originalStart.y + clamped.dy,
  };
  editorSelectionAction.end = {
    ...editorSelectionMoveAction.originalEnd,
    x: editorSelectionMoveAction.originalEnd.x + clamped.dx,
    y: editorSelectionMoveAction.originalEnd.y + clamped.dy,
  };
  if (editorSelectionAction.mode === "free") {
    editorFreePath = editorSelectionMoveAction.originalPath.map((point) => ({
      ...point,
      x: point.x + clamped.dx,
      y: point.y + clamped.dy,
    }));
  }
  renderEditorSelection();
}

function drawEditorSelectionMask(ctx, keepInside = true) {
  const rect = $("#editor-preview").getBoundingClientRect();
  ctx.beginPath();
  if (editorSelectionAction?.mode === "free" && editorFreePath.length > 2) {
    editorFreePath.forEach((point, index) => {
      const x = point.x / rect.width * 420;
      const y = point.y / rect.height * 760;
      if (index) ctx.lineTo(x, y);
      else ctx.moveTo(x, y);
    });
    ctx.closePath();
  } else if (editorSelectionAction) {
    const x1 = Math.min(editorSelectionAction.start.x, editorSelectionAction.end.x) / rect.width * 420;
    const y1 = Math.min(editorSelectionAction.start.y, editorSelectionAction.end.y) / rect.height * 760;
    const x2 = Math.max(editorSelectionAction.start.x, editorSelectionAction.end.x) / rect.width * 420;
    const y2 = Math.max(editorSelectionAction.start.y, editorSelectionAction.end.y) / rect.height * 760;
    ctx.rect(x1, y1, x2 - x1, y2 - y1);
  } else {
    ctx.rect(0, 0, 420, 760);
  }
  if (keepInside) ctx.clip();
}

function alphaBounds(canvas) {
  const ctx = canvas.getContext("2d");
  const { width, height } = canvas;
  const data = ctx.getImageData(0, 0, width, height).data;
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      if (data[(y * width + x) * 4 + 3] > 8) {
        if (x < minX) minX = x;
        if (y < minY) minY = y;
        if (x > maxX) maxX = x;
        if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < minX || maxY < minY) return null;
  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

function cropCanvasToBounds(canvas, bounds) {
  const cropped = document.createElement("canvas");
  cropped.width = Math.max(1, bounds.w);
  cropped.height = Math.max(1, bounds.h);
  cropped.getContext("2d").drawImage(canvas, bounds.x, bounds.y, bounds.w, bounds.h, 0, 0, bounds.w, bounds.h);
  return cropped;
}

const MeshWarp = {
  size: 4,
  points(bounds, anchorIndex, dx, dy) {
    const col = anchorIndex % this.size;
    const row = Math.floor(anchorIndex / this.size);
    const points = [];
    for (let y = 0; y < this.size; y += 1) {
      for (let x = 0; x < this.size; x += 1) {
        const source = {
          x: bounds.x + (bounds.w * x) / (this.size - 1),
          y: bounds.y + (bounds.h * y) / (this.size - 1),
        };
        const distance = Math.hypot(x - col, y - row);
        const influence = Math.exp(-(distance * distance) / 2.1);
        points.push({
          sx: source.x,
          sy: source.y,
          dx: source.x + dx * influence,
          dy: source.y + dy * influence,
        });
      }
    }
    return points;
  },
  drawTriangle(ctx, image, a, b, c) {
    const denom = a.sx * (b.sy - c.sy) + b.sx * (c.sy - a.sy) + c.sx * (a.sy - b.sy);
    if (Math.abs(denom) < 0.001) return;
    const m11 = (a.dx * (b.sy - c.sy) + b.dx * (c.sy - a.sy) + c.dx * (a.sy - b.sy)) / denom;
    const m12 = (a.dy * (b.sy - c.sy) + b.dy * (c.sy - a.sy) + c.dy * (a.sy - b.sy)) / denom;
    const m21 = (a.sx * (b.dx - c.dx) + b.sx * (c.dx - a.dx) + c.sx * (a.dx - b.dx)) / denom;
    const m22 = (a.sx * (b.dy - c.dy) + b.sx * (c.dy - a.dy) + c.sx * (a.dy - b.dy)) / denom;
    const dx = (a.sx * (b.sy * c.dx - c.sy * b.dx) + b.sx * (c.sy * a.dx - a.sy * c.dx) + c.sx * (a.sy * b.dx - b.sy * a.dx)) / denom;
    const dy = (a.sx * (b.sy * c.dy - c.sy * b.dy) + b.sx * (c.sy * a.dy - a.sy * c.dy) + c.sx * (a.sy * b.dy - b.sy * a.dy)) / denom;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(a.dx, a.dy);
    ctx.lineTo(b.dx, b.dy);
    ctx.lineTo(c.dx, c.dy);
    ctx.closePath();
    ctx.clip();
    ctx.transform(m11, m12, m21, m22, dx, dy);
    ctx.drawImage(image, 0, 0, 420, 760);
    ctx.restore();
  },
  render(ctx, image, bounds, anchorIndex, dx, dy) {
    const points = this.points(bounds, anchorIndex, dx, dy);
    for (let row = 0; row < this.size - 1; row += 1) {
      for (let col = 0; col < this.size - 1; col += 1) {
        const i = row * this.size + col;
        this.drawTriangle(ctx, image, points[i], points[i + 1], points[i + this.size]);
        this.drawTriangle(ctx, image, points[i + 1], points[i + this.size + 1], points[i + this.size]);
      }
    }
    return points;
  },
};

function cropAssetToSelection() {
  const layer = selectedAssetLayer();
  if (!layer) return;
  if (!editorSelectionAction) {
    showToast(lang === "zh" ? "请先建立一个选区。" : "Create a selection first.");
    return;
  }
  const cssBounds = editorSelectionBoundsCss();
  if (!cssBounds) {
    showToast(lang === "zh" ? "选区太小，请重新框选。" : "Selection is too small.");
    return;
  }
  pushEditorHistory();
  const image = new Image();
  image.onload = () => {
    const previewRect = $("#editor-preview").getBoundingClientRect();
    const sourceW = image.naturalWidth || image.width || 420;
    const sourceH = image.naturalHeight || image.height || 760;
    const scaleX = sourceW / previewRect.width;
    const scaleY = sourceH / previewRect.height;
    const sx = Math.max(0, Math.floor(cssBounds.x * scaleX));
    const sy = Math.max(0, Math.floor(cssBounds.y * scaleY));
    const sw = Math.max(1, Math.ceil(cssBounds.w * scaleX));
    const sh = Math.max(1, Math.ceil(cssBounds.h * scaleY));
    const canvas = document.createElement("canvas");
    canvas.width = sw;
    canvas.height = sh;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(image, sx, sy, sw, sh, 0, 0, sw, sh);
    if (editorSelectionAction.mode === "free" && editorFreePath.length > 2) {
      ctx.save();
      ctx.globalCompositeOperation = "destination-in";
      ctx.beginPath();
      editorFreePath.forEach((point, index) => {
        const x = (point.x - cssBounds.x) * scaleX;
        const y = (point.y - cssBounds.y) * scaleY;
        if (index) ctx.lineTo(x, y);
        else ctx.moveTo(x, y);
      });
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.save();
    const bounds = alphaBounds(canvas);
    ctx.restore();
    if (!bounds) {
      showToast(lang === "zh" ? "选区内没有可保留图像。" : "No image pixels inside the selection.");
      return;
    }
    const originalBox = { x: layer.x, y: layer.y, w: layer.w, h: layer.h };
    const cropped = cropCanvasToBounds(canvas, bounds);
    layer.x = originalBox.x + ((cssBounds.x + bounds.x / scaleX) / previewRect.width) * originalBox.w;
    layer.y = originalBox.y + ((cssBounds.y + bounds.y / scaleY) / previewRect.height) * originalBox.h;
    layer.w = Math.max(12, (bounds.w / scaleX / previewRect.width) * originalBox.w);
    layer.h = Math.max(12, (bounds.h / scaleY / previewRect.height) * originalBox.h);
    layer.src = cropped.toDataURL();
    layer.originalSrc = layer.src;
    $("#editor-preview-image").src = layer.src;
    editorSelectionAction = null;
    editorFreePath = [];
    clearEditorSelection();
    renderEditorTransformGrid();
  };
  image.src = layer.src;
}

function buildAnchorGrid() {
  const grid = $("#editor-transform-grid");
  if (!grid) return;
  grid.innerHTML = Array.from({ length: 16 }, (_, index) => `<button data-transform-anchor="${index}" aria-label="Anchor ${index + 1}"></button>`).join("");
}

function hslToRgb(h, s, l) {
  const hue2rgb = (p, q, tValue) => {
    let t2 = tValue;
    if (t2 < 0) t2 += 1;
    if (t2 > 1) t2 -= 1;
    if (t2 < 1 / 6) return p + (q - p) * 6 * t2;
    if (t2 < 1 / 2) return q;
    if (t2 < 2 / 3) return p + (q - p) * (2 / 3 - t2) * 6;
    return p;
  };
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  return [Math.round(hue2rgb(p, q, h + 1 / 3) * 255), Math.round(hue2rgb(p, q, h) * 255), Math.round(hue2rgb(p, q, h - 1 / 3) * 255)];
}

function rgbToHex(r, g, b) {
  return `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}

function hsvToRgb(h, s, v) {
  const hue = ((h % 360) + 360) % 360;
  const c = v * s;
  const x = c * (1 - Math.abs((hue / 60) % 2 - 1));
  const m = v - c;
  let rgb = [0, 0, 0];
  if (hue < 60) rgb = [c, x, 0];
  else if (hue < 120) rgb = [x, c, 0];
  else if (hue < 180) rgb = [0, c, x];
  else if (hue < 240) rgb = [0, x, c];
  else if (hue < 300) rgb = [x, 0, c];
  else rgb = [c, 0, x];
  return rgb.map((value) => Math.round((value + m) * 255));
}

function rgbToHsv(r, g, b) {
  const nr = r / 255;
  const ng = g / 255;
  const nb = b / 255;
  const max = Math.max(nr, ng, nb);
  const min = Math.min(nr, ng, nb);
  const delta = max - min;
  let hue = 0;
  if (delta) {
    if (max === nr) hue = 60 * (((ng - nb) / delta) % 6);
    else if (max === ng) hue = 60 * (((nb - nr) / delta) + 2);
    else hue = 60 * (((nr - ng) / delta) + 4);
  }
  if (hue < 0) hue += 360;
  const sat = max === 0 ? 0 : delta / max;
  return { h: hue, s: sat, v: max };
}

function clampChannel(value) {
  return Math.max(0, Math.min(255, Math.round(Number(value) || 0)));
}

function updateColorInputsFromState() {
  const [r, g, b] = hsvToRgb(colorPickerState.hue, colorPickerState.sat, colorPickerState.val);
  $("#color-r-input").value = r;
  $("#color-g-input").value = g;
  $("#color-b-input").value = b;
}

function updateSelectedColorPreview(color = colorPickerState.pendingColor || designerState.color) {
  const preview = $("#color-selection-preview");
  if (preview) preview.style.setProperty("--selected-color", color);
}

function applyColorState() {
  const [r, g, b] = hsvToRgb(colorPickerState.hue, colorPickerState.sat, colorPickerState.val);
  const color = rgbToHex(r, g, b);
  designerState.color = color;
  colorPickerState.pendingColor = color;
  updateSelectedColorPreview(color);
}

function drawColorStripCanvas() {
  const canvas = $("#color-strip-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
  [
    [0, "#ff0000"],
    [1 / 6, "#ffff00"],
    [2 / 6, "#00ff00"],
    [3 / 6, "#00ffff"],
    [4 / 6, "#0000ff"],
    [5 / 6, "#ff00ff"],
    [1, "#ff0000"],
  ].forEach(([stop, color]) => gradient.addColorStop(stop, color));
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const y = (colorPickerState.hue / 360) * canvas.height;
  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(3, y);
  ctx.lineTo(canvas.width - 3, y);
  ctx.stroke();
}

function drawColorPlaneCanvas() {
  const canvas = $("#color-plane-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const [rr, gg, bb] = hsvToRgb(colorPickerState.hue, 1, 1);
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = `rgb(${rr}, ${gg}, ${bb})`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const white = ctx.createLinearGradient(0, 0, canvas.width, 0);
  white.addColorStop(0, "rgba(255,255,255,1)");
  white.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = white;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const black = ctx.createLinearGradient(0, 0, 0, canvas.height);
  black.addColorStop(0, "rgba(0,0,0,0)");
  black.addColorStop(1, "rgba(0,0,0,1)");
  ctx.fillStyle = black;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const x = colorPickerState.sat * canvas.width;
  const y = (1 - colorPickerState.val) * canvas.height;
  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x, y, 7, 0, Math.PI * 2);
  ctx.stroke();
  ctx.strokeStyle = "rgba(45,35,48,0.75)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(x, y, 9, 0, Math.PI * 2);
  ctx.stroke();
}

function syncColorPickerFromCurrent() {
  const match = String(designerState.color || "").match(/^#?([0-9a-f]{6})$/i);
  if (!match) return;
  const hex = match[1];
  const rgb = [0, 2, 4].map((index) => parseInt(hex.slice(index, index + 2), 16));
  const hsv = rgbToHsv(rgb[0], rgb[1], rgb[2]);
  colorPickerState.hue = hsv.h;
  colorPickerState.sat = hsv.s;
  colorPickerState.val = hsv.v;
}

function renderColorPicker() {
  syncColorPickerFromCurrent();
  drawColorStripCanvas();
  drawColorPlaneCanvas();
  updateColorInputsFromState();
  const [r, g, b] = hsvToRgb(colorPickerState.hue, colorPickerState.sat, colorPickerState.val);
  colorPickerState.pendingColor = rgbToHex(r, g, b);
  updateSelectedColorPreview(colorPickerState.pendingColor);
}

function confirmColorSwatch() {
  const color = colorPickerState.pendingColor || designerState.color;
  designerState.color = color;
  addColorSwatch(color);
  $("#color-modal").classList.add("hidden");
  renderDesigner();
}

function addColorSwatch(color) {
  const grid = $("#draw-swatches");
  if (!grid) return;
  const existing = grid.querySelector(`[data-color="${color}"]`);
  if (existing) {
    existing.click();
    return;
  }
  const addButton = $("#add-color-swatch");
  const colorButtons = [...grid.querySelectorAll(".swatch[data-color]")];
  if (colorButtons.length >= 17) colorButtons[0]?.remove();
  const button = document.createElement("button");
  button.className = "swatch";
  button.dataset.color = color;
  button.style.setProperty("--swatch", color);
  button.setAttribute("aria-label", color);
  grid.insertBefore(button, addButton);
  $$("#draw-swatches .swatch").forEach((node) => node.classList.toggle("active", node === button));
}

function renderEditorTransformGrid() {
  const grid = $("#editor-transform-grid");
  if (!grid) return;
  if (editorMode !== "transform") {
    grid.classList.add("hidden");
    return;
  }
  const bounds = editorOperationBounds();
  grid.classList.remove("hidden");
  grid.style.left = `${bounds.cssX || 0}px`;
  grid.style.top = `${bounds.cssY || 0}px`;
  grid.style.width = `${bounds.cssW || $("#editor-preview").getBoundingClientRect().width}px`;
  grid.style.height = `${bounds.cssH || $("#editor-preview").getBoundingClientRect().height}px`;
  grid.style.right = "auto";
  grid.style.bottom = "auto";
}

function transformedDestination(bounds, anchorIndex, dx, dy) {
  const col = anchorIndex % 4;
  const row = Math.floor(anchorIndex / 4);
  const dest = { x: bounds.x, y: bounds.y, w: bounds.w, h: bounds.h };
  const canvasDx = dx * bounds.scaleX * 1.85;
  const canvasDy = dy * bounds.scaleY * 1.85;
  if (col === 0) {
    dest.x += canvasDx;
    dest.w -= canvasDx;
  } else if (col === 3) {
    dest.w += canvasDx;
  } else {
    dest.x += canvasDx * 0.55;
    dest.w += Math.abs(canvasDx) * 0.32;
  }
  if (row === 0) {
    dest.y += canvasDy;
    dest.h -= canvasDy;
  } else if (row === 3) {
    dest.h += canvasDy;
  } else {
    dest.y += canvasDy * 0.55;
    dest.h += Math.abs(canvasDy) * 0.32;
  }
  dest.w = Math.max(8, dest.w);
  dest.h = Math.max(8, dest.h);
  return dest;
}

function applyTransformDelta(action, dx, dy) {
  const layer = selectedAssetLayer();
  if (!layer || !action) return;
  const image = new Image();
  image.onload = () => {
    const out = document.createElement("canvas");
    out.width = 420;
    out.height = 760;
    const ctx = out.getContext("2d");
    ctx.drawImage(image, 0, 0, 420, 760);
    const source = document.createElement("canvas");
    source.width = 420;
    source.height = 760;
    const sourceCtx = source.getContext("2d");
    sourceCtx.save();
    if (action.hasSelection) drawEditorSelectionMask(sourceCtx, true);
    sourceCtx.drawImage(image, 0, 0, 420, 760);
    sourceCtx.restore();
    if (action.hasSelection) {
      ctx.save();
      ctx.globalCompositeOperation = "destination-out";
      drawEditorSelectionMask(ctx, true);
      ctx.fillRect(0, 0, 420, 760);
      ctx.restore();
    } else {
      ctx.clearRect(0, 0, 420, 760);
    }
    MeshWarp.render(ctx, source, action.bounds, action.anchorIndex, dx * action.bounds.scaleX * 1.7, dy * action.bounds.scaleY * 1.7);
    layer.src = out.toDataURL();
    layer.originalSrc = layer.src;
    $("#editor-preview-image").src = layer.src;
    if (!editorSession) {
      renderDesigner();
      autoSave();
    }
  };
  image.src = action.source;
}

function beginEditorTransform(event, anchorIndex) {
  const layer = selectedAssetLayer();
  if (!layer) return;
  event.preventDefault();
  pushEditorHistory();
  editorTransformAction = {
    anchorIndex,
    startX: event.clientX,
    startY: event.clientY,
    source: layer.src,
    bounds: editorOperationBounds(),
    hasSelection: Boolean(editorSelectionAction),
  };
  editorTransformMoved = false;
  event.currentTarget.setPointerCapture?.(event.pointerId);
}

function updateEditorTransform(event) {
  if (!editorTransformAction) return;
  const dx = event.clientX - editorTransformAction.startX;
  const dy = event.clientY - editorTransformAction.startY;
  if (Math.abs(dx) + Math.abs(dy) > 4) editorTransformMoved = true;
  const dest = transformedDestination(editorTransformAction.bounds, editorTransformAction.anchorIndex, dx, dy);
  const grid = $("#editor-transform-grid");
  if (grid) {
    grid.style.left = `${dest.x / 420 * $("#editor-preview").getBoundingClientRect().width}px`;
    grid.style.top = `${dest.y / 760 * $("#editor-preview").getBoundingClientRect().height}px`;
    grid.style.width = `${dest.w / 420 * $("#editor-preview").getBoundingClientRect().width}px`;
    grid.style.height = `${dest.h / 760 * $("#editor-preview").getBoundingClientRect().height}px`;
  }
}

function endEditorTransform(event) {
  if (!editorTransformAction) return;
  const action = editorTransformAction;
  editorTransformAction = null;
  const dx = event.clientX - action.startX;
  const dy = event.clientY - action.startY;
  if (editorTransformMoved) applyTransformDelta(action, dx, dy);
  event.currentTarget.releasePointerCapture?.(event.pointerId);
}

function applyAnchorWarp(index) {
  const layer = selectedAssetLayer();
  if (!layer) return;
  pushEditorHistory();
  const col = index % 4;
  const row = Math.floor(index / 4);
  applyTransformDelta({
    anchorIndex: index,
    startX: 0,
    startY: 0,
    source: layer.src,
    bounds: editorOperationBounds(),
    hasSelection: Boolean(editorSelectionAction),
  }, (col - 1.5) * 46, (row - 1.5) * 56);
}

function editorPoint(event) {
  const rect = $("#editor-preview").getBoundingClientRect();
  return {
    x: event.clientX - rect.left,
    y: event.clientY - rect.top,
    w: rect.width,
    h: rect.height,
  };
}

function beginEditorSelection(event) {
  if (editorMode !== "select" && editorMode !== "free") return;
  event.preventDefault();
  const point = editorPoint(event);
  if (editorSelectionAction && pointInsideEditorSelection(point)) {
    editorDragging = false;
    editorSelectionMoveAction = {
      start: point,
      originalStart: { ...editorSelectionAction.start },
      originalEnd: { ...editorSelectionAction.end },
      originalPath: editorFreePath.map((item) => ({ ...item })),
    };
    $("#editor-preview")?.setPointerCapture?.(event.pointerId);
    return;
  }
  editorDragging = true;
  editorSelectionMoveAction = null;
  editorSelectionAction = { start: point, end: point, mode: editorMode };
  editorFreePath = editorMode === "free" ? [point] : [];
  $("#editor-preview")?.setPointerCapture?.(event.pointerId);
  renderEditorSelection();
}

function updateEditorSelection(event) {
  if (editorSelectionMoveAction) {
    const point = editorPoint(event);
    moveEditorSelection(point.x - editorSelectionMoveAction.start.x, point.y - editorSelectionMoveAction.start.y);
    return;
  }
  if (!editorSelectionAction || !editorDragging) return;
  const point = editorPoint(event);
  editorSelectionAction.end = point;
  if (editorSelectionAction.mode === "free") editorFreePath.push(point);
  renderEditorSelection();
}

function renderEditorSelection() {
  const box = $("#editor-selection");
  if (!box || !editorSelectionAction) return;
  const previewRect = $("#editor-preview").getBoundingClientRect();
  const points = editorSelectionAction.mode === "free" && editorFreePath.length ? editorFreePath : [editorSelectionAction.start, editorSelectionAction.end];
  const x1 = Math.max(0, Math.min(...points.map((point) => point.x)));
  const y1 = Math.max(0, Math.min(...points.map((point) => point.y)));
  const x2 = Math.min(editorSelectionAction.start.w || 9999, Math.max(...points.map((point) => point.x)));
  const y2 = Math.min(editorSelectionAction.start.h || 9999, Math.max(...points.map((point) => point.y)));
  box.classList.add("active");
  box.classList.toggle("free", editorSelectionAction.mode === "free");
  if (editorSelectionAction.mode === "free" && editorFreePath.length > 2) {
    box.style.left = "0px";
    box.style.top = "0px";
    box.style.width = `${previewRect.width}px`;
    box.style.height = `${previewRect.height}px`;
    box.style.clipPath = `polygon(${editorFreePath.map((point) => `${Math.max(0, Math.min(100, point.x / previewRect.width * 100))}% ${Math.max(0, Math.min(100, point.y / previewRect.height * 100))}%`).join(", ")})`;
  } else {
    box.style.left = `${x1}px`;
    box.style.top = `${y1}px`;
    box.style.width = `${x2 - x1}px`;
    box.style.height = `${y2 - y1}px`;
    box.style.clipPath = "";
  }
  renderEditorTransformGrid();
}

function endEditorSelection(event) {
  if (!editorSelectionAction) return;
  editorSelectionMoveAction = null;
  editorDragging = false;
  if (event?.pointerId !== undefined) $("#editor-preview")?.releasePointerCapture?.(event.pointerId);
  renderEditorSelection();
}

function sampleCanvasColor(event) {
  const point = canvasPoint(event);
  const sample = document.createElement("canvas");
  sample.width = 420;
  sample.height = 760;
  const ctx = sample.getContext("2d");
  ctx.drawImage(assetCanvas(), 0, 0);
  ctx.drawImage(paintCanvas(), 0, 0);
  const data = ctx.getImageData(Math.max(0, Math.min(419, Math.round(point.x))), Math.max(0, Math.min(759, Math.round(point.y))), 1, 1).data;
  if (data[3] > 0) {
    const color = rgbToHex(data[0], data[1], data[2]);
    designerState.color = color;
    colorPickerState.pendingColor = color;
    syncColorPickerFromCurrent();
    drawColorStripCanvas();
    drawColorPlaneCanvas();
    updateColorInputsFromState();
    updateSelectedColorPreview(color);
    $("#color-modal")?.classList.remove("hidden");
  }
  eyedropperActive = false;
  showToast(lang === "zh" ? "已吸取画布颜色。" : "Canvas color picked.");
}

function renderObjectBox() {
  const box = $("#object-box");
  const edit = $("#object-edit");
  const rotate = $("#object-rotate");
  const layer = currentFinger().layers.find((item) => item.id === designerState.selectedObjectId && item.type === "asset");
  if (!box || !layer || !layer.visible) {
    box?.classList.add("hidden");
    edit?.classList.add("hidden");
    rotate?.classList.add("hidden");
    $("#transform-grid")?.classList.add("hidden");
    return;
  }
  const nail = $("#active-canvas-nail").getBoundingClientRect();
  box.classList.remove("hidden");
  if (!box.children.length) {
    box.innerHTML = ["nw", "ne", "sw", "se"].map((corner) => `<span class="object-resize-handle handle-${corner}"></span>`).join("");
  }
  const left = (layer.x / 420) * nail.width;
  const top = (layer.y / 760) * nail.height;
  const width = (layer.w / 420) * nail.width;
  const height = (layer.h / 760) * nail.height;
  box.style.left = `${left}px`;
  box.style.top = `${top}px`;
  box.style.width = `${width}px`;
  box.style.height = `${height}px`;
  box.style.transform = `rotate(${layer.rotation || 0}deg)`;
  edit.classList.toggle("hidden", Boolean(layer.temporaryPaintSelection));
  rotate?.classList.toggle("hidden", Boolean(layer.temporaryPaintSelection));
  if (!layer.temporaryPaintSelection) {
    const rotatedPoints = layerCanvasPoints(layer).map((point) => ({
      x: (point.x / 420) * nail.width,
      y: (point.y / 760) * nail.height,
    }));
    const bottomMid = {
      x: (rotatedPoints[2].x + rotatedPoints[3].x) / 2,
      y: (rotatedPoints[2].y + rotatedPoints[3].y) / 2,
    };
    edit.style.left = `${bottomMid.x - 64}px`;
    edit.style.top = `${bottomMid.y + 10}px`;
    if (rotate) {
      rotate.style.left = `${bottomMid.x}px`;
      rotate.style.top = `${bottomMid.y + 10}px`;
    }
  }
  renderTransformGrid();
}

function renderTransformGrid() {
  const grid = $("#transform-grid");
  const layer = selectedAssetLayer();
  if (!grid || !layer || !transformMode) {
    grid?.classList.add("hidden");
    return;
  }
  const nail = $("#active-canvas-nail").getBoundingClientRect();
  grid.classList.remove("hidden");
  grid.style.left = `${(layer.x / 420) * nail.width}px`;
  grid.style.top = `${(layer.y / 760) * nail.height}px`;
  grid.style.width = `${(layer.w / 420) * nail.width}px`;
  grid.style.height = `${(layer.h / 760) * nail.height}px`;
  if (!grid.children.length) {
    grid.innerHTML = Array.from({ length: 16 }, (_, index) => `<button data-transform-anchor="${index}" aria-label="Anchor ${index + 1}"></button>`).join("");
  }
}

function cycleShape() {
  return;
}

function combinedDesignDataUrl(width = 420, height = 760, format = "image/png", quality) {
  const out = document.createElement("canvas");
  out.width = width;
  out.height = height;
  const context = out.getContext("2d");
  const nail = currentFinger();
  const scaleX = width / 420;
  const scaleY = height / 760;
  nail.layers.slice().reverse().forEach((layer) => {
    if (!layer.visible) return;
    context.save();
    context.globalAlpha = layer.type === "asset" && layer.filtersBaked ? 1 : layer.opacity;
    if (layer.type === "asset" && layer.src) {
      const img = new Image();
      img.src = layer.src;
      try {
        context.drawImage(img, layer.x * scaleX, layer.y * scaleY, layer.w * scaleX, layer.h * scaleY);
      } catch {
        // Image may still be decoding; saved preview falls back to visible material.
      }
    } else if (layer.data) {
      const img = new Image();
      img.src = layer.data;
      try {
        context.drawImage(img, 0, 0, out.width, out.height);
      } catch {
        // Same async fallback as above.
      }
    }
    context.restore();
  });
  return quality == null ? out.toDataURL(format) : out.toDataURL(format, quality);
}

function draftPreviewDataUrl() {
  return combinedDesignDataUrl(168, 304, "image/png");
}

function cloneAllFingerDesigns() {
  return JSON.parse(JSON.stringify(fingerDesigns));
}

function createPersonalTemplateEntry({ mode = "drafts", auto = false } = {}) {
  saveCurrentCanvas();
  const thumb = draftPreviewDataUrl();
  const shape = currentFinger().shape;
  const now = new Date();
  const isDraft = mode === "drafts";
  return {
    source: "personal",
    mode,
    isAutoDraft: isDraft && auto,
    templateId: isDraft
      ? (auto ? AUTO_DRAFT_TEMPLATE_ID : `DRAFT-${now.getTime()}`)
      : `TPL-${now.getTime()}`,
    name: isDraft
      ? (auto ? t("autoDraftName") : `${t(shapeKeys[shape])} draft`)
      : `${t(shapeKeys[shape])} template`,
    zhName: isDraft
      ? (auto ? "自动保存 Draft" : `${t(shapeKeys[shape])} 草稿`)
      : `${t(shapeKeys[shape])} 模板`,
    author: "You",
    authorId: "@personal",
    authorLevel: isDraft ? (auto ? "Auto draft" : "Personal draft") : "Personal template",
    description: isDraft ? (auto ? t("autoDraftDescription") : "A saved personal draft from the design canvas.") : "A saved personal template from the design canvas.",
    shapeKey: shape,
    shapeLabel: t(shapeKeys[shape]),
    date: now.toISOString().slice(0, 10),
    savedAt: now.toISOString(),
    activeFinger: designerState.finger,
    fingerDesigns: cloneAllFingerDesigns(),
    likes: 0,
    comments: 0,
    thumb: `url(${thumb})`,
    image: thumb,
  };
}

function createPersonalTemplateDraft({ auto = false } = {}) {
  return createPersonalTemplateEntry({ mode: "drafts", auto });
}

function createSavedPersonalTemplate() {
  return createPersonalTemplateDraft({ auto: false });
}

function normalizePersonalTemplateOrder() {
  for (let index = designs.length - 1; index >= 0; index -= 1) {
    const design = designs[index];
    const isLegacyFavoritePlaceholder = design?.source === "personal"
      && (design.mode || "templates") === "favorites"
      && (design.name === "Saved Chrome Petal" || design.zhName === "收藏的镜面花瓣")
      && !design.templateId;
    if (isLegacyFavoritePlaceholder) designs.splice(index, 1);
  }
  designs.forEach((design) => {
    const isCanvasSavedPersonal = design?.source === "personal"
      && (design.fingerDesigns || design.activeFinger || design.authorId === "@personal")
      && !(design.mode === "favorites");
    if (!isCanvasSavedPersonal || design.mode === "drafts") return;
    design.mode = "drafts";
    design.templateId = design.templateId && String(design.templateId).startsWith("DRAFT-")
      ? design.templateId
      : `DRAFT-${design.savedAt ? new Date(design.savedAt).getTime() : Date.now()}`;
    design.authorLevel = design.isAutoDraft ? "Auto draft" : "Personal draft";
    design.description = design.isAutoDraft ? t("autoDraftDescription") : "A saved personal draft from the design canvas.";
  });
  const autoDrafts = designs.filter((design) => design.source === "personal" && design.mode === "drafts" && (design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID));
  if (!autoDrafts.length) return;
  const autoDraft = { ...autoDrafts[autoDrafts.length - 1], mode: "drafts", isAutoDraft: true, templateId: AUTO_DRAFT_TEMPLATE_ID };
  const others = designs.filter((design) => !(design.source === "personal" && design.mode === "drafts" && (design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID)));
  designs.length = 0;
  designs.push(...others.filter((design) => design.source !== "personal" || design.mode !== "drafts"));
  designs.push(autoDraft);
  designs.push(...others.filter((design) => design.source === "personal" && design.mode === "drafts"));
}

function persistPersonalDesigns() {
  normalizePersonalTemplateOrder();
  const payload = () => JSON.stringify(designs.filter((design) => design.source === "personal"));
  try {
    localStorage.setItem(PERSONAL_DESIGNS_KEY, payload());
    return true;
  } catch (error) {
    while (true) {
      const removable = designs
        .map((design, index) => ({ design, index }))
        .filter(({ design }) => design.source === "personal" && !(design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID))
        .sort((a, b) => new Date(a.design.savedAt || 0) - new Date(b.design.savedAt || 0))[0];
      if (!removable) break;
      designs.splice(removable.index, 1);
      normalizePersonalTemplateOrder();
      try {
        localStorage.setItem(PERSONAL_DESIGNS_KEY, payload());
        showToast(t("designSaveTrimmed"));
        return true;
      } catch {
        // Keep trimming until the browser can store the remaining drafts.
      }
    }
    console.error("Failed to persist personal designs", error);
    showToast(t("designSaveFailed"));
    return false;
  }
}

function storedUserSession() {
  try {
    return JSON.parse(localStorage.getItem(USER_SESSION_KEY) || "null");
  } catch {
    localStorage.removeItem(USER_SESSION_KEY);
    return null;
  }
}

function saveUserSession(session) {
  if (!session?.userId) return;
  persistentUser = session;
  localStorage.setItem(USER_SESSION_KEY, JSON.stringify(session));
}

function clearPersistentUser() {
  persistentUser = null;
  try {
    localStorage.removeItem(USER_SESSION_KEY);
  } catch (error) {
    console.warn("[user-session] Unable to clear persistent user", error);
  }
}

function ensurePersistentUser({ createGuest = false } = {}) {
  if (persistentUser?.userId) return Promise.resolve(persistentUser);
  if (userSessionPromise) return userSessionPromise;
  const existing = storedUserSession();
  if (!existing?.userId && !existing?.recoveryCode && !createGuest) return Promise.resolve(null);
  userSessionPromise = fetch("/api/user/session", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      userId: existing?.userId || "",
      recoveryCode: existing?.recoveryCode || "",
    }),
  })
    .then((response) => response.ok ? response.json() : Promise.reject(new Error("User session request failed")))
    .then((result) => {
      const user = result.user || result;
      saveUserSession({
        userId: user.userId,
        username: user.username,
        userKind: user.userKind || "guest",
        recoveryCode: user.recoveryCode || existing?.recoveryCode || "",
      });
      return persistentUser;
    })
    .catch((error) => {
      console.warn("[user-session] Unable to initialize persistent user", error);
      return null;
    })
    .finally(() => {
      userSessionPromise = null;
    });
  return userSessionPromise;
}

function activeActionUser() {
  if (currentAuthUser?.userId) {
    return Promise.resolve({
      userId: currentAuthUser.userId,
      recoveryCode: currentAuthUser.recoveryCode || "",
    });
  }
  return ensurePersistentUser();
}

function templateActionTarget(design, index) {
  return String(design?.templateId || design?.id || templateMeta(design || {}, index).id);
}

function updateCatalogTemplateCounts(templateId, counts = {}) {
  if (!templateId || !Array.isArray(publicCatalog?.templates)) return;
  const item = publicCatalog.templates.find((template) => template.template_id === templateId);
  if (!item) return;
  if (counts.likes !== undefined) item.like_count = counts.likes;
  if (counts.comments !== undefined) item.comment_count = counts.comments;
}

async function recordUserAction(targetType, targetId, actionType) {
  try {
    const user = await activeActionUser();
    if (!user?.userId || !targetId) return;
    await fetch("/api/user/action", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        userId: user.userId,
        recoveryCode: user.recoveryCode || "",
        targetType,
        targetId: String(targetId),
        actionType,
      }),
    });
  } catch (error) {
    console.warn("[user-action] Unable to record action", error);
  }
}

function personalAutoDraft() {
  return designs.find((design) => design.source === "personal" && design.mode === "drafts" && (design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID));
}

function shouldUseServerDraft(serverDraft) {
  if (!serverDraft?.content?.savedAt) return false;
  const localDraft = personalAutoDraft();
  if (!localDraft?.savedAt) return true;
  return new Date(serverDraft.content.savedAt).getTime() > new Date(localDraft.savedAt).getTime();
}

function mergeServerDesignDraft(serverDraft) {
  const draft = serverDraft?.content;
  if (!draft || !shouldUseServerDraft(serverDraft)) return false;
  const existingIndex = designs.findIndex((design) => design.source === "personal" && design.mode === "drafts" && (design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID));
  const normalizedDraft = { ...draft, isAutoDraft: true, templateId: AUTO_DRAFT_TEMPLATE_ID, source: "personal", mode: "drafts" };
  if (existingIndex >= 0) designs[existingIndex] = { ...designs[existingIndex], ...normalizedDraft };
  else designs.push(normalizedDraft);
  if (draft.fingerDesigns) {
    Object.keys(draft.fingerDesigns).forEach((finger) => {
      if (fingerDesigns[finger] && Array.isArray(draft.fingerDesigns[finger]?.layers)) {
        fingerDesigns[finger] = draft.fingerDesigns[finger];
      }
    });
    designerState.finger = draft.activeFinger || designerState.finger;
  }
  persistPersonalDesigns();
  normalizeFingerBaseStates(fingerDesigns.thumb?.material || "m123");
  renderDesigner();
  renderDesigns();
  return true;
}

async function loadServerAutoDraft() {
  const user = await ensurePersistentUser();
  if (!user?.userId) return;
  const params = new URLSearchParams({ userId: user.userId, draftId: AUTO_DRAFT_TEMPLATE_ID });
  if (user.recoveryCode) params.set("recoveryCode", user.recoveryCode);
  try {
    const response = await fetch(`/api/user/draft?${params.toString()}`);
    if (!response.ok) return;
    const result = await response.json();
    if (result.user) saveUserSession(result.user);
    mergeServerDesignDraft(result.draft);
  } catch (error) {
    console.warn("[draft-sync] Unable to load server draft", error);
  }
}

async function syncDraftToServer(draft) {
  if (!draft?.templateId) return;
  const user = await ensurePersistentUser();
  if (!user?.userId) return;
  try {
    const response = await fetch("/api/user/draft", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        userId: user.userId,
        recoveryCode: user.recoveryCode || "",
        draftId: draft.templateId,
        draftType: "design_canvas",
        isAutoDraft: Boolean(draft.isAutoDraft || draft.templateId === AUTO_DRAFT_TEMPLATE_ID),
        content: draft,
      }),
    });
    if (response.ok) {
      const result = await response.json();
      if (result.user) saveUserSession(result.user);
    }
  } catch (error) {
    console.warn("[draft-sync] Unable to save server draft", error);
  }
}

function upsertAutoDraftTemplate({ render = false, notify = false } = {}) {
  const draft = createPersonalTemplateDraft({ auto: true });
  const existingIndex = designs.findIndex((design) => design.source === "personal" && design.mode === "drafts" && (design.isAutoDraft || design.templateId === AUTO_DRAFT_TEMPLATE_ID));
  if (existingIndex >= 0) {
    designs[existingIndex] = { ...designs[existingIndex], ...draft };
  } else {
    designs.push(draft);
  }
  persistPersonalDesigns();
  syncDraftToServer(draft);
  if (render) renderDesigns();
  if (notify) showToast(t("autoSaved"));
}

function saveManualPersonalDraft({ render = true, notify = true } = {}) {
  const draft = createPersonalTemplateDraft({ auto: false });
  designs.push(draft);
  const saved = persistPersonalDesigns();
  if (!saved) return false;
  syncDraftToServer(draft);
  if (render) renderDesigns();
  if (notify) showToast(t("designSaved"));
  return true;
}

function startAutoDraftTimer() {
  window.clearInterval(autoDraftTimer);
  upsertAutoDraftTemplate({ render: activeD3View === "canvas" && activeCanvasSubpage === "drafts" });
  autoDraftTimer = window.setInterval(() => {
    upsertAutoDraftTemplate({ render: activeD3View === "canvas" && activeCanvasSubpage === "drafts" });
  }, AUTO_DRAFT_INTERVAL_MS);
}

function saveToPersonalTemplates() {
  return saveManualPersonalDraft();
}

async function exportTransparentPng() {
  saveCurrentCanvas();
  const out = document.createElement("canvas");
  out.width = 420;
  out.height = 760;
  const context = out.getContext("2d");
  context.save();
  applyNailClip(context, currentFinger().shape, out.width, out.height);
  for (const layer of currentFinger().layers.slice().reverse()) {
    if (!layer.visible) return;
    context.save();
    context.globalAlpha = layer.type === "asset" && layer.filtersBaked ? 1 : layer.opacity;
    if (layer.type === "asset" && layer.src) {
      await drawImageToCanvas(out, layer.src, (ctx, image) => ctx.drawImage(image, layer.x, layer.y, layer.w, layer.h));
    } else if (layer.data) {
      await drawImageToCanvas(out, layer.data, (ctx, image) => ctx.drawImage(image, 0, 0, out.width, out.height));
    }
    context.restore();
  }
  context.restore();
  const link = document.createElement("a");
  link.download = `nail-design-${Date.now()}.png`;
  link.href = out.toDataURL("image/png");
  link.click();
  showToast(t("designExported"));
}

function applyNailClip(context, shape, width, height) {
  context.beginPath();
  const map = {
    "long-oval": [0.5, 0.5, 0.42, 0.5],
    "short-oval": [0.5, 0.52, 0.47, 0.48],
    "short-round": [0.5, 0.54, 0.48, 0.45],
  };
  if (map[shape]) {
    const [cx, cy, rx, ry] = map[shape];
    context.ellipse(width * cx, height * cy, width * rx, height * ry, 0, 0, Math.PI * 2);
  } else {
    const points = {
      "short-square": [[0.18,0.04],[0.82,0.04],[0.94,0.18],[0.94,0.96],[0.06,0.96],[0.06,0.18]],
      "medium-square": [[0.20,0.02],[0.80,0.02],[0.94,0.16],[0.94,0.97],[0.06,0.97],[0.06,0.16]],
      squoval: [[0.22,0.02],[0.78,0.02],[0.94,0.20],[0.92,0.86],[0.76,0.98],[0.24,0.98],[0.08,0.86],[0.06,0.20]],
      almond: [[0.50,0],[0.73,0.10],[0.88,0.31],[0.94,0.72],[0.78,0.96],[0.50,1],[0.22,0.96],[0.06,0.72],[0.12,0.31],[0.27,0.10]],
      "medium-almond": [[0.50,0],[0.76,0.12],[0.91,0.36],[0.94,0.76],[0.75,0.98],[0.50,1],[0.25,0.98],[0.06,0.76],[0.09,0.36],[0.24,0.12]],
      "short-almond": [[0.50,0],[0.80,0.15],[0.94,0.42],[0.92,0.78],[0.73,0.97],[0.50,1],[0.27,0.97],[0.08,0.78],[0.06,0.42],[0.20,0.15]],
    }[shape];
    points.forEach(([x, y], index) => index ? context.lineTo(width * x, height * y) : context.moveTo(width * x, height * y));
    context.closePath();
  }
  context.clip();
}

document.addEventListener("click", async (event) => {
  if (event.target.closest("#open-login-modal, #auth-gate-login")) {
    openLoginModal();
    return;
  }
  if (event.target.closest("#auth-gate-guest")) {
    markGuestContinue();
    ensurePersistentUser({ createGuest: true });
    closeAuthGateModal();
    return;
  }
  if (event.target.closest("#close-login-modal")) {
    markGuestContinue();
    ensurePersistentUser({ createGuest: true });
    closeLoginModal();
    return;
  }
  if (event.target.closest("#forgot-password-link")) {
    openForgotPasswordModal();
    return;
  }
  if (event.target.closest("#close-forgot-password")) {
    closeForgotPasswordModal();
    openLoginModal();
    return;
  }
  if (event.target.closest("#forgot-request-code")) {
    requestForgotCode();
    return;
  }
  if (event.target.closest("#auth-logout")) {
    logoutUser();
    return;
  }
  if (event.target.closest("[data-auth-menu='templates']")) {
    activateView("design");
    personalMode = "favorites";
    $$("#personal-switch button").forEach((button) => button.classList.toggle("active", button.dataset.personal === "favorites"));
    activateDesignTab("personal");
    $("#personal-panel")?.scrollIntoView({ behavior: "smooth", block: "start" });
    return;
  }
  if (event.target.closest("[data-auth-menu='member']")) {
    activateView("member");
    $("#member-view")?.scrollIntoView({ behavior: "smooth", block: "start" });
    return;
  }

  const nav = event.target.closest(".nav-item");
  if (nav) activateView(nav.dataset.view);

  const campaign = event.target.closest("[data-campaign-target]");
  if (campaign) {
    window.location.href = campaign.dataset.campaignUrl || activityCampaigns[campaignSlideIndex % activityCampaigns.length].url;
    return;
  }

  if (event.target.closest("#home-how-print")) {
    activateView("design");
    $("#design-view .tab[data-tab='printcode']")?.click();
    $("#printcode-panel")?.scrollIntoView({ behavior: "smooth", block: "start" });
    return;
  }

  const homeTarget = event.target.closest("[data-home-target]");
  if (homeTarget) {
    const target = homeTarget.dataset.homeTarget;
    if (target === "member-task") {
      activateView("member");
      $(".member-hub-panel")?.scrollIntoView({ behavior: "smooth", block: "start" });
    } else if (target === "member-center") {
      activateView("member");
      $("#member-stats-board")?.scrollIntoView({ behavior: "smooth", block: "start" });
    } else if (target === "design-canvas") {
      activateView("design");
      $("#design-view .tab[data-tab='canvas']")?.click();
    } else if (target === "about") {
      activateView("about");
    }
    return;
  }

  const memberPanelButton = event.target.closest("[data-member-panel]");
  if (memberPanelButton && memberPanelButton.closest("#member-view")) {
    activateMemberPanel(memberPanelButton.dataset.memberPanel);
  }

  const memberNoticeButton = event.target.closest("[data-member-notice]");
  if (memberNoticeButton) {
    const notice = memberNotices.find((item) => item.id === memberNoticeButton.dataset.memberNotice);
    if (notice) {
      activateView("member");
      activateMemberPanel(notice.panel, notice.target);
    }
  }

  const memberJump = event.target.closest("[data-member-jump]");
  if (memberJump) {
    activateView("member");
    const target = memberJump.dataset.memberJump === "store"
      ? $("#member-store")
      : memberJump.dataset.memberJump === "task-list"
        ? $(".latest-task-list")
        : $("#member-stats-board");
    target?.scrollIntoView({ behavior: "smooth", block: "center" });
    target?.classList.add("notice-highlight");
    window.setTimeout(() => target?.classList.remove("notice-highlight"), 1800);
  }

  const communityCategory = event.target.closest("[data-community-category]");
  if (communityCategory) {
    activeCommunityCategory = communityCategory.dataset.communityCategory;
    renderPosts();
  }

  const tab = event.target.closest(".tab");
  if (tab) {
    const section = tab.closest(".view");
    if (section?.id === "design-view") {
      activateDesignTab(tab.dataset.tab);
    } else {
      section.querySelectorAll(".tab").forEach((button) => button.classList.toggle("active", button === tab));
      section.querySelectorAll(".tab-panel").forEach((panel) => panel.classList.toggle("active", panel.id === `${tab.dataset.tab}-panel`));
    }
  }

  const d3Nav = event.target.closest("[data-d3-view]");
  if (d3Nav) {
    activateD3Subpage(d3Nav.dataset.d3View);
  }

  if (event.target.closest(".mission-action, #complete-task")) {
    points += 60;
    renderRewards();
    showToast(t("taskDone"));
  }

  if (event.target.closest(".promo-use")) showToast(t("sampleApplied"));
  if (event.target.closest("#open-coupon-modal, #home-open-coupon-modal")) openCouponModal();
  if (event.target.closest("#close-coupon-modal")) closeCouponModal();
  const couponOption = event.target.closest("[data-coupon-index]");
  if (couponOption) openCouponDetail(Number(couponOption.dataset.couponIndex));
  if (event.target.closest("#activate-selected-coupon")) activateSelectedCoupon();
  if (event.target.closest("#open-cart")) openCart();
  if (event.target.closest("#close-cart")) closeCart();
  if (event.target.closest("#close-cart-edit-modal")) closeCartEdit();
  if (event.target.closest("#save-cart-edit")) saveCartEdit();
  const cartDelete = event.target.closest("[data-cart-delete]");
  if (cartDelete) removeCartLine(cartDelete.dataset.cartDelete);
  const cartEdit = event.target.closest("[data-cart-edit]");
  if (cartEdit) openCartEdit(cartEdit.dataset.cartEdit);
  if (event.target.closest("#open-product-filters")) {
    renderProductFilters();
    $("#product-filter-modal")?.classList.remove("hidden");
  }
  if (event.target.closest("#close-product-filters")) $("#product-filter-modal")?.classList.add("hidden");
  if (event.target.closest("#close-product-detail")) closeProductDetail();
  if (event.target.closest(".cart-checkout")) prepareCheckoutDraft("cart");
  const productPromoPage = event.target.closest("[data-product-promo-page]");
  if (productPromoPage) {
    event.preventDefault();
    event.stopPropagation();
    activeProductPromoIndex = Number(productPromoPage.dataset.productPromoPage || 0);
    renderProductPromoRail();
    startProductPromoAutoplay();
    return;
  }
  if (event.target.closest("#buy-product-now")) {
    const product = findProductById(activeProductIndex);
    activeProductRemark = String($("#product-detail-remark")?.value || "").trim();
    if (!product || productSizeStock(product, activeProductSize) <= 0 || !isActiveProductFulfillmentReady(product)) {
      event.preventDefault();
      if (product && productSizeStock(product, activeProductSize) > 0) promptMissingFulfillment(product);
      return;
    }
    prepareCheckoutDraft("buy-now");
  }
  const productCategory = event.target.closest("[data-product-category]");
  if (productCategory) {
    activeProductCategory = productCategory.dataset.productCategory;
    renderProductFilters();
    renderProducts();
  }
  const productFilterButton = event.target.closest("[data-product-filter-button]");
  if (productFilterButton) {
    const key = productFilterButton.dataset.productFilterButton;
    const value = productFilterButton.dataset.productFilterValue || "all";
    if (key === "type") activeProductType = value;
    if (key === "kind") activeProductKind = value;
    productRenderLimit = PRODUCT_RENDER_BATCH;
    renderProductFilters();
    renderProducts();
  }
  const productSize = event.target.closest("[data-product-size]");
  if (productSize) {
    activeProductSize = productSize.dataset.productSize;
    activeProductQty = 1;
    syncProductDetailSummary();
  }
  const productFulfillment = event.target.closest("[data-product-fulfillment]");
  if (productFulfillment && !productFulfillment.disabled) {
    const mode = productFulfillment.dataset.productFulfillment;
    if (mode === "pickup") openProductPickupModal();
    if (mode === "shipping") openProductShippingModal();
  }
  if (event.target.closest("#close-product-pickup-modal")) closeProductPickupModal();
  if (event.target.closest("#close-product-shipping-modal")) closeProductShippingModal();
  if (event.target.closest("#confirm-product-shipping")) confirmProductShippingAddress();
  const pickupDevice = event.target.closest("[data-pickup-device-index]");
  if (pickupDevice) selectPickupDevice(pickupDevice.dataset.pickupDeviceIndex);
  const productOpen = event.target.closest("[data-product-open]");
  if (productOpen) openProductDetail(productOpen.dataset.productOpen);
  if (event.target.closest("#add-product-cart")) addProductToCart();
  if (event.target.closest(".reward-redeem")) showToast(lang === "zh" ? "示例奖励已兑换。" : "Sample reward redeemed.");

  const galleryButton = event.target.closest("#gallery-source button");
  if (galleryButton) {
    activeSource = galleryButton.dataset.source;
    activeGalleryCategory = "all";
    activeGalleryFilters = {};
    resetTemplateRenderLimit();
    $$("#gallery-source button").forEach((button) => button.classList.toggle("active", button === galleryButton));
    renderGalleryCategories();
    renderDesigns();
  }

  const personalButton = event.target.closest("#personal-switch button");
  if (personalButton) {
    personalMode = personalButton.dataset.personal;
    $$("#personal-switch button").forEach((button) => button.classList.toggle("active", button === personalButton));
    renderPersonalDesigns();
  }

  const canvasSubButton = event.target.closest("#canvas-sub-switch button");
  if (canvasSubButton) {
    setCanvasSubpage(canvasSubButton.dataset.canvasSubpage);
  }

  if (event.target.closest("[data-open-template-library]")) {
    switchToPublicTemplateGallery({ communityFirst: true });
    return;
  }

  const galleryCategory = event.target.closest("[data-gallery-category]");
  if (galleryCategory) {
    activeGalleryCategory = galleryCategory.dataset.galleryCategory;
    activeGalleryFilters = activeGalleryCategory === "all" ? {} : { legacy: activeGalleryCategory };
    resetTemplateRenderLimit();
    renderGalleryCategories();
    renderDesigns();
  }

  const templateOpen = event.target.closest("[data-template-open]");
  if (templateOpen) {
    openTemplateDetail(Number(templateOpen.dataset.templateOpen), templateOpen.dataset.templateScope || "public");
    if (templateOpen.closest(".template-icon-actions")) {
      window.setTimeout(() => $("#template-comment-input")?.focus(), 120);
    }
  }

  const templateUseCanvas = event.target.closest("[data-template-use-canvas]");
  if (templateUseCanvas) {
    useTemplateInCanvas(
      Number(templateUseCanvas.dataset.templateUseCanvas),
      templateUseCanvas.dataset.templateScope || "personal",
    );
  }

  const templateLike = event.target.closest("[data-template-like]");
  if (templateLike) {
    const itemIndex = Number(templateLike.dataset.templateLike);
    const item = renderedTemplateByScope(templateLike.dataset.templateScope || "public", itemIndex);
    if (item) {
      item.likes = (item.likes || 0) + 1;
      updateCatalogTemplateCounts(item.templateId, { likes: item.likes });
      renderDesigns();
      if (item.templateId && item.source !== "personal") {
        templateSocialRequest({ action: "like_template", templateId: item.templateId })
        .then((payload) => {
          if (payload?.likeCount !== undefined) item.likes = payload.likeCount;
          updateCatalogTemplateCounts(item.templateId, { likes: item.likes });
          renderDesigns();
        })
          .catch((error) => {
            console.warn("[template-like] backend unavailable", error);
            recordUserAction("template", templateActionTarget(item, itemIndex), "like");
          });
      } else {
        recordUserAction("template", templateActionTarget(item, itemIndex), "like");
      }
      showToast(lang === "zh" ? "已点赞。" : "Liked.");
    }
  }

  if (event.target.closest("#upload-community-template")) openCommunityTemplateModal();
  if (event.target.closest("#close-community-template-upload")) closeCommunityTemplateModal();

  const saveGalleryButton = event.target.closest("[data-save-gallery]");
  if (saveGalleryButton) {
    const itemIndex = Number(saveGalleryButton.dataset.saveGallery);
    const item = renderedTemplateByScope(saveGalleryButton.dataset.templateScope || "public", itemIndex);
    if (!item) return;
    designs.push({ ...item, source: "personal", mode: "favorites", likes: 0, comments: 0 });
    persistPersonalDesigns();
    renderDesigns();
    recordUserAction("template", templateActionTarget(item, itemIndex), "favorite");
    showToast(t("designSaved"));
  }

  if (event.target.closest("#personal-delete-toggle")) {
    personalDeleteMode = !personalDeleteMode;
    $("#personal-delete-toggle")?.classList.toggle("active", personalDeleteMode);
    renderPersonalDesigns();
  }
  if (event.target.closest("#canvas-draft-delete-toggle")) {
    canvasDraftDeleteMode = !canvasDraftDeleteMode;
    $("#canvas-draft-delete-toggle")?.classList.toggle("active", canvasDraftDeleteMode);
    renderCanvasDrafts();
  }
  const deleteTemplate = event.target.closest("[data-delete-template]");
  if (deleteTemplate) {
    event.preventDefault();
    event.stopPropagation();
    openDeleteTemplateModal(Number(deleteTemplate.dataset.deleteTemplate), deleteTemplate.dataset.templateScope || "personal");
  }
  if (event.target.closest("#confirm-delete-template")) confirmDeleteTemplate();
  if (event.target.closest("#cancel-delete-template")) closeDeleteTemplateModal();

  if (event.target.closest("#close-template-detail")) closeTemplateDetail();
  if (event.target.closest("#cancel-template-reply")) {
    setTemplateReplyTarget(null);
    $("#template-comment-input")?.focus();
  }
  if (event.target.closest("#use-template-canvas")) useTemplateInCanvas();
  if (event.target.closest("#use-template-print")) useTemplateForPrint();
  if (event.target.closest("#open-print-order-entry")) openPrintOrderModal();
  if (event.target.closest("#close-print-order-modal")) closePrintOrderModal();
  if (event.target.closest("#open-print-order-create")) openPrintOrderCreateModal();
  if (event.target.closest("#close-print-order-create")) closePrintOrderCreateModal();
  if (event.target.closest("#confirm-print-order")) confirmPrintOrder();
  const aiOpen = event.target.closest("[data-ai-flow]");
  if (aiOpen) openAiWorkflow(aiOpen.dataset.aiFlow);
  if (event.target.closest("#close-ai-workflow")) closeAiWorkflow();
  const aiStep = event.target.closest("#ai-workflow-modal [data-ai-step]");
  if (aiStep) setAiWorkflowStep(aiStep.dataset.aiStep);
  const aiStyle = event.target.closest("#ai-style-tags [data-ai-style]");
  if (aiStyle) toggleAiStyle(aiStyle);
  const aiRemoveRef = event.target.closest("[data-ai-remove-ref]");
  if (aiRemoveRef) {
    aiReferenceImages.splice(Number(aiRemoveRef.dataset.aiRemoveRef), 1);
    renderAiReferences();
  }
  if (event.target.closest("#ai-generate-submit")) generateAiImage();
  const aiResult = event.target.closest("[data-ai-result-index]");
  if (aiResult) {
    selectAiImage(aiGeneratedImages[Number(aiResult.dataset.aiResultIndex)]);
  }
  const aiSampleResult = event.target.closest("[data-ai-sample-result]");
  if (aiSampleResult && !aiGeneratedImages.length) {
    const swatches = ["#ffd1e4", "#8c7cff", "#85e6d5"];
    const color = swatches[(Number(aiSampleResult.dataset.aiSampleResult) - 1) % swatches.length];
    selectedAiImage = makeTemplateDataUrl({ name: "AI Sample", thumb: `linear-gradient(135deg, #fff, ${color}, #ffffff)` }, currentFinger().shape);
    aiPreviewImage = await composeAiHandPreview([selectedAiImage, selectedAiImage, selectedAiImage, selectedAiImage, selectedAiImage]) || selectedAiImage;
    selectAiImage(selectedAiImage);
  }
  if (event.target.closest("#ai-regenerate-toggle")) $("#ai-regenerate-box")?.classList.toggle("hidden");
  if (event.target.closest("#ai-regenerate-submit")) generateAiImage($("#ai-regenerate-input")?.value || "", true);
  if (event.target.closest("#ai-next-preview")) {
    if (!selectedAiImage) showToast(t("aiNoResult"));
    else setAiWorkflowStep(3);
  }
  if (event.target.closest("#ai-use-canvas")) useAiResultInCanvas();
  if (event.target.closest("#ai-save-gallery")) saveAiResultToGallery();
  if (event.target.closest("#ai-export-local")) exportAiResultLocal();
  if (event.target.closest("#ai-print-direct")) printAiResultDirect();
  if (event.target.closest("#ai-share-placeholder")) showToast(lang === "zh" ? "分享功能占位。" : "Share placeholder.");
  const commentLike = event.target.closest("[data-comment-like]");
  if (commentLike && activeTemplateIndex !== null) {
    const design = renderedTemplateByScope();
    if (!design) return;
    const comments = ensureTemplateComments(design, activeTemplateIndex);
    const comment = findTemplateComment(comments, commentLike.dataset.commentLike);
    if (comment) {
      comment.likes = (comment.likes || 0) + 1;
      renderTemplateComments();
      templateSocialRequest({ action: "like_comment", commentId: comment.id })
        .then((payload) => {
          if (payload?.likeCount !== undefined) comment.likes = payload.likeCount;
          renderTemplateComments();
        })
        .catch((error) => {
          console.warn("[comment-like] backend unavailable", error);
          recordUserAction("comment", comment.id, "like");
        });
    }
  }
  const commentReply = event.target.closest("[data-comment-reply]");
  if (commentReply && activeTemplateIndex !== null) {
    setTemplateReplyTarget(commentReply.dataset.commentReply);
    $("#template-comment-input")?.focus();
  }
  if (event.target.closest("#print-template-action")) {
    const design = renderedTemplateByScope();
    if (design && activeTemplateIndex !== null) useTemplateForPrint(activeTemplateIndex, activeTemplateScope);
    else openPrintOrderModal();
    $("#print-status").textContent = lang === "zh" ? "请确认材质和设备后进入支付。" : "Confirm material and device before checkout.";
    showToast($("#print-status").textContent);
    if (design && activeTemplateIndex !== null) {
      recordUserAction("template", templateActionTarget(design, activeTemplateIndex), "print");
    }
  }

  const modeButton = event.target.closest(".designer-mode");
  if (modeButton) {
    designerState.mode = modeButton.dataset.designerMode;
    $("#brush-popover")?.classList.remove("show");
    openBrushSettingsFor = null;
    renderDesigner();
  }

  const fingerButton = event.target.closest(".finger-option");
  if (fingerButton) {
    saveCurrentCanvas();
    designerState.finger = fingerButton.dataset.finger;
    renderDesigner();
  }

  if (event.target.closest("#shape-next")) cycleShape();

  if (event.target.closest("#new-layer")) addPaintLayer();

  if (event.target.closest("#hide-right-panel")) {
    $("#designer-board")?.classList.add("right-panel-collapsed");
    $("#show-right-panel")?.classList.remove("hidden");
  }

  if (event.target.closest("#show-right-panel")) {
    $("#designer-board")?.classList.remove("right-panel-collapsed");
    $("#show-right-panel")?.classList.add("hidden");
  }

  const materialButton = event.target.closest(".material-tile[data-material]");
  if (materialButton && materialButton.closest("#material-panel")) {
    applyMaterialToAllFingers(materialButton.dataset.material);
  }

  const colorButton = event.target.closest("[data-color]");
  if (colorButton) {
    designerState.color = colorButton.dataset.color;
    $$("#draw-swatches .swatch").forEach((button) => button.classList.toggle("active", button === colorButton));
  }

  const brushButton = event.target.closest(".brush-option");
  if (brushButton) {
    detachBrushPopover();
    const wasOpen = openBrushSettingsFor === brushButton.dataset.brush && $("#brush-popover").classList.contains("show");
    designerState.brush = brushButton.dataset.brush;
    $$(".brush-option").forEach((button) => button.classList.toggle("active", button === brushButton));
    if (brushButton.closest("#brush-list")) {
      const popover = $("#brush-popover");
      const rect = brushButton.getBoundingClientRect();
      const width = 172;
      const rightSide = rect.right + 10;
      const leftSide = rect.left - width - 10;
      const preferredLeft = rightSide + width <= window.innerWidth - 12 ? rightSide : leftSide;
      const left = Math.max(12, Math.min(window.innerWidth - width - 12, preferredLeft));
      const top = Math.max(12, Math.min(window.innerHeight - 124, rect.top - 4));
      popover.style.setProperty("--brush-popover-left", `${left}px`);
      popover.style.setProperty("--brush-popover-top", `${top}px`);
      popover.classList.toggle("show", !wasOpen);
      openBrushSettingsFor = wasOpen ? null : brushButton.dataset.brush;
    } else {
      $("#brush-popover").classList.remove("show");
      openBrushSettingsFor = null;
    }
  }

  const libraryAsset = event.target.closest("[data-library-asset]");
  if (libraryAsset) importAssetToCanvas(libraryAsset.dataset.libraryAsset);

  const layerMenu = event.target.closest("[data-layer-menu]");
  if (layerMenu) {
    const layerId = layerMenu.dataset.layerMenu;
    openLayerMenuFor = openLayerMenuFor === layerId ? null : layerId;
    if (openLayerMenuFor !== layerId) openLayerOpacityFor = null;
    renderDesigner();
    return;
  }

  const layerToggle = event.target.closest("[data-layer-toggle]");
  if (layerToggle) {
    const layer = currentFinger().layers.find((item) => item.id === layerToggle.dataset.layerToggle);
    layer.visible = !layer.visible;
    renderDesigner();
    autoSave();
  }

  const layerOpacity = event.target.closest("[data-layer-opacity]");
  if (layerOpacity) {
    const layerId = layerOpacity.dataset.layerOpacity;
    openLayerOpacityFor = openLayerOpacityFor === layerId ? null : layerId;
    renderDesigner();
  }

  const layerDelete = event.target.closest("[data-layer-delete]");
  if (layerDelete) {
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    deleteLayer(layerDelete.dataset.layerDelete);
  }

  const layerDuplicate = event.target.closest("[data-layer-duplicate]");
  if (layerDuplicate) {
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    duplicateLayer(layerDuplicate.dataset.layerDuplicate);
  }

  const layerMergeDown = event.target.closest("[data-layer-merge-down]");
  if (layerMergeDown) {
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    mergeLayerDown(layerMergeDown.dataset.layerMergeDown, false);
  }

  const layerMergeAll = event.target.closest("[data-layer-merge-all]");
  if (layerMergeAll) {
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    mergeLayerDown(layerMergeAll.dataset.layerMergeAll, true);
  }

  if (event.target.closest("#undo-action")) undo();
  if (event.target.closest("#redo-action")) redo();
  if (event.target.closest("#object-edit")) openAssetEditor();
  if (event.target.closest("#close-asset-editor")) closeAssetEditor();
  if (event.target.closest("#apply-asset-edit")) applyAssetEditor();
  if (event.target.closest("#asset-crop-selection")) cropAssetToSelection();
  if (event.target.closest("#delete-box-selection")) cropAssetToSelection();
  if (event.target.closest("#delete-free-selection")) cropAssetToSelection();
  if (event.target.closest("#material-color-wheel, #draw-color-wheel")) {
    $("#color-modal").classList.remove("hidden");
    renderColorPicker();
  }
  if (event.target.closest("#close-color-modal")) $("#color-modal").classList.add("hidden");
  if (event.target.closest("#eyedropper-btn")) {
    eyedropperActive = true;
    $("#color-modal").classList.add("hidden");
    showToast(lang === "zh" ? "在画布上点击以吸取颜色。" : "Click the canvas to pick a color.");
  }
  if (event.target.closest("#add-color-swatch")) {
    $("#color-modal").classList.remove("hidden");
    renderColorPicker();
  }
  if (event.target.closest("#confirm-color-swatch")) {
    confirmColorSwatch();
  }
  const quickColor = event.target.closest("[data-quick-color]");
  if (quickColor) {
    designerState.color = quickColor.dataset.quickColor;
    syncColorPickerFromCurrent();
    colorPickerState.pendingColor = designerState.color;
    drawColorStripCanvas();
    drawColorPlaneCanvas();
    updateColorInputsFromState();
    updateSelectedColorPreview(designerState.color);
  }
  if (event.target.closest("#asset-rect-select") || event.target.closest("#asset-select-area")) {
    setEditorMode("select");
  }
  if (event.target.closest("#asset-free-select") || event.target.closest("#asset-free-area")) {
    setEditorMode("free");
  }
  if (event.target.closest("#asset-undo")) undoEditorAction();
  if (event.target.closest("#asset-redo")) redoEditorAction();
  const transformAnchor = event.target.closest("[data-transform-anchor]");
  if (transformAnchor) {
    event.preventDefault();
    if (!editorTransformMoved) applyAnchorWarp(Number(transformAnchor.dataset.transformAnchor));
    editorTransformMoved = false;
  }

  const layerRow = event.target.closest(".layer-row");
  if (layerRow && !event.target.closest("[data-layer-menu], [data-layer-toggle], [data-layer-opacity], [data-layer-opacity-slider], .layer-opacity-popover, [data-layer-delete], [data-layer-duplicate], [data-layer-merge-down], [data-layer-merge-all], [data-layer-drag]")) {
    designerState.activeLayerId = layerRow.dataset.layerId;
    const layer = currentFinger().layers.find((item) => item.id === designerState.activeLayerId);
    designerState.selectedObjectId = layer?.type === "asset" ? layer.id : null;
    renderDesigner();
  }

  if (event.target.closest("#apply-design")) openApplyTargetModal();
  if (event.target.closest("#export-design")) exportTransparentPng();
  if (event.target.closest("#exit-design")) openExitChoiceModal();

  if (event.target.closest("#save-design")) {
    openSaveChoiceModal();
  }

  if (event.target.closest("#close-apply-target")) closeApplyTargetModal();
  const applyTarget = event.target.closest("[data-apply-target]");
  if (applyTarget) applyCurrentDesignToFinger(applyTarget.dataset.applyTarget);

  if (event.target.closest("#close-save-choice")) closeSaveChoiceModal();
  if (event.target.closest("#confirm-save-design")) saveDesignDraft();
  if (event.target.closest("#save-design-as")) {
    if (!saveManualPersonalDraft()) return;
    closeSaveChoiceModal();
    switchToPersonalTemplateGallery("drafts");
  }
  if (event.target.closest("#cancel-exit-choice") || event.target.closest("#exit-save-cancel")) closeExitChoiceModal();
  if (event.target.closest("#exit-save-yes")) exitCanvas({ saveDraft: true });
  if (event.target.closest("#exit-save-no")) exitCanvas({ saveDraft: false });

  const printTutorialButton = event.target.closest("[data-print-tutorial]");
  if (printTutorialButton) setPrintTutorial(printTutorialButton.dataset.printTutorial);

  if (event.target.closest("#choose-template-from-print")) switchToPublicTemplateGallery({ communityFirst: true });
  const printGuideTarget = event.target.closest("[data-guide-target]");
  if (printGuideTarget) {
    if (printGuideTarget.dataset.guideTarget === "canvas") {
      activateDesignTab("canvas");
      setCanvasSubpage("canvas");
    }
    if (printGuideTarget.dataset.guideTarget === "gallery") {
      switchToPublicTemplateGallery({ communityFirst: true });
    }
  }
  if (event.target.closest("#activate-print-code")) {
    $("#print-status").textContent = t("printActivated");
    showToast(t("printActivated"));
  }
  if (event.target.closest("#print-design")) {
    const context = currentCanvasPrintContext();
    activateDesignTab("printcode");
    openPrintOrderModal(context);
  }

  if (event.target.closest("[data-jump='tasks']")) {
    activateView("member");
    activateMemberPanel("tasks");
  }
});

$("#layer-list")?.addEventListener("dragstart", (event) => {
  const handle = event.target.closest("[data-layer-drag]");
  if (!handle) return;
  layerDragId = handle.dataset.layerDrag;
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("text/plain", layerDragId);
  handle.closest(".layer-row")?.classList.add("dragging");
});

$("#layer-list")?.addEventListener("dragover", (event) => {
  if (!layerDragId) return;
  const row = event.target.closest(".layer-row");
  if (!row || row.dataset.layerId === layerDragId) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = "move";
  $$("#layer-list .layer-row").forEach((item) => item.classList.toggle("drag-over", item === row));
});

$("#layer-list")?.addEventListener("drop", (event) => {
  if (!layerDragId) return;
  const row = event.target.closest(".layer-row");
  event.preventDefault();
  $$("#layer-list .layer-row").forEach((item) => item.classList.remove("dragging", "drag-over"));
  if (row) reorderLayer(layerDragId, row.dataset.layerId);
  layerDragId = null;
});

$("#layer-list")?.addEventListener("dragend", () => {
  layerDragId = null;
  $$("#layer-list .layer-row").forEach((item) => item.classList.remove("dragging", "drag-over"));
});

$("#lang-toggle").addEventListener("click", () => {
  lang = lang === "en" ? "zh" : "en";
  document.documentElement.lang = lang === "en" ? "en" : "zh-CN";
  translatePage();
  renderProductFilters();
  renderProducts();
  renderCart();
});

$("#post-sort").addEventListener("click", (event) => {
  const button = event.target.closest("button");
  if (!button) return;
  postSort = button.dataset.sort;
  $$("#post-sort button").forEach((node) => node.classList.toggle("active", node === button));
  renderPosts();
});

$("#topic-filter")?.addEventListener("change", (event) => {
  topicFilter = event.target.value;
  renderPosts();
});

$("#global-search").addEventListener("input", (event) => {
  const term = event.target.value.trim().toLowerCase();
  $$(".task-card, .post-card, .promo-card, .reward-card, .design-card, .product-card").forEach((card) => {
    card.style.display = !term || card.textContent.toLowerCase().includes(term) ? "" : "none";
  });
});

$("#product-search")?.addEventListener("input", (event) => {
  productSearch = event.target.value;
  resetProductRenderLimit();
  renderProducts();
});

$("#product-category-grid")?.addEventListener("change", (event) => {
  const select = event.target.closest("[data-product-filter]");
  if (!select) return;
  if (select.dataset.productFilter === "style") activeProductStyle = select.value;
  if (select.dataset.productFilter === "shape") activeProductShape = select.value;
  if (select.dataset.productFilter === "type") activeProductType = select.value;
  if (select.dataset.productFilter === "kind") activeProductKind = select.value;
  resetProductRenderLimit();
  renderProductFilters();
  renderProducts();
});

$("#gallery-category-grid")?.addEventListener("change", (event) => {
  const select = event.target.closest("[data-gallery-filter]");
  if (!select) return;
  const key = select.dataset.galleryFilter;
  if (select.value === "all") {
    delete activeGalleryFilters[key];
  } else {
    activeGalleryFilters[key] = select.value;
  }
  activeGalleryCategory = "all";
  resetTemplateRenderLimit();
  renderGalleryCategories();
  renderDesigns();
});

$("#product-detail-qty")?.addEventListener("input", (event) => {
  activeProductQty = Math.max(1, Number(event.target.value || 1));
  syncProductDetailSummary();
});

$("#product-detail-remark")?.addEventListener("input", (event) => {
  activeProductRemark = String(event.target.value || "");
});

$("#cart-edit-size")?.addEventListener("change", (event) => {
  const line = productCart[activeCartEditIndex];
  const product = line ? findProductById(line.id) : null;
  const qtyInput = $("#cart-edit-qty");
  if (!product || !qtyInput) return;
  const stock = productSizeStock(product, String(event.target.value || "M").toUpperCase());
  qtyInput.max = String(Math.max(1, stock || 1));
  qtyInput.value = String(Math.max(1, Math.min(stock || 1, Number(qtyInput.value || 1))));
});

$("#brush-size").addEventListener("input", (event) => {
  designerState.brushSize = Number(event.target.value);
});

$("#brush-opacity").addEventListener("input", (event) => {
  designerState.brushOpacity = Number(event.target.value);
});

$("#layer-list").addEventListener("input", (event) => {
  const slider = event.target.closest("[data-layer-opacity-slider]");
  if (!slider) return;
  const layer = currentFinger().layers.find((item) => item.id === slider.dataset.layerOpacitySlider);
  if (!layer) return;
  layer.opacity = Math.max(0, Math.min(1, Number(slider.value) / 100));
  openLayerOpacityFor = layer.id;
  slider.previousElementSibling.textContent = `${slider.value}%`;
  compositeCanvases();
  autoSave();
});

$("#local-asset-input").addEventListener("change", (event) => {
  const file = event.target.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => importAssetToCanvas("local", reader.result);
  reader.readAsDataURL(file);
  event.target.value = "";
});

$("#ai-reference-input")?.addEventListener("change", (event) => {
  const files = [...(event.target.files || [])].slice(0, Math.max(0, 3 - aiReferenceImages.length));
  if (!files.length) return;
  Promise.all(files.map((file) => compressAiReferenceFile(file)))
    .then((images) => {
      aiReferenceImages.push(...images);
      aiReferenceImages = aiReferenceImages.slice(0, 3);
      renderAiReferences();
    })
    .catch(() => showToast(lang === "zh" ? "参考图读取失败。" : "Reference image failed to load."));
  event.target.value = "";
});

["#asset-hue", "#asset-saturation", "#asset-opacity", "#asset-brightness"].forEach((selector) => {
  $(selector).addEventListener("input", updateSelectedAssetFilter);
});

$("#color-strip-canvas").addEventListener("click", (event) => {
  const canvas = event.currentTarget;
  const rect = canvas.getBoundingClientRect();
  const y = Math.max(0, Math.min(rect.height, event.clientY - rect.top));
  colorPickerState.hue = (y / rect.height) * 360;
  drawColorStripCanvas();
  drawColorPlaneCanvas();
  updateColorInputsFromState();
  applyColorState();
});

$("#color-plane-canvas").addEventListener("click", (event) => {
  const canvas = event.currentTarget;
  const rect = canvas.getBoundingClientRect();
  const x = Math.max(0, Math.min(rect.width, event.clientX - rect.left));
  const y = Math.max(0, Math.min(rect.height, event.clientY - rect.top));
  colorPickerState.sat = x / rect.width;
  colorPickerState.val = 1 - (y / rect.height);
  drawColorPlaneCanvas();
  updateColorInputsFromState();
  applyColorState();
});

["#color-r-input", "#color-g-input", "#color-b-input"].forEach((selector) => {
  $(selector).addEventListener("input", () => {
    const r = clampChannel($("#color-r-input").value);
    const g = clampChannel($("#color-g-input").value);
    const b = clampChannel($("#color-b-input").value);
    const hsv = rgbToHsv(r, g, b);
    colorPickerState.hue = hsv.h;
    colorPickerState.sat = hsv.s;
    colorPickerState.val = hsv.v;
    $("#color-r-input").value = r;
    $("#color-g-input").value = g;
    $("#color-b-input").value = b;
    drawColorStripCanvas();
    drawColorPlaneCanvas();
    applyColorState();
  });
});

$("#editor-preview").addEventListener("pointerdown", (event) => {
  beginEditorSelection(event);
});

$("#editor-preview").addEventListener("pointermove", (event) => {
  updateEditorSelection(event);
});

$("#editor-preview").addEventListener("pointerup", (event) => {
  endEditorSelection(event);
});

$("#editor-preview").addEventListener("pointercancel", (event) => {
  endEditorSelection(event);
});

$("#editor-transform-grid").addEventListener("pointerdown", (event) => {
  const anchor = event.target.closest("[data-transform-anchor]");
  if (!anchor) return;
  beginEditorTransform(event, Number(anchor.dataset.transformAnchor));
});

$("#editor-transform-grid").addEventListener("pointermove", (event) => {
  updateEditorTransform(event);
});

$("#editor-transform-grid").addEventListener("pointerup", (event) => {
  endEditorTransform(event);
});

$("#editor-transform-grid").addEventListener("pointercancel", (event) => {
  endEditorTransform(event);
});

$("#object-rotate")?.addEventListener("pointerdown", (event) => {
  beginObjectRotate(event);
});

$("#object-rotate")?.addEventListener("pointermove", (event) => {
  updateObjectRotate(event);
});

$("#object-rotate")?.addEventListener("pointerup", (event) => {
  endObjectRotate(event);
});

$("#object-rotate")?.addEventListener("pointercancel", (event) => {
  endObjectRotate(event);
});

$("#canvas-viewport").addEventListener("pointerdown", (event) => {
  if (event.pointerType !== "touch") return;
  canvasView.pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
  if (canvasView.pointers.size === 2) {
    event.preventDefault();
    beginCanvasPinch();
  }
});

$("#canvas-viewport").addEventListener("pointermove", (event) => {
  if (!canvasView.pointers.has(event.pointerId)) return;
  canvasView.pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
  if (canvasView.pinching) {
    event.preventDefault();
    updateCanvasPinch();
  }
});

["pointerup", "pointercancel", "pointerleave"].forEach((type) => {
  $("#canvas-viewport").addEventListener(type, (event) => {
    if (!canvasView.pointers.has(event.pointerId)) return;
    canvasView.pointers.delete(event.pointerId);
    if (canvasView.pointers.size < 2) canvasView.pinching = false;
  });
});

function restoreSavedState() {
  try {
    restoreProductCart();
    const savedFingers = JSON.parse(localStorage.getItem("nailStudioFingerDesigns") || "null");
    if (savedFingers) {
      Object.keys(savedFingers).forEach((finger) => {
        if (fingerDesigns[finger] && Array.isArray(savedFingers[finger]?.layers)) {
          fingerDesigns[finger] = savedFingers[finger];
          if (!String(fingerDesigns[finger].material || "").startsWith("m")) fingerDesigns[finger].material = "m123";
        }
      });
    }
    const personal = JSON.parse(localStorage.getItem(PERSONAL_DESIGNS_KEY) || "[]");
    if (Array.isArray(personal)) {
      personal.forEach((item) => {
        const exists = item.templateId
          ? designs.some((design) => design.templateId === item.templateId)
          : designs.some((design) => design.name === item.name && design.source === "personal");
        if (!exists) designs.push(item);
      });
      normalizePersonalTemplateOrder();
      localStorage.setItem(PERSONAL_DESIGNS_KEY, JSON.stringify(designs.filter((design) => design.source === "personal")));
    }
  } catch {
    localStorage.removeItem("nailStudioFingerDesigns");
    localStorage.removeItem("nailStudioPersonalDesigns");
  }
  normalizeFingerBaseStates(fingerDesigns.thumb?.material || "m123");
  const layer = currentFinger().layers[0];
  designerState.activeLayerId = layer?.id || null;
}

paintCanvas().addEventListener("pointerdown", async (event) => {
  if (canvasView.pinching || canvasView.pointers.size > 1) return;
  if (eyedropperActive) {
    sampleCanvasColor(event);
    return;
  }
  if (designerState.selectedObjectId && beginObjectEdit(event)) {
    pushHistory();
    paintCanvas().setPointerCapture(event.pointerId);
    return;
  }
  if (designerState.brush === "select") {
    if (beginObjectEdit(event)) {
      pushHistory();
      paintCanvas().setPointerCapture(event.pointerId);
      return;
    }
    paintCanvas().setPointerCapture(event.pointerId);
    beginSelection(event);
    return;
  }
  if (designerState.mode === "import" && beginObjectEdit(event)) {
    pushHistory();
    paintCanvas().setPointerCapture(event.pointerId);
    return;
  }
  if (designerState.mode !== "draw") return;
  if (designerState.brush === "bucket") {
    floodFillAt(canvasPoint(event));
    return;
  }
  pushHistory();
  paintCanvas().setPointerCapture(event.pointerId);
  pendingDrawPointerId = event.pointerId;
  await loadPaintLayerForEditing(ensurePaintLayer());
  if (pendingDrawPointerId !== event.pointerId) return;
  pendingDrawPointerId = null;
  isDrawing = true;
  lastPoint = canvasPoint(event);
  moveBrushCursor(event);
});

paintCanvas().addEventListener("pointermove", (event) => {
  if (canvasView.pinching) return;
  moveBrushCursor(event);
  updateCanvasCursor(event);
  if (selectionAction) {
    updateSelection(event);
    return;
  }
  if (objectAction) {
    updateObjectEdit(event);
    return;
  }
  if (!isDrawing || designerState.mode !== "draw") return;
  const point = canvasPoint(event);
  drawStroke(lastPoint, point);
  lastPoint = point;
});

paintCanvas().addEventListener("pointerup", (event) => {
  if (pendingDrawPointerId === event.pointerId && !isDrawing) {
    pendingDrawPointerId = null;
    releasePaintPointer(event);
    return;
  }
  if (selectionAction) {
    endSelection();
    releasePaintPointer(event);
    return;
  }
  if (objectAction) {
    endObjectEdit();
    releasePaintPointer(event);
    return;
  }
  if (!isDrawing) return;
  isDrawing = false;
  lastPoint = null;
  saveCurrentCanvas();
  renderLayerList();
  autoSave();
  releasePaintPointer(event);
});

paintCanvas().addEventListener("pointercancel", (event) => {
  pendingDrawPointerId = null;
  isDrawing = false;
  objectAction = null;
  selectionAction = null;
  $("#selection-box")?.classList.remove("active");
  lastPoint = null;
  releasePaintPointer(event);
  saveCurrentCanvas();
  renderDesigner();
});

paintCanvas().addEventListener("pointerleave", () => {
  if (objectAction || selectionAction || isDrawing || pendingDrawPointerId !== null) return;
  paintCanvas().style.cursor = "";
  $(".brush-cursor").classList.remove("active");
});

document.addEventListener("pointerup", (event) => {
  if (objectAction) {
    endObjectEdit();
    releasePaintPointer(event);
  }
  if (selectionAction) {
    endSelection();
    releasePaintPointer(event);
  }
  if (pendingDrawPointerId === event.pointerId && !isDrawing) {
    pendingDrawPointerId = null;
    releasePaintPointer(event);
  }
});

document.addEventListener("pointercancel", (event) => {
  if (!objectAction && !selectionAction && pendingDrawPointerId === null && !isDrawing) return;
  pendingDrawPointerId = null;
  isDrawing = false;
  objectAction = null;
  selectionAction = null;
  lastPoint = null;
  $("#selection-box")?.classList.remove("active");
  releasePaintPointer(event);
  saveCurrentCanvas();
  renderDesigner();
});

buildAnchorGrid();
detachBrushPopover();
restoreSavedState();
loadServerAutoDraft();
installDebugBridge();
translatePage();
verifyStoredAuthSession();
startCampaignCarousel();
loadGalleryTaxonomy();
loadPublicCatalog();
applyInitialRoute();
startAutoDraftTimer();

const legacyDesignerApi = {
  renderDesigner,
  importAssetToCanvas,
  addPaintLayer,
  saveCurrentCanvas,
  saveToPersonalTemplates,
  exportTransparentPng,
  undo,
  redo,
};

window.nailStudioDebug = {
  ...(window.nailStudioDebug || {}),
  testSeedEditWithSavedImage,
  savedPersonalImages: () => designs.filter((design) => design.source === "personal" && templateImageSource(design)).map((design, index) => ({
    index,
    name: local(design, "name", "zhName"),
    id: design.id || "",
    templateId: design.templateId || "",
    shape: local({ name: design.shapeLabel, zhName: design.shapeLabel }, "name", "zhName") || design.shapeKey || "",
    savedAt: design.savedAt || "",
    imageLength: templateImageSource(design).length,
    imageType: templateImageSource(design).startsWith("data:") ? templateImageSource(design).slice(0, templateImageSource(design).indexOf(";") + 1) : "url",
    hasImage: Boolean(templateImageSource(design)),
  })),
};

let fabricCanvas = null;
let fabricReady = false;
let fabricLoadingFinger = false;
let fabricCurrentFinger = designerState.finger;
let fabricHistory = [];
let fabricRedoHistory = [];
const fabricLayerMeta = Object.fromEntries(fingers.map((finger) => [finger, [{ id: uid("fabric-paint"), type: "paint", name: "Paint 1", visible: true, opacity: 1 }]]));
const fabricBrushSettings = {
  pencil: { width: 10, opacity: 0.85, decimate: 0.4 },
  pixel: { width: 14, opacity: 1, decimate: 12 },
  watercolor: { width: 24, opacity: 0.28, decimate: 1 },
  ballpoint: { width: 4, opacity: 0.9, decimate: 0.25 },
  crayon: { width: 16, opacity: 0.72, decimate: 2 },
  eraser: { width: 22, opacity: 1, decimate: 0.5 },
};

function fabricStorageKey(finger = designerState.finger) {
  return `nailStudioFabric-${finger}`;
}

function fabricLayerKey(finger = designerState.finger) {
  return `nailStudioFabricLayers-${finger}`;
}

function isFabricEnabled() {
  return fabricReady && fabricCanvas;
}

function currentFabricMeta() {
  return fabricLayerMeta[designerState.finger] || [];
}

function selectedFabricLayerId() {
  const active = fabricCanvas?.getActiveObject();
  if (active?.layerId) return active.layerId;
  if (designerState.activeLayerId && currentFabricMeta().some((layer) => layer.id === designerState.activeLayerId)) return designerState.activeLayerId;
  return currentFabricMeta()[0]?.id || null;
}

function ensureFabricPaintLayer() {
  const layers = currentFabricMeta();
  let layer = layers.find((item) => item.id === designerState.activeLayerId && item.type === "paint");
  if (!layer) layer = layers.find((item) => item.type === "paint");
  if (!layer) {
    layer = { id: uid("fabric-paint"), type: "paint", name: `Paint ${layers.filter((item) => item.type === "paint").length + 1}`, visible: true, opacity: 1 };
    layers.unshift(layer);
  }
  designerState.activeLayerId = layer.id;
  return layer;
}

function saveFabricCanvasState() {
  if (!isFabricEnabled() || fabricLoadingFinger) return;
  const json = fabricCanvas.toJSON(["layerId", "layerName", "layerType"]);
  localStorage.setItem(fabricStorageKey(fabricCurrentFinger), JSON.stringify(json));
  localStorage.setItem(fabricLayerKey(fabricCurrentFinger), JSON.stringify(fabricLayerMeta[fabricCurrentFinger] || []));
  localStorage.setItem("nailStudioFingerDesigns", JSON.stringify(fingerDesigns));
}

function loadFabricLayerMeta(finger) {
  try {
    const saved = JSON.parse(localStorage.getItem(fabricLayerKey(finger)) || "null");
    if (Array.isArray(saved) && saved.length) {
      fabricLayerMeta[finger] = saved;
      return;
    }
  } catch {
    localStorage.removeItem(fabricLayerKey(finger));
  }
  if (!fabricLayerMeta[finger]?.length) {
    fabricLayerMeta[finger] = [{ id: uid("fabric-paint"), type: "paint", name: "Paint 1", visible: true, opacity: 1 }];
  }
}

function loadFabricCanvasState(finger) {
  if (!isFabricEnabled()) return;
  fabricLoadingFinger = true;
  fabricCanvas.clear();
  loadFabricLayerMeta(finger);
  try {
    const saved = JSON.parse(localStorage.getItem(fabricStorageKey(finger)) || "null");
    if (saved?.objects) {
      fabricCanvas.loadFromJSON(saved, () => {
        fabricLoadingFinger = false;
        fabricCanvas.getObjects().forEach((object) => {
          object.set({ borderColor: "#df5e93", cornerColor: "#df5e93", cornerStyle: "circle", transparentCorners: false });
        });
        applyFabricLayerVisibility();
        syncFabricBrush();
        fabricCanvas.renderAll();
        renderFabricLayerList();
      });
      return;
    }
  } catch {
    localStorage.removeItem(fabricStorageKey(finger));
  }
  fabricLoadingFinger = false;
  syncFabricBrush();
  fabricCanvas.renderAll();
  renderFabricLayerList();
}

function fabricSnapshot() {
  if (!isFabricEnabled()) return "";
  return JSON.stringify({
    json: fabricCanvas.toJSON(["layerId", "layerName", "layerType"]),
    meta: fabricLayerMeta[designerState.finger],
  });
}

function restoreFabricSnapshot(snapshot) {
  if (!isFabricEnabled() || !snapshot) return;
  const preferredLayerId = designerState.activeLayerId;
  const parsed = JSON.parse(snapshot);
  fabricLayerMeta[designerState.finger] = parsed.meta || fabricLayerMeta[designerState.finger];
  fabricLoadingFinger = true;
  fabricCanvas.loadFromJSON(parsed.json, () => {
    fabricLoadingFinger = false;
    if (preferredLayerId && currentFabricMeta().some((layer) => layer.id === preferredLayerId)) {
      designerState.activeLayerId = preferredLayerId;
      const object = fabricCanvas.getObjects().find((item) => item.layerId === preferredLayerId);
      if (object) fabricCanvas.setActiveObject(object);
      else fabricCanvas.discardActiveObject();
    }
    applyFabricLayerVisibility();
    fabricCanvas.renderAll();
    renderFabricLayerList();
    saveFabricCanvasState();
  });
}

function pushFabricHistory() {
  if (!isFabricEnabled()) return;
  fabricHistory.push(fabricSnapshot());
  if (fabricHistory.length > 50) fabricHistory.shift();
  fabricRedoHistory.length = 0;
}

function syncFabricBrush() {
  if (!isFabricEnabled()) return;
  const activeBrush = designerState.brush || "pencil";
  fabricCanvas.selection = activeBrush === "select";
  fabricCanvas.isDrawingMode = designerState.mode === "draw" && activeBrush !== "select" && activeBrush !== "bucket";
  fabricCanvas.getObjects().forEach((object) => {
    object.selectable = activeBrush === "select" || designerState.mode === "import";
    object.evented = object.selectable;
  });
  if (!fabricCanvas.isDrawingMode) return;
  const settings = fabricBrushSettings[activeBrush] || fabricBrushSettings.pencil;
  const brush = new fabric.PencilBrush(fabricCanvas);
  brush.width = activeBrush === "eraser" ? Math.max(4, designerState.brushSize || settings.width) : Math.max(1, designerState.brushSize || settings.width);
  brush.color = fabric.Color.fromHex(designerState.color || "#df5e93").setAlpha(activeBrush === "eraser" ? designerState.brushOpacity : designerState.brushOpacity || settings.opacity).toRgba();
  brush.decimate = settings.decimate;
  brush.strokeLineCap = activeBrush === "pixel" ? "square" : "round";
  brush.strokeLineJoin = activeBrush === "pixel" ? "miter" : "round";
  if (activeBrush === "eraser") brush.globalCompositeOperation = "destination-out";
  fabricCanvas.freeDrawingBrush = brush;
}

function applyFabricLayerVisibility() {
  if (!isFabricEnabled()) return;
  const layerMap = new Map(currentFabricMeta().map((layer) => [layer.id, layer]));
  fabricCanvas.getObjects().forEach((object) => {
    const layer = layerMap.get(object.layerId);
    if (!layer) return;
    object.visible = layer.visible;
    object.opacity = layer.opacity;
  });
}

function fabricObjectThumb(object) {
  try {
    return `<img class="layer-thumb" src="${object.toDataURL({ format: "png", multiplier: 0.25 })}" alt="" />`;
  } catch {
    return `<span class="layer-thumb"></span>`;
  }
}

function renderFabricLayerList() {
  if (!isFabricEnabled()) return legacyDesignerApi.renderDesigner();
  const list = $("#layer-list");
  if (!list) return;
  const objects = fabricCanvas.getObjects().slice().reverse();
  const layers = currentFabricMeta();
  const selectedId = selectedFabricLayerId();
  list.innerHTML = layers.map((layer) => {
    const object = objects.find((item) => item.layerId === layer.id);
    return `
      <div class="layer-row ${layer.id === selectedId ? "active" : ""} ${openLayerMenuFor === layer.id ? "layer-menu-open" : ""} ${layer.visible ? "" : "layer-hidden"}" data-layer-id="${layer.id}">
        ${object ? fabricObjectThumb(object) : "<span class=\"layer-thumb\"></span>"}
        <strong>${layer.name}</strong>
        <span class="layer-menu-caret" data-layer-menu="${layer.id}" aria-hidden="true">▾</span>
        <div class="layer-action-menu">
          <button data-layer-toggle="${layer.id}" title="${layer.visible ? t("hideLayer") : t("showLayer")}">${layerActionText(layer.visible ? "hide" : "show")}</button>
          <button data-layer-opacity="${layer.id}" title="${t("adjustOpacity")}">${layerActionText("opacity")}</button>
          <button data-layer-duplicate="${layer.id}" title="Duplicate layer">${layerActionText("duplicate")}</button>
          <button data-layer-merge-down="${layer.id}" title="Merge down">${layerActionText("mergeDown")}</button>
          <button data-layer-merge-all="${layer.id}" title="Merge all below">${layerActionText("mergeAll")}</button>
          <button data-layer-delete="${layer.id}" title="Delete">${layerActionText("delete")}</button>
        </div>
      </div>
    `;
  }).join("");
}

function renderFabricDesigner() {
  if (!isFabricEnabled()) return legacyDesignerApi.renderDesigner();
  const nail = $("#active-canvas-nail");
  normalizeFingerBaseStates(currentFinger().material);
  const current = currentFinger();
  if (!nail) return;
  if (fabricCurrentFinger !== designerState.finger) {
    saveFabricCanvasState();
    fabricCurrentFinger = designerState.finger;
    loadFabricCanvasState(fabricCurrentFinger);
  }
  $("#designer-board")?.classList.toggle("draw-mode", designerState.mode === "draw");
  nail.className = `canvas-nail material-base material-${current.material} fabric-active`;
  nail.style.setProperty("--fitted-nail", materialBaseImageForFinger(current.material, designerState.finger));
  nail.classList.add("hide-guide");
  $$(".finger-option").forEach((button) => {
    const selected = button.dataset.finger === designerState.finger;
    const finger = fingerDesigns[button.dataset.finger];
    button.classList.toggle("active", selected);
    const mini = button.querySelector(".mini-nail");
    mini.className = `mini-nail material-base material-${finger.material}`;
    mini.style.setProperty("--fitted-nail", materialBaseImageForFinger(finger.material, button.dataset.finger));
  });
  $$(".designer-mode").forEach((button) => button.classList.toggle("active", button.dataset.designerMode === designerState.mode));
  $$(".dynamic-panel").forEach((panel) => panel.classList.toggle("active", panel.id === `${designerState.mode}-panel`));
  $$(".swatch, .material-tile").forEach((button) => button.classList.toggle("active", button.dataset.material === current.material || button.dataset.color === designerState.color));
  $$(".brush-option").forEach((button) => button.classList.toggle("active", button.dataset.brush === designerState.brush));
  $("#brush-size").value = designerState.brushSize;
  $("#brush-opacity").value = designerState.brushOpacity;
  syncFabricBrush();
  applyFabricLayerVisibility();
  renderFabricLayerList();
  fabricCanvas.renderAll();
}

function addFabricPaintLayer() {
  if (!isFabricEnabled()) return legacyDesignerApi.addPaintLayer();
  pushFabricHistory();
  const count = currentFabricMeta().filter((layer) => layer.type === "paint").length + 1;
  const layer = { id: uid("fabric-paint"), type: "paint", name: `Paint ${count}`, visible: true, opacity: 1 };
  currentFabricMeta().unshift(layer);
  designerState.activeLayerId = layer.id;
  fabricCanvas.discardActiveObject();
  renderFabricDesigner();
  saveFabricCanvasState();
}

function makeFabricLibraryAsset(kind) {
  return makeLibraryAsset(kind);
}

function importFabricAsset(kind, imageSource) {
  if (!isFabricEnabled()) return legacyDesignerApi.importAssetToCanvas(kind, imageSource);
  pushFabricHistory();
  const src = imageSource || makeFabricLibraryAsset(kind);
  fabric.Image.fromURL(src, (image) => {
    const maxWidth = 190;
    const scale = maxWidth / Math.max(image.width || maxWidth, image.height || maxWidth);
    const layer = { id: uid("fabric-asset"), type: "asset", name: kind === "local" ? "Local Image" : `${kind} asset`, visible: true, opacity: 1 };
    currentFabricMeta().unshift(layer);
    image.set({
      left: 115,
      top: 250,
      scaleX: scale,
      scaleY: scale,
      layerId: layer.id,
      layerName: layer.name,
      layerType: "asset",
      borderColor: "#df5e93",
      cornerColor: "#df5e93",
      cornerStyle: "circle",
      transparentCorners: false,
    });
    fabricCanvas.add(image);
    fabricCanvas.setActiveObject(image);
    designerState.activeLayerId = layer.id;
    designerState.selectedObjectId = layer.id;
    renderFabricDesigner();
    saveFabricCanvasState();
    showToast(t("sampleImported"));
  }, { crossOrigin: "anonymous" });
}

function selectFabricLayer(layerId) {
  if (!isFabricEnabled()) return;
  designerState.activeLayerId = layerId;
  const object = fabricCanvas.getObjects().find((item) => item.layerId === layerId);
  if (object) fabricCanvas.setActiveObject(object);
  else fabricCanvas.discardActiveObject();
  renderFabricDesigner();
}

function deleteFabricLayer(layerId) {
  if (!isFabricEnabled()) return deleteLayer(layerId);
  pushFabricHistory();
  const layers = currentFabricMeta();
  const index = layers.findIndex((layer) => layer.id === layerId);
  if (index === -1) return;
  const objects = fabricCanvas.getObjects().filter((object) => object.layerId === layerId);
  objects.forEach((object) => fabricCanvas.remove(object));
  layers.splice(index, 1);
  if (!layers.length) layers.push({ id: uid("fabric-paint"), type: "paint", name: "Paint 1", visible: true, opacity: 1 });
  designerState.activeLayerId = layers[0].id;
  fabricCanvas.discardActiveObject();
  renderFabricDesigner();
  saveFabricCanvasState();
}

function duplicateFabricLayer(layerId) {
  if (!isFabricEnabled()) return duplicateLayer(layerId);
  const layers = currentFabricMeta();
  const index = layers.findIndex((layer) => layer.id === layerId);
  if (index === -1) return;
  pushFabricHistory();
  const sourceLayer = layers[index];
  const cloneLayer = { ...sourceLayer, id: uid(sourceLayer.type || "fabric-layer"), name: `${sourceLayer.name || "Layer"} Copy` };
  layers.splice(index, 0, cloneLayer);
  const objects = fabricCanvas.getObjects().filter((object) => object.layerId === layerId);
  if (!objects.length) {
    designerState.activeLayerId = cloneLayer.id;
    renderFabricDesigner();
    saveFabricCanvasState();
    return;
  }
  let remaining = objects.length;
  objects.forEach((object) => {
    object.clone((clone) => {
      clone.set({
        left: (clone.left || 0) + 12,
        top: (clone.top || 0) + 12,
        layerId: cloneLayer.id,
        layerName: cloneLayer.name,
        layerType: cloneLayer.type,
        borderColor: "#df5e93",
        cornerColor: "#df5e93",
        cornerStyle: "circle",
        transparentCorners: false,
      });
      fabricCanvas.add(clone);
      remaining -= 1;
      if (!remaining) {
        designerState.activeLayerId = cloneLayer.id;
        fabricCanvas.setActiveObject(clone);
        renderFabricDesigner();
        saveFabricCanvasState();
      }
    });
  });
}

function fabricMergedLayerImage(layerIds) {
  const original = fabricCanvas.getObjects().map((object) => ({ object, visible: object.visible }));
  fabricCanvas.getObjects().forEach((object) => {
    object.visible = layerIds.includes(object.layerId);
  });
  fabricCanvas.discardActiveObject();
  fabricCanvas.renderAll();
  const data = fabricCanvas.toDataURL({ format: "png", multiplier: 1 });
  original.forEach(({ object, visible }) => {
    object.visible = visible;
  });
  fabricCanvas.renderAll();
  return data;
}

function mergeFabricLayerDown(layerId, mergeAll = false) {
  if (!isFabricEnabled()) return mergeLayerDown(layerId, mergeAll);
  const layers = currentFabricMeta();
  const index = layers.findIndex((layer) => layer.id === layerId);
  if (index === -1 || index >= layers.length - 1) return;
  pushFabricHistory();
  const group = mergeAll ? layers.slice(index) : layers.slice(index, index + 2);
  const layerIds = group.map((layer) => layer.id);
  const data = fabricMergedLayerImage(layerIds);
  fabricCanvas.getObjects()
    .filter((object) => layerIds.includes(object.layerId))
    .forEach((object) => fabricCanvas.remove(object));
  const merged = { id: uid("fabric-merged"), type: "paint", name: mergeAll ? "Merged Layers" : "Merged Layer", visible: true, opacity: 1 };
  layers.splice(index, mergeAll ? layers.length - index : 2, merged);
  fabric.Image.fromURL(data, (image) => {
    image.set({
      left: 0,
      top: 0,
      scaleX: 1,
      scaleY: 1,
      layerId: merged.id,
      layerName: merged.name,
      layerType: "paint",
      selectable: designerState.brush === "select",
      evented: designerState.brush === "select",
      borderColor: "#df5e93",
      cornerColor: "#df5e93",
      cornerStyle: "circle",
      transparentCorners: false,
    });
    fabricCanvas.add(image);
    designerState.activeLayerId = merged.id;
    fabricCanvas.setActiveObject(image);
    renderFabricDesigner();
    saveFabricCanvasState();
  });
}

function setFabricLayerVisibility(layerId) {
  if (!isFabricEnabled()) return;
  const layer = currentFabricMeta().find((item) => item.id === layerId);
  if (!layer) return;
  pushFabricHistory();
  layer.visible = !layer.visible;
  applyFabricLayerVisibility();
  renderFabricDesigner();
  saveFabricCanvasState();
}

function setFabricLayerOpacity(layerId) {
  if (!isFabricEnabled()) return;
  const layer = currentFabricMeta().find((item) => item.id === layerId);
  if (!layer) return;
  pushFabricHistory();
  layer.opacity = layer.opacity <= 0.35 ? 1 : Math.max(0.25, layer.opacity - 0.25);
  applyFabricLayerVisibility();
  renderFabricDesigner();
  saveFabricCanvasState();
}

function combinedFabricDesignDataUrl(includeMaterial = false) {
  if (!isFabricEnabled()) return combinedDesignDataUrl();
  const out = document.createElement("canvas");
  out.width = 420;
  out.height = 760;
  const ctx = out.getContext("2d");
  ctx.save();
  applyNailClip(ctx, currentFinger().shape, out.width, out.height);
  if (includeMaterial) {
    ctx.fillStyle = "#fff8fb";
    ctx.fillRect(0, 0, out.width, out.height);
  }
  const data = fabricCanvas.toDataURL({ format: "png", multiplier: 1, withoutTransform: false });
  const img = new Image();
  img.src = data;
  try {
    ctx.drawImage(img, 0, 0, out.width, out.height);
  } catch {
    return data;
  }
  ctx.restore();
  return out.toDataURL("image/png");
}

function saveFabricToPersonalTemplates() {
  if (!isFabricEnabled()) return legacyDesignerApi.saveToPersonalTemplates();
  saveFabricCanvasState();
  const thumb = fabricCanvas.toDataURL({ format: "jpeg", quality: 0.72, multiplier: 0.45 });
  designs.push({
    source: "personal",
    mode: "templates",
    name: `${t(shapeKeys[currentFinger().shape])} Fabric draft`,
    zhName: `${t(shapeKeys[currentFinger().shape])}草稿`,
    likes: 0,
    comments: 0,
    thumb: `url(${thumb})`,
    image: thumb,
  });
  if (!persistPersonalDesigns()) return false;
  renderDesigns();
  showToast(t("designSaved"));
  return true;
}

function exportFabricTransparentPng() {
  if (!isFabricEnabled()) return legacyDesignerApi.exportTransparentPng();
  saveFabricCanvasState();
  const link = document.createElement("a");
  link.download = `nail-design-${Date.now()}.png`;
  link.href = fabricCanvas.toDataURL({ format: "png", multiplier: 2 });
  link.click();
  showToast(t("designExported"));
}

function initFabricDesigner() {
  return;
  if (!window.fabric || fabricReady || !paintCanvas()) return;
  $("#active-canvas-nail")?.classList.add("fabric-active");
  assetCanvas()?.getContext("2d")?.clearRect(0, 0, assetCanvas().width, assetCanvas().height);
  fabricCanvas = new fabric.Canvas("nail-canvas", {
    preserveObjectStacking: true,
    selection: true,
    backgroundColor: "rgba(255,255,255,0)",
  });
  fabricCanvas.setWidth(420);
  fabricCanvas.setHeight(760);
  fabricReady = true;
  fabricCanvas.on("mouse:down", () => {
    if (designerState.mode === "draw" || designerState.mode === "import") pushFabricHistory();
  });
  fabricCanvas.on("path:created", (event) => {
    const layer = ensureFabricPaintLayer();
    const path = event.path;
    path.set({
      layerId: layer.id,
      layerName: layer.name,
      layerType: "paint",
      selectable: designerState.brush === "select",
      evented: designerState.brush === "select",
      opacity: layer.opacity,
    });
    if (designerState.brush === "crayon") path.set({ strokeDashArray: [2, 3] });
    saveFabricCanvasState();
    renderFabricLayerList();
  });
  fabricCanvas.on("selection:created", () => {
    designerState.activeLayerId = selectedFabricLayerId();
    renderFabricLayerList();
  });
  fabricCanvas.on("selection:updated", () => {
    designerState.activeLayerId = selectedFabricLayerId();
    renderFabricLayerList();
  });
  fabricCanvas.on("selection:cleared", renderFabricLayerList);
  fabricCanvas.on("object:modified", () => {
    saveFabricCanvasState();
    renderFabricLayerList();
  });
  fabricCanvas.on("object:added", () => {
    if (!fabricLoadingFinger) saveFabricCanvasState();
  });
  renderDesigner = renderFabricDesigner;
  importAssetToCanvas = importFabricAsset;
  addPaintLayer = addFabricPaintLayer;
  saveCurrentCanvas = saveFabricCanvasState;
  saveToPersonalTemplates = saveFabricToPersonalTemplates;
  exportTransparentPng = exportFabricTransparentPng;
  undo = function fabricUndo() {
    if (!isFabricEnabled()) return legacyDesignerApi.undo();
    if (!fabricHistory.length) return;
    fabricRedoHistory.push(fabricSnapshot());
    restoreFabricSnapshot(fabricHistory.pop());
  };
  redo = function fabricRedo() {
    if (!isFabricEnabled()) return legacyDesignerApi.redo();
    if (!fabricRedoHistory.length) return;
    fabricHistory.push(fabricSnapshot());
    restoreFabricSnapshot(fabricRedoHistory.pop());
  };
  loadFabricCanvasState(designerState.finger);
  renderFabricDesigner();
  showToast(lang === "zh" ? "Fabric画板已接入。" : "Fabric canvas enabled.");
}

document.addEventListener("click", (event) => {
  if (!isFabricEnabled()) return;
  const layerMenu = event.target.closest("[data-layer-menu]");
  if (layerMenu) {
    event.stopImmediatePropagation();
    const layerId = layerMenu.dataset.layerMenu;
    openLayerMenuFor = openLayerMenuFor === layerId ? null : layerId;
    if (openLayerMenuFor !== layerId) openLayerOpacityFor = null;
    renderFabricLayerList();
    return;
  }
  const layerToggle = event.target.closest("[data-layer-toggle]");
  if (layerToggle) {
    event.stopImmediatePropagation();
    setFabricLayerVisibility(layerToggle.dataset.layerToggle);
    return;
  }
  const layerOpacity = event.target.closest("[data-layer-opacity]");
  if (layerOpacity) {
    event.stopImmediatePropagation();
    setFabricLayerOpacity(layerOpacity.dataset.layerOpacity);
    return;
  }
  const layerDelete = event.target.closest("[data-layer-delete]");
  if (layerDelete) {
    event.stopImmediatePropagation();
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    deleteFabricLayer(layerDelete.dataset.layerDelete);
    return;
  }
  const layerDuplicate = event.target.closest("[data-layer-duplicate]");
  if (layerDuplicate) {
    event.stopImmediatePropagation();
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    duplicateFabricLayer(layerDuplicate.dataset.layerDuplicate);
    return;
  }
  const layerMergeDown = event.target.closest("[data-layer-merge-down]");
  if (layerMergeDown) {
    event.stopImmediatePropagation();
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    mergeFabricLayerDown(layerMergeDown.dataset.layerMergeDown, false);
    return;
  }
  const layerMergeAll = event.target.closest("[data-layer-merge-all]");
  if (layerMergeAll) {
    event.stopImmediatePropagation();
    openLayerMenuFor = null;
    openLayerOpacityFor = null;
    mergeFabricLayerDown(layerMergeAll.dataset.layerMergeAll, true);
    return;
  }
  const layerRow = event.target.closest(".layer-row");
  if (layerRow) {
    event.stopImmediatePropagation();
    selectFabricLayer(layerRow.dataset.layerId);
  }
}, true);

$("#brush-size").addEventListener("input", syncFabricBrush);
$("#brush-opacity").addEventListener("input", syncFabricBrush);
$("#gallery-search")?.addEventListener("input", (event) => {
  gallerySearch = event.target.value;
  resetTemplateRenderLimit();
  renderDesigns();
});
$("#community-template-image")?.addEventListener("change", handleCommunityTemplateImageChange);
$("#community-template-form")?.addEventListener("submit", submitCommunityTemplateUpload);
$("#login-form")?.addEventListener("submit", submitLoginForm);
$("#forgot-password-form")?.addEventListener("submit", submitForgotPassword);
$("#template-comment-form")?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const design = renderedTemplateByScope();
  const input = $("#template-comment-input");
  const content = input?.value.trim();
  if (!design || !content) return;
  if (!design.templateId || design.source === "personal") {
    const comments = ensureTemplateComments(design, activeTemplateIndex);
    const newComment = { id: uid("comment"), user: currentAuthUser?.username || "You", text: content, likes: 0, replies: [] };
    if (activeTemplateReplyTargetId) {
      const parent = findTemplateComment(comments, activeTemplateReplyTargetId);
      if (parent) {
        parent.replies = parent.replies || [];
        parent.replies.push(newComment);
      }
    } else {
      comments.push(newComment);
    }
    design.commentsData = comments;
    design.comments = countTemplateComments(comments);
    input.value = "";
    setTemplateReplyTarget(null);
    renderTemplateComments();
    return;
  }
  try {
    const payload = await templateSocialRequest({
      action: "add_comment",
      templateId: design.templateId,
      parentCommentId: activeTemplateReplyTargetId || "",
      content,
    });
    if (!payload?.ok) throw new Error(payload?.error || "Comment failed.");
    design.commentsData = Array.isArray(payload.comments) ? payload.comments : [];
    design.comments = payload.commentCount ?? countTemplateComments(design.commentsData);
    updateCatalogTemplateCounts(design.templateId, { comments: design.comments });
    input.value = "";
    setTemplateReplyTarget(null);
    renderTemplateComments();
    renderDesigns();
  } catch (error) {
    console.warn("[template-comment] backend unavailable", error);
    showToast(lang === "zh" ? "评论发送失败。" : "Comment failed.");
  }
});

window.addEventListener("scroll", updateMemberStickyLabel, { passive: true });
window.addEventListener("resize", updateMemberStickyLabel);
window.addEventListener("load", initFabricDesigner);
if (window.fabric) initFabricDesigner();
